const canvas = document.querySelector("#game-canvas");
// Every frame paints the full playfield black, so the drawing buffer never
// needs browser-page transparency. An opaque buffer avoids unnecessary
// compositing work. Browser power policies can still limit the
// animation callback rate independently of how inexpensive drawing is.
const context = canvas.getContext("2d", {alpha: false});

/** @typedef {{ x: number, y: number }} Vector2 */
/**
 * @typedef {Object} PhysicsBody
 * @property {number} x
 * @property {number} y
 * @property {number} velocityX
 * @property {number} velocityY
 * @property {number} mass
 * @property {number} [radius]
 * @property {number} [momentOfInertia]
 * @property {number} [angularVelocity]
 */
/**
 * @typedef {Object} CollisionManifold
 * @property {Vector2} normal
 * @property {number} penetration
 * @property {Vector2} contactPoint
 */
/**
 * @typedef {Object} ContactResponse
 * @property {number} x Impulse x component received by the second body.
 * @property {number} y Impulse y component received by the second body.
 * @property {number} normalImpulse
 * @property {number} tangentImpulse
 * @property {number} firstAngularImpulse
 * @property {number} secondAngularImpulse
 */

// Keep keyboard control available after the player clicks the play field.
canvas.tabIndex = 0;
// The canvas remains keyboard-focusable, but its native focus ring is a
// distracting one-pixel blue frame around the game arena.
canvas.style.outline = "none";
canvas.addEventListener("pointerdown", () => canvas.focus());
canvas.focus({preventScroll: true});

// All active vessels and rocks are reduced together so the arena gains visual
// breathing room without changing the relative collision language.
const WORLD_BODY_SCALE = 0.72;
// Mass is proportional to area for a uniform body. Because visual and
// collision radii are reduced by WORLD_BODY_SCALE, densities are increased by
// its inverse square so newly generated asteroids retain their original mass.
const WORLD_MASS_COMPENSATION = 1 / WORLD_BODY_SCALE ** 2;
// Mass tuning lives here: Borg pulse mass sets the shared scale, and this
// ratio sets starship pulse mass relative to it. Changing either propagates
// through ship mass, asteroid/cube density, inertia and spark energy budgets.
// The reference phaser mass anchors the original world mass calibration.
const REFERENCE_BULLET_MASS = 10;
// With the derived body masses, a stationary head-on hit spends about 20%
// of a full ship shield. Relative motion and impact angle still affect damage.
const BORG_BULLET_MASS = 108;
const BORG_TO_STARSHIP_BULLET_MASS_RATIO = 8.1;
// Projectile mass is independent of its visual length; the contact solver
// uses it for momentum and kinetic energy.
const BULLET_MASS = BORG_BULLET_MASS / BORG_TO_STARSHIP_BULLET_MASS_RATIO;
const BODY_MASS_COMPENSATION = BULLET_MASS / REFERENCE_BULLET_MASS;
// Fix relative cube density at the current balance. Deriving this from the
// tunable pulse mass as well would scale cube mass twice when pulses change.
const BORG_MASS_MULTIPLIER = 33.2;
// The shield circle is the collision boundary. The saucer and nacelles stay
// inside it at every heading, so the new silhouette preserves familiar handling.
const STARSHIP_RADIUS = 28 * WORLD_BODY_SCALE;
// Support hulls stay readable while giving the player's gold ship priority.
const FRIENDLY_STARSHIP_OPACITY = 0.72;
// Unlit wrecks retain a visible collision silhouette after losing their shields.
const FRIENDLY_WRECK_OPACITY = 0.5;
// Ship mass retains the shared phaser calibration with a 20% hull mass increase.
const STARSHIP_MASS = 1200 * BODY_MASS_COMPENSATION;
// This inertia is only the scale used to convert a collision's angular impulse
// into one immediate heading adjustment; the ship does not retain angular
// velocity or intrinsic angular momentum after the contact.
const STARSHIP_COLLISION_TURN_INERTIA =
    (STARSHIP_MASS * STARSHIP_RADIUS ** 2) / 2;
// Collision turning is intentionally a subtle heading nudge rather than a
// physical spin replacement. The cap prevents a high-speed scrape from
// producing a chaotic turn-around in ordinary play.
const SHIP_COLLISION_TURN_RESPONSE = 0.2;
const MAX_SHIP_COLLISION_TURN_ANGLE = Math.PI / 12;
// Sustained turns retain one full revolution per second, independently from
// one-time collision heading adjustments.
const ROTATION_SPEED = Math.PI * 2;
// Manual steering ramps linearly from rest to full speed in seconds. A 50 ms
// tap turns just 1.8 degrees; holding reaches the familiar rate after 250 ms.
// Releasing stops immediately: this is input sensitivity, not spin inertia.
const MANUAL_TURN_RAMP_DURATION = 0.25;
// Bound simulation and input integration after stalls to avoid large jumps.
const MAX_SIMULATION_STEP = 0.1;
// Movement is deliberately expressed in CSS pixels per second so the game
// behaves the same at different device pixel ratios and display refresh rates.
const MAX_SPEED = 360;
// This is the rate at which the ship gains or loses speed while a throttle key
// is held. Keeping it global makes the handling easy to tune.
const MOVEMENT_RESPONSIVENESS = 480;
// Temporary wall recovery starts at stopping distance plus a short reaction
// buffer, capped at 65% engine speed so reckless approaches can still hit.
const WALL_AVOIDANCE_STOPPING_CAP =
    (MAX_SPEED * 0.65) ** 2 / (2 * MOVEMENT_RESPONSIVENESS);
// A tenth of a second supplies a small speed-scaled clearance for frame entry.
const WALL_AVOIDANCE_REACTION_SECONDS = 0.1;
