/**
 * Integrate manual turning at both keyboard edges and animation steps. This
 * preserves even taps that begin and end between frames, without rounding a
 * tap up to a whole frame. Wall avoidance presses use this same control and ramp;
 * autopilot retains its existing direct turn rate.
 */
class ManualTurnControl {
    #direction = 0;
    #heldTime = 0;
    #previousTime = performance.now();

    /**
     * Integrate the linear speed ramp exactly, including crossing its endpoint.
     * Angular displacement is the area under angular velocity, so splitting an
     * interval across frames or key repeats does not change the resulting turn.
     * @param {number} time Monotonic input timestamp in milliseconds.
     * @returns {number} Signed heading adjustment in radians.
     */
    advance(time) {
        const deltaTime = Math.min(
            Math.max(0, (time - this.#previousTime) / 1000),
            MAX_SIMULATION_STEP,
        );
        this.#previousTime = time;

        if (this.#direction === 0) {
            return 0;
        }

        const rampTime = Math.min(
            deltaTime,
            MANUAL_TURN_RAMP_DURATION - this.#heldTime,
        );
        const rampArea =
            (rampTime * (this.#heldTime + rampTime / 2)) / MANUAL_TURN_RAMP_DURATION;
        this.#heldTime = Math.min(
            MANUAL_TURN_RAMP_DURATION,
            this.#heldTime + deltaTime,
        );
        return (
            this.#direction * ROTATION_SPEED * (rampArea + deltaTime - rampTime)
        );
    }

    /**
     * Finish the old input interval before adopting a new direction. Opposing
     * keys cancel; release or reversal starts the next turn gently. Repeats and
     * pressing another key for the same direction never restart a held ramp.
     * @param {number} direction Net input turn: -1 CCW, 0 stopped, or 1 CW.
     * @param {number} time Monotonic input timestamp in milliseconds.
     * @returns {number} Heading adjustment accrued before this input change.
     */
    setDirection(direction, time) {
        const angle = this.advance(time);
        if (direction !== this.#direction) {
            this.#direction = direction;
            this.#heldTime = 0;
        }
        return angle;
    }

    /**
     * Discard input timing across pause, focus loss, and life changes.
     * @returns {void}
     */
    reset() {
        this.#direction = 0;
        this.#heldTime = 0;
        this.#previousTime = performance.now();
    }
}

const asteroids = [];
const bullets = [];
const sparks = [];
/** @type {BorgCube[]} Live cubes and drifting wrecks in the current field. */
const borgCubes = [];
/** @type {number} One-based field number; victory advances it, defeat retries it. */
let sessionField = 1;
/** @type {number} Starting helper count restored on every retry of this field. */
let fieldStartingHelperCount = 0;

/** @returns {Generator<Asteroid>} Solid bodies, including the drifting wreck. */
function* physicalTargets() {
    yield* asteroids;
    yield* borgCubes;
}

/** @returns {Generator<Asteroid>} Live bodies available for combat targeting. */
function* combatTargets() {
    for (const body of physicalTargets()) {
        if (!(body instanceof BorgCube) || body.alive) yield body;
    }
}

/**
 * @param {Asteroid} target Previously committed body.
 * @returns {boolean} Whether the body remains a live combat target.
 */
function isLiveTarget(target) {
    return (
        asteroids.includes(target) || (borgCubes.includes(target) && target.alive)
    );
}

// Keep only this round's achievements, including through pauses and its result
// screen. Starting any new field clears them; a Set prevents duplicate unlocks.
/** @type {Set<string>} */
const roundAchievements = new Set();
// Asteroids have no health pool: compare the impulse-based impact damage
// delivered directly to them by each weapon in this field. Wall impacts,
// asteroid-to-asteroid contacts, and damage received by the ship do not count.
// Evaluate at victory so an early ram cannot win before later blaster hits.
const fieldAsteroidDamage = {ramming: 0, blasters: 0};

/**
 * Heading dwell and target commitment use simulation time, so pausing cannot
 * acquire a target. Pause and focus loss clear the lock; a new sector also
 * disables assistance. Target centers define the sector and nearest distance.
 */
class AimAssist {
    /** @param {Starship} ship Hull owning this independent target lock. */
    constructor(ship) {
        /** @type {Starship} Hull whose heading and position define acquisition. */
        this.ship = ship;
    }

    enabled = false;
    /** @type {Asteroid | undefined} Currently committed live body. */
    target = undefined;
    heading = undefined;
    dwell = 0;
    lockRemaining = 0;

    /** @returns {void} Discard transient acquisition and lock state. */
    reset() {
        this.target = undefined;
        this.heading = undefined;
        this.dwell = 0;
        this.lockRemaining = 0;
    }

    /** @returns {void} Switch assistance without supplying flight input. */
    toggle() {
        this.enabled = !this.enabled;
        this.reset();
    }

    /**
     * Follow the closest surviving child of the locked body, keeping successive
     * cuts on one lineage instead of acquiring an unrelated nearby asteroid.
     * A child receives the normal minimum commitment even across the sector
     * edge; terminal destruction releases the lock for ordinary acquisition.
     * @param {Asteroid} parent Body replaced by the fragmentation transaction.
     * @param {Asteroid[]} fragments Retained children already added to the field.
     * @returns {void}
     */
    followFragments(parent, fragments) {
        if (!this.enabled || this.target !== parent) return;
        let closest = undefined;
        let closestDistance = Infinity;
        for (const fragment of fragments) {
            const distance =
                (fragment.x - this.ship.x) ** 2 + (fragment.y - this.ship.y) ** 2;
            if (distance < closestDistance) {
                closest = fragment;
                closestDistance = distance;
            }
        }
        if (closest === undefined) {
            this.reset();
            return;
        }
        this.target = closest;
        this.lockRemaining = AIM_ASSIST_MIN_LOCK_SECONDS;
    }

    /**
     * @param {Asteroid} target Candidate body in the current world.
     * @returns {boolean} Whether its center lies in the current nose sector.
     */
    inSector(target) {
        return (
            Math.abs(
                shortestAngleDifference(
                    Math.atan2(target.y - this.ship.y, target.x - this.ship.x),
                    this.ship.angle,
                ),
            ) <= AIM_ASSIST_SECTOR_HALF_ANGLE
        );
    }

    /**
     * @param {number} deltaTime Active simulation seconds since the last step.
     * @returns {void}
     */
    update(deltaTime) {
        if (!this.enabled) return;
        if (this.target !== undefined) {
            this.lockRemaining = Math.max(0, this.lockRemaining - deltaTime);
            if (
                !isLiveTarget(this.target) ||
                (this.lockRemaining <= COLLISION_EPSILON && !this.inSector(this.target))
            ) {
                this.reset();
            } else {
                return;
            }
        }
        if (
            this.heading === undefined ||
            Math.abs(shortestAngleDifference(this.ship.angle, this.heading)) >
            AIM_ASSIST_SECTOR_HALF_ANGLE
        ) {
            this.heading = this.ship.angle;
            this.dwell = 0;
            return;
        }
        this.dwell += deltaTime;
        if (this.dwell + COLLISION_EPSILON < AIM_ASSIST_ACQUIRE_SECONDS) return;
        let closestDistance = Infinity;
        for (const target of combatTargets()) {
            const distance =
                (target.x - this.ship.x) ** 2 + (target.y - this.ship.y) ** 2;
            if (distance < closestDistance && this.inSector(target)) {
                this.target = target;
                closestDistance = distance;
            }
        }
        if (this.target !== undefined) {
            this.lockRemaining = AIM_ASSIST_MIN_LOCK_SECONDS;
        }
        // Once the heading is settled, an entering target can lock immediately.
        this.dwell = Math.min(this.dwell, AIM_ASSIST_ACQUIRE_SECONDS);
    }
}

/**
 * Input producers and tactical commitments are private to one hull. Helpers
 * use the same navigation and weapon policy as the player, with independent
 * locks, escape lanes, reaction clocks, bursts and key sets. Only the player's
 * controller receives DOM keyboard events or supplies the bridge indicators.
 */
class ShipControls {
    manualTurnControl = new ManualTurnControl();
    pressedKeys = new Set();
    manualPressedKeys = new Set();
    autopilotPressedKeys = new Set();
    autoGunnerPressedKeys = new Set();
    wallAvoidancePressedKeys = new Set();
    automatedDesiredAngle = 0;
    /** @type {number | undefined} Release assisted turn input at this heading. */
    turnTargetAngle = undefined;
    autopilotEnabled = false;
    wallAvoidanceActive = false;
    wallAvoidanceEscapeAngle = 0;
    wallAvoidanceDesiredAngle = 0;
    /** @type {Asteroid | undefined} Independent navigation engagement. */
    autopilotTargetLock = undefined;
    autopilotDesiredAngle = 0;
    /** @type {Asteroid | Starship | undefined} Committed avoidance body. */
    autopilotEscapeTarget = undefined;
    autopilotEscapeHeading = 0;
    autopilotEscapeTimeRemaining = 0;
    autopilotTurnDirection = 0;
    autopilotTurnTimeRemaining = 0;
    autopilotTargetLockTimeRemaining = 0;
    autopilotDecisionTime = 0;
    autopilotAttackTimeRemaining = 0;
    autopilotAttackRoll = 1;
    autoGunnerEnabled = false;
    autoGunnerBurstActive = false;
}

/**
 * Identical ships share geometry and tuning, but own their motion, defenses,
 * damage protection and weapon state. Each controller owns independent
 * tactical state; helper controllers can supply input without sharing a hull or
 * weapon cooldown. Destruction is reported to the session by the controller,
 * never by the reusable ship itself.
 * @implements {PhysicsBody}
 */
class Starship {
    /** @type {Asteroid | undefined} Shared fleet assignment for helper navigation. */
    fleetTarget = undefined;
    controls = new ShipControls();
    aimAssist = new AimAssist(this);
    x = 0;
    y = 0;
    angle = -Math.PI / 2;
    velocityX = 0;
    velocityY = 0;
    radius = STARSHIP_RADIUS;
    mass = STARSHIP_MASS;
    shieldState = SHIELD_MAX_STATE;
    hullState = SHIP_MAX_STATE;
    displayedShieldState = SHIELD_MAX_STATE;
    displayedHullState = SHIP_MAX_STATE;
    spawnImmunityRemaining = SHIP_SPAWN_IMMUNITY_SECONDS;
    collisionDamageBudget = COLLISION_DAMAGE_BUDGET_CAP;
    phaserShotCooldown = 0;
    phaserHeat = 0;

    /**
     * @param {number} x Initial center x in CSS pixels.
     * @param {number} y Initial center y in CSS pixels.
     */
    constructor(x, y) {
        this.x = x;
        this.y = y;
    }

    /**
     * Restore a fresh identical hull without invalidating controller references.
     * Defaults come from construction so a new ship and a restarted ship cannot
     * drift apart when a per-ship subsystem is added later.
     * @param {number} x Spawn center x in CSS pixels.
     * @param {number} y Spawn center y in CSS pixels.
     * @param {number} [angle] Initial heading in radians.
     * @returns {void}
     */
    reset(x, y, angle = 0) {
        Object.assign(this, new Starship(x, y));
        this.aimAssist = new AimAssist(this);
        this.angle = angle;
    }

    /**
     * @param {number} width Arena width in CSS pixels.
     * @param {number} height Arena height in CSS pixels.
     * @returns {void} Clamp this shield inside a resized playfield.
     */
    keepInside(width, height) {
        this.x = constrainPosition(this.x, this.radius, width);
        this.y = constrainPosition(this.y, this.radius, height);
    }

    /** @returns {boolean} Whether the hull can still participate in combat. */
    get alive() {
        return this.hullState > COLLISION_EPSILON;
    }

    /**
     * Launch a pulse and apply recoil to its own ship.
     * @returns {void}
     */
    emitBullet() {
        const directionX = Math.cos(this.angle);
        const directionY = Math.sin(this.angle);
        const spawnDistance = STARSHIP_RADIUS + BULLET_HALF_LENGTH;
        const bullet = new Bullet({
            x: this.x + directionX * spawnDistance,
            y: this.y + directionY * spawnDistance,
            angle: this.angle,
        });
        const bulletImpulseX = bullet.mass * bullet.velocityX;
        const bulletImpulseY = bullet.mass * bullet.velocityY;

        // Firing transfers the bullet's launch impulse out of the ship. Applying
        // equal and opposite recoil keeps the ship-plus-bullet total impulse equal
        // to the ship's impulse before firing, while making the nudge visible even
        // when the ship was initially at rest.
        const recoilVelocityX = -bulletImpulseX / STARSHIP_MASS;
        const recoilVelocityY = -bulletImpulseY / STARSHIP_MASS;
        this.velocityX += recoilVelocityX;
        this.velocityY += recoilVelocityY;

        heavyShotSound.playRandom();
        bullets.push(bullet);
    }

    /**
     * Restore this ship's shield during active simulation.
     * @param {number} deltaTime Active simulation seconds.
     * @returns {void}
     */
    regenerateShield(deltaTime) {
        if (!Number.isFinite(deltaTime)) {
            return;
        }

        this.shieldState = Math.min(
            SHIELD_MAX_STATE,
            this.shieldState + SHIELD_REGENERATION_RATE * Math.max(0, deltaTime),
        );
    }

    /**
     * Refill this ship's independent contact protection.
     * @param {number} deltaTime Active simulation seconds.
     * @returns {void}
     */
    refillCollisionDamageBudget(deltaTime) {
        if (!Number.isFinite(deltaTime)) {
            return;
        }

        this.collisionDamageBudget = Math.min(
            COLLISION_DAMAGE_BUDGET_CAP,
            this.collisionDamageBudget +
            Math.max(0, deltaTime) * COLLISION_DAMAGE_BUDGET_REFILL_RATE,
        );
    }

    /**
     * Absorb an impact using the shield charge before contact.
     * @param {number} collisionMomentum Contact impulse magnitude.
     * @returns {void}
     */
    applyCollisionDamage(collisionMomentum) {
        this.applyImpactDamage(collisionMomentum, false);
    }

    /**
     * Apply a discrete weapon hit independently of the scrape protection budget.
     * @param {number} collisionMomentum Projectile contact impulse magnitude.
     * @returns {void}
     */
    applyWeaponDamage(collisionMomentum) {
        this.applyImpactDamage(collisionMomentum, true);
    }

    /**
     * Share shield transmission and spawn protection across all impact sources.
     * Only body and wall contacts consume the replenishing scrape budget;
     * weapon hits neither use nor reduce it, even during a physical collision.
     * @param {number} collisionMomentum Finite, nonnegative contact impulse.
     * @param {boolean} weapon Whether this is a discrete projectile impact.
     * @returns {void}
     */
    applyImpactDamage(collisionMomentum, weapon) {
        if (this.spawnImmunityRemaining > 0) return;
        const safeCollisionMomentum = Number.isFinite(collisionMomentum)
            ? Math.max(0, collisionMomentum)
            : 0;
        const rawImpactDamage = safeCollisionMomentum * COLLISION_DAMAGE_SCALE;
        const impactDamage = weapon
            ? rawImpactDamage
            : Math.min(rawImpactDamage, this.collisionDamageBudget);
        const shieldFraction = this.shieldState / SHIELD_MAX_STATE;
        const transmittedFraction = 1 - shieldFraction;
        const shieldDamage = Math.min(
            this.shieldState,
            impactDamage * SHIELD_DAMAGE_COEFFICIENT,
        );
        const shipDamage = Math.min(
            this.hullState,
            impactDamage * transmittedFraction * SHIP_DAMAGE_COEFFICIENT,
        );

        this.shieldState = Math.max(0, this.shieldState - shieldDamage);
        this.hullState = Math.max(0, this.hullState - shipDamage);
        if (!weapon) {
            this.collisionDamageBudget = Math.max(
                0,
                this.collisionDamageBudget - impactDamage,
            );
        }

        if (this.hullState <= COLLISION_EPSILON) {
            this.hullState = 0;
        }
    }

    /**
     * Apply thrust or braking from a controller's independent held-key set.
     * Turning remains with the controller so manual and automated helm timing
     * can differ without changing the identical ship's acceleration model.
     * @param {Set<string>} keys Effective flight input for this ship.
     * @param {number} deltaTime Bounded simulation step in seconds.
     * @returns {void}
     */
    applyThrottle(keys, deltaTime) {
        if (!Number.isFinite(deltaTime) || deltaTime < 0) return;
        const decelerates = keys.has("ArrowDown") || keys.has("KeyS");
        // Brake wins when manual and automated input sources hold both.
        const accelerates =
            !decelerates && (keys.has("ArrowUp") || keys.has("KeyW"));

        if (accelerates !== decelerates) {
            if (accelerates) {
                const acceleration = MOVEMENT_RESPONSIVENESS * deltaTime;
                this.velocityX += Math.cos(this.angle) * acceleration;
                this.velocityY += Math.sin(this.angle) * acceleration;

                const acceleratedSpeed = Math.hypot(
                    this.velocityX,
                    this.velocityY,
                );

                if (acceleratedSpeed > MAX_SPEED) {
                    const speedRatio = MAX_SPEED / acceleratedSpeed;
                    this.velocityX *= speedRatio;
                    this.velocityY *= speedRatio;
                }
            } else {
                const currentSpeed = Math.hypot(this.velocityX, this.velocityY);

                if (currentSpeed > COLLISION_EPSILON) {
                    const deceleration = Math.min(
                        currentSpeed,
                        MOVEMENT_RESPONSIVENESS * deltaTime,
                    );
                    const speedRatio =
                        (currentSpeed - deceleration) / currentSpeed;
                    this.velocityX *= speedRatio;
                    this.velocityY *= speedRatio;
                }
            }
        }
    }

    /**
     * @param {number} deltaTime Active simulation seconds; pause freezes cooling.
     * @returns {void}
     */
    coolWeapon(deltaTime) {
        if (!Number.isFinite(deltaTime)) return;
        const elapsed = Math.max(0, deltaTime);
        this.phaserShotCooldown = Math.max(
            0,
            this.phaserShotCooldown - elapsed,
        );
        this.phaserHeat = Math.max(
            0,
            this.phaserHeat - PHASER_COOLING_RATE * elapsed,
        );
    }

    /** @returns {void} Fire only while this hull and its weapon are ready. */
    tryFire() {
        if (
            !this.alive ||
            this.phaserHeat >= PHASER_OVERHEAT_THRESHOLD ||
            this.phaserShotCooldown > COLLISION_EPSILON
        )
            return;
        this.emitBullet();
        this.phaserShotCooldown = PHASER_FIRE_INTERVAL;
        this.phaserHeat +=
            PHASER_SHOT_HEAT +
            PHASER_WARM_SHOT_HEAT *
            (this.phaserHeat / PHASER_OVERHEAT_THRESHOLD) ** 2;
    }
}

// Keep the player reference stable across field resets. Fleet membership is
// explicit, while manual input, alarms and session failure belong to the player.
/** @type {Starship[]} Active friendly hulls; the player is always index zero. */
const starships = [new Starship(0, 0)];
// The UI selects one hull; world systems only receive hulls or the fleet.
const playerShip = starships[0];

// The alarm is a transition cue, not a loop: one red alert per ship life.
let redAlertSoundPlayed = false;
let alertLevel = 0;
let alertRecoveryTime = 0;
// Bridge-local history observes only the player's hull and resets each field.
let alertHullLossRate = 0;
let alertPreviousHullState = SHIP_MAX_STATE;
let shipFailureActive = false;
let shipFailureTimeRemaining = 0;
let gameWon = false;
let previousFrameTime = undefined;
let asteroidsGenerated = false;
// Pausing stops simulation time while leaving the render loop alive, so the
// player can inspect a frozen collision result and resume without a time jump.
// Starting paused gives the player the controls before any movement begins.
let gamePaused = true;
let viewportWidth = 0;
let viewportHeight = 0;
const phraseMetricsCache = new Map();
let dangerWallGradients = undefined;
let starfieldPaths = [new Path2D(), new Path2D()];

/**
 * Decode short effects once and mix inexpensive buffer sources. Safari's
 * HTMLAudioElement.play() can synchronously stall physics for 70–260 ms even
 * after preloading or routing media voices through Web Audio. Buffer sources
 * keep that native media-player work out of the simulation altogether.
 * Unavailable audio never prevents play; gestures unlock the shared mixer.
 */
class SoundEffect {
    /**
     * @param {string[]} sources Local audio-file paths for this effect.
     * @param {number} voiceCount Number of overlapping voices for each source.
     */
    constructor(sources, voiceCount) {
        this.voiceCount = voiceCount;
        /** @type {{ buffer: AudioBuffer | null, voices: AudioBufferSourceNode[] }[]} */
        this.variants = sources.map((source) => {
            /** @type {{ buffer: AudioBuffer | null, voices: AudioBufferSourceNode[] }} */
            const variant = {buffer: null, voices: []};
            // Data URLs and decompression work asynchronously on file:// as well as
            // HTTPS. Each variant is decoded only once while the opening help shows.
            void fetch(
                `data:application/gzip;base64,${SOUND_EFFECT_SAMPLES[source]}`,
            )
                .then((response) =>
                    new Response(
                        response.body.pipeThrough(
                            new DecompressionStream("gzip"),
                        ),
                    ).arrayBuffer(),
                )
                .then((bytes) => soundContext.decodeAudioData(bytes))
                .then((buffer) => {
                    variant.buffer = buffer;
                })
                .catch((error) =>
                    console.warn("Sound effect unavailable:", source, error),
                );
            return variant;
        });
    }

    /**
     * Start a random loaded variant, preferring one with a free voice. Replacing
     * its oldest source bounds overlapping audio during a dense collision burst.
     * @returns {void}
     */
    playRandom() {
        // Skip unavailable effects rather than delaying or queuing gameplay sounds.
        if (!soundUnlocked || soundBackgrounded) {
            return;
        }
        if (soundContext.state !== "running") {
            resumeSound();
            return;
        }

        const loadedVariants = this.variants.filter(
            ({buffer}) => buffer !== null,
        );
        const idleVariants = loadedVariants.filter(
            ({voices}) => voices.length < this.voiceCount,
        );
        const availableVariants =
            idleVariants.length > 0 ? idleVariants : loadedVariants;

        if (availableVariants.length === 0) {
            return;
        }

        const variant =
            availableVariants[Math.floor(Math.random() * availableVariants.length)];
        if (variant.voices.length >= this.voiceCount) {
            variant.voices.shift()?.stop();
        }

        // Buffer sources are deliberately single-use; the decoded sample is reused.
        // Node creation and scheduling avoid native media playback/seek round trips.
        const voice = soundContext.createBufferSource();
        voice.buffer = variant.buffer;
        voice.connect(soundContext.destination);
        voice.addEventListener(
            "ended",
            () => {
                const voiceIndex = variant.voices.indexOf(voice);
                if (voiceIndex !== -1) {
                    variant.voices.splice(voiceIndex, 1);
                }
                voice.disconnect();
            },
            {once: true},
        );
        variant.voices.push(voice);
        voice.start();
    }

    /**
     * Discard active voices before replacing their mixer. Decoded samples survive
     * recovery, but old shots and impacts must never replay after waking up.
     * @returns {void}
     */
    stopVoices() {
        for (const variant of this.variants) {
            for (const voice of variant.voices) {
                voice.stop();
                voice.disconnect();
            }
            variant.voices.length = 0;
        }
    }
}

// One context serves all variants; decoding can finish while the opening help
// is visible. Interactive latency suits shots and impacts rather than streams.
let soundContext = new AudioContext({latencyHint: "interactive"});
let soundUnlocked = false;
// A visible window can still be in another app's background. Do not let
// ongoing gameplay restart an output connection deliberately released on blur.
let soundBackgrounded = document.hidden || !document.hasFocus();
/** @type {number | null} */
let soundRecoveryTimer = null;
// Only one replacement is allowed until a gesture or wake event retries, so
// an ongoing system interruption cannot repeatedly create audio contexts.
let soundContextRebuilt = false;

/**
 * Resume interrupted audio and check its clock, including contexts that still
 * report "running" after sleep but no longer process their scheduled sources.
 * One watchdog bounds pending resume promises; gameplay never waits for audio.
 * @returns {void}
 */
function resumeSound() {
    if (!soundUnlocked || soundBackgrounded || document.hidden) {
        return;
    }

    const recoveringContext = soundContext;
    const audioTime = recoveringContext.currentTime;
    if (
        recoveringContext.state !== "running" &&
        recoveringContext.state !== "closed"
    ) {
        void recoveringContext.resume().catch(() => undefined);
    }

    // Resume must run inside a fresh gesture even when a previous attempt's
    // watchdog is pending; only the clock check itself is coalesced.
    if (soundRecoveryTimer !== null) {
        return;
    }

    soundRecoveryTimer = window.setTimeout(() => {
        soundRecoveryTimer = null;
        if (
            soundBackgrounded ||
            document.hidden ||
            soundContext !== recoveringContext
        ) {
            return;
        }
        if (
            recoveringContext.state === "running" &&
            recoveringContext.currentTime > audioTime
        ) {
            soundContextRebuilt = false;
            return;
        }
        if (soundContextRebuilt) {
            return;
        }

        // A stuck resume promise or frozen clock needs a fresh output connection.
        // AudioBuffers are reusable across contexts, so recovery needs no fetch or
        // decoding and leaves the current game and paused-help screen intact.
        soundContextRebuilt = true;
        recoveringContext.removeEventListener("statechange", resumeSound);
        for (const effect of soundEffects) {
            effect.stopVoices();
        }
        soundContext = new AudioContext({latencyHint: "interactive"});
        soundContext.addEventListener("statechange", resumeSound);
        if (recoveringContext.state !== "closed") {
            void recoveringContext.close().catch(() => undefined);
        }
        resumeSound();
    }, SOUND_RECOVERY_CHECK_MILLISECONDS);
}

/**
 * Release background audio explicitly. Safari can otherwise lose its output
 * while still reporting "running" with an advancing clock, even after reload.
 * Discard voices so shots made before switching away never replay on return.
 * @returns {void}
 */
function suspendSound() {
    soundBackgrounded = true;
    window.clearTimeout(soundRecoveryTimer);
    soundRecoveryTimer = null;
    for (const effect of soundEffects) {
        effect.stopVoices();
    }
    if (soundContext.state !== "closed") {
        void soundContext.suspend().catch(() => undefined);
    }
}

/**
 * Reacquire the output on foreground/wake events, including a falsely healthy
 * running context. This lifecycle reset is separate from ordinary key presses
 * so continuous fire never tears down its own output or interrupts its voices.
 * @returns {void}
 */
function recoverSound() {
    if (document.hidden || !document.hasFocus()) {
        suspendSound();
        return;
    }
    soundBackgrounded = false;
    soundContextRebuilt = false;
    if (!soundUnlocked) {
        return;
    }
    const recoveringContext = soundContext;
    if (recoveringContext.state === "running") {
        for (const effect of soundEffects) {
            effect.stopVoices();
        }
        // resume() alone is a no-op for a running context. A complete output cycle
        // addresses WebKit bug 276687; the watchdog still covers a frozen clock.
        void recoveringContext
            .suspend()
            .then(() => {
                if (soundContext === recoveringContext) {
                    resumeSound();
                }
            })
            .catch(() => undefined);
    }
    resumeSound();
}

/**
 * Resume the mixer inside a player gesture, respecting browser autoplay rules.
 * Resume failures remain non-fatal and the next gesture can retry.
 * @returns {void}
 */
function unlockSound() {
    const firstGesture = !soundUnlocked;
    soundUnlocked = true;
    soundBackgrounded = document.hidden;
    soundContextRebuilt = false;
    resumeSound();
    // Reloading a page can inherit Safari's silent output route. Reacquire an
    // already-running mixer once at activation, keeping resume in this gesture.
    if (firstGesture) {
        recoverSound();
    }
}

soundContext.addEventListener("statechange", resumeSound);
canvas.addEventListener("pointerdown", unlockSound);
window.addEventListener("focus", recoverSound);
window.addEventListener("blur", suspendSound);
window.addEventListener("pageshow", recoverSound);
window.addEventListener("pagehide", suspendSound);
document.addEventListener("visibilitychange", recoverSound);

const heavyShotSound = new SoundEffect(
    HEAVY_SHOT_SOUND_SOURCES,
    SOUND_EFFECT_VOICE_COUNT,
);
const empSound = new SoundEffect(EMP_SOUND_SOURCES, SOUND_EFFECT_VOICE_COUNT);
const yellowAlertSound = new SoundEffect([YELLOW_ALERT_SOUND_SOURCE], 1);
const redAlertSound = new SoundEffect([RED_ALERT_SOUND_SOURCE], 1);
const winSound = new SoundEffect([WIN_SOUND_SOURCE], 1);
const defeatSound = new SoundEffect([DEFEAT_SOUND_SOURCE], 1);
const soundEffects = [
    heavyShotSound,
    empSound,
    yellowAlertSound,
    redAlertSound,
    winSound,
    defeatSound,
];

function randomBetween(minimum, maximum) {
    return minimum + Math.random() * (maximum - minimum);
}

/**
 * Sample an integer from an inclusive range.
 * @param {number} minimum Inclusive lower bound.
 * @param {number} maximum Inclusive upper bound.
 * @returns {number}
 */
function randomIntegerBetween(minimum, maximum) {
    return Math.floor(randomBetween(minimum, maximum + 1));
}

/**
 * Sample a safe body-center coordinate inside one viewport extent.
 * @param {number} extent Viewport width or height in CSS pixels.
 * @param {number} radius Body radius in CSS pixels.
 * @returns {number}
 */
function randomCoordinate(extent, radius) {
    const minimum = radius;
    const maximum = extent - radius;

    return maximum <= minimum ? extent / 2 : randomBetween(minimum, maximum);
}

/**
 * Generate ordered perimeter angles for a random convex asteroid polygon.
 * @param {number} vertexCount Number of polygon vertices.
 * @returns {readonly number[]}
 */
function createOrderedAngles(vertexCount) {
    const angles = Array.from({length: vertexCount}, () =>
        randomBetween(0, Math.PI * 2),
    );

    angles.sort((firstAngle, secondAngle) => firstAngle - secondAngle);
    return Object.freeze(angles);
}

/**
 * Convert material density into a readable asteroid color. Lower-density
 * bodies are blue-gray and higher-density bodies become progressively redder.
 * @param {number} density
 * @returns {string}
 */
function asteroidColorForDensity(density) {
    const densityRange = ASTEROID_MAX_DENSITY - ASTEROID_MIN_DENSITY;
    const densityRatio =
        densityRange > 0
            ? Math.max(
                0,
                Math.min(1, (density - ASTEROID_MIN_DENSITY) / densityRange),
            )
            : 0.5;
    const hue =
        ASTEROID_MIN_COLOR_HUE +
        (ASTEROID_MAX_COLOR_HUE - ASTEROID_MIN_COLOR_HUE) * densityRatio;

    return `hsl(${hue} 72% 68%)`;
}

/**
 * A convex planar rigid body whose local polygon is centered on its mass
 * center. Rotation is kept separate from the local vertices so collision axes
 * and the rendered silhouette always describe the same pose.
 * @implements {PhysicsBody}
 */
class Asteroid {
    /**
     * @param {Object} options
     * @param {number} options.radius
     * @param {number[]} [options.angles]
     * @param {Vector2[]} [options.localVertices]
     * @param {number} options.x
     * @param {number} options.y
     * @param {number} options.velocityX
     * @param {number} options.velocityY
     * @param {number} options.density
     * @param {number} [options.rotation]
     * @param {number} [options.angularVelocity]
     * @param {number} [options.additionalMass]
     */
    constructor({
                    radius,
                    angles = [],
                    localVertices,
                    x,
                    y,
                    velocityX,
                    velocityY,
                    density = ASTEROID_DENSITY,
                    rotation = 0,
                    angularVelocity = 0,
                    additionalMass = 0,
                }) {
        const sourceVertices =
            localVertices ??
            angles.map((angle) => ({
                x: Math.cos(angle) * radius,
                y: Math.sin(angle) * radius,
            }));
        const localCenter = polygonCentroid(sourceVertices);

        this.radius = Math.max(
            ...sourceVertices.map((vertex) =>
                Math.hypot(vertex.x - localCenter.x, vertex.y - localCenter.y),
            ),
        );
        this.localVertices = Object.freeze(
            sourceVertices.map((vertex) =>
                Object.freeze({
                    x: vertex.x - localCenter.x,
                    y: vertex.y - localCenter.y,
                }),
            ),
        );
        this.x = x;
        this.y = y;
        this.velocityX = velocityX;
        this.velocityY = velocityY;
        this.density = density;
        // Density is immutable for the lifetime of a body, so its presentation
        // color is likewise immutable and does not need rebuilding every frame.
        this.materialColor = asteroidColorForDensity(density);
        this.rotation = rotation;
        this.angularVelocity = angularVelocity;
        this.worldVertices = this.localVertices.map((vertex) => ({
            x: this.x + vertex.x,
            y: this.y + vertex.y,
        }));
        this.surfaceAreaValue = polygonArea(this.localVertices);
        this.massValue = this.density * this.surfaceAreaValue + additionalMass;
        // A uniform polygon's mass moment of inertia comes directly from its
        // vertices. Scaling the unit-density value by mass/area also treats any
        // absorbed mass as material spread through the fragment, keeping the
        // parallel-axis relationship exact when a parent asteroid is cut.
        this.momentOfInertiaValue =
            this.surfaceAreaValue > COLLISION_EPSILON
                ? polygonMassMomentOfInertia(this.localVertices) *
                (this.massValue / this.surfaceAreaValue)
                : (this.massValue * this.radius ** 2) / 2;
        // Translation does not change edge normals, so cache these axes once per
        // asteroid instead of rebuilding them during every SAT collision test.
        // The cached local axes are rotated into world space whenever the body
        // geometry is refreshed.
        this.localCollisionAxes = polygonAxes(this.localVertices);
        this.collisionAxes = this.localCollisionAxes.map((axis) => ({
            ...axis,
        }));
        this.worldBounds = polygonBounds(this.worldVertices);
        this.geometryX = undefined;
        this.geometryY = undefined;
        this.geometryRotation = undefined;
        this.collisionPolygon();
    }

    get mass() {
        return this.massValue;
    }

    get surfaceArea() {
        return this.surfaceAreaValue;
    }

    get momentOfInertia() {
        return this.momentOfInertiaValue;
    }

    /**
     * Asteroids move freely until they meet a field boundary or another
     * collision body. Rotation is integrated before the wall check so a spinning
     * shoulder can reach a wall even when the center of mass is stationary.
     */
    update(width, height, deltaTime) {
        this.rotation = wrapAngle(
            this.rotation + this.angularVelocity * deltaTime,
        );
        this.x += this.velocityX * deltaTime;
        this.y += this.velocityY * deltaTime;
        resolveAsteroidWallCollisions(this, width, height);
    }

    keepInside(width, height) {
        this.collisionPolygon();
        const bounds = this.worldBounds;
        const bodyWidth = bounds.maximumX - bounds.minimumX;
        const bodyHeight = bounds.maximumY - bounds.minimumY;

        this.x =
            bodyWidth >= width
                ? width / 2
                : this.x +
                (bounds.minimumX < 0
                    ? -bounds.minimumX
                    : bounds.maximumX > width
                        ? width - bounds.maximumX
                        : 0);
        this.y =
            bodyHeight >= height
                ? height / 2
                : this.y +
                (bounds.minimumY < 0
                    ? -bounds.minimumY
                    : bounds.maximumY > height
                        ? height - bounds.maximumY
                        : 0);
        this.collisionPolygon();
    }

    draw() {
        const vertices = this.collisionPolygon();
        const firstVertex = vertices[0];

        context.beginPath();
        context.moveTo(firstVertex.x, firstVertex.y);

        for (let vertexIndex = 1; vertexIndex < vertices.length; vertexIndex += 1) {
            const vertex = vertices[vertexIndex];
            context.lineTo(vertex.x, vertex.y);
        }

        context.closePath();
        context.fillStyle = this.materialColor;
        context.fill();
        context.strokeStyle = LCARS_GOLD;
        context.globalAlpha = 0.72;
        context.lineWidth = 1.5;
        context.stroke();
        context.globalAlpha = 1;
    }

    /**
     * Refresh geometry only when the pose changes. Walls and contact correction
     * can move a body several times in one frame, so compare the actual pose
     * rather than caching by frame number. Rendering then reuses physics data.
     * @returns {Vector2[]} World vertices shared with bounds and contact tests.
     */
    collisionPolygon() {
        if (
            this.geometryX === this.x &&
            this.geometryY === this.y &&
            this.geometryRotation === this.rotation
        ) {
            return this.worldVertices;
        }

        const cosine = Math.cos(this.rotation);
        const sine = Math.sin(this.rotation);

        for (
            let vertexIndex = 0;
            vertexIndex < this.localVertices.length;
            vertexIndex += 1
        ) {
            const localVertex = this.localVertices[vertexIndex];
            const worldVertex = this.worldVertices[vertexIndex];
            worldVertex.x = this.x + localVertex.x * cosine - localVertex.y * sine;
            worldVertex.y = this.y + localVertex.x * sine + localVertex.y * cosine;
        }

        for (
            let axisIndex = 0;
            axisIndex < this.localCollisionAxes.length;
            axisIndex += 1
        ) {
            const localAxis = this.localCollisionAxes[axisIndex];
            const worldAxis = this.collisionAxes[axisIndex];
            worldAxis.x = localAxis.x * cosine - localAxis.y * sine;
            worldAxis.y = localAxis.x * sine + localAxis.y * cosine;
        }

        updatePolygonBounds(this.worldBounds, this.worldVertices);
        this.geometryX = this.x;
        this.geometryY = this.y;
        this.geometryRotation = this.rotation;
        return this.worldVertices;
    }
}

/**
 * An armored machine using the existing convex-body geometry and impulses.
 * The four perimeter faces have shields and recent-fire memory, but share one
 * reinforcement allocation. Presentation belongs to the body, never the HUD.
 */
/**
 * @param {PhysicsBody} origin Body seeking the closest live friendly hull.
 * @returns {Starship | undefined} Opponent, or none when the fleet is destroyed.
 */
function nearestStarship(origin) {
    let nearest = undefined;
    let distance = Infinity;
    for (const ship of starships) {
        if (!ship.alive) continue;
        const squared = (ship.x - origin.x) ** 2 + (ship.y - origin.y) ** 2;
        if (squared < distance) {
            nearest = ship;
            distance = squared;
        }
    }
    return nearest;
}

class BorgCube extends Asteroid {
    /**
     * @param {number} width Arena width in CSS pixels.
     * @param {number} height Arena height in CSS pixels.
     */
    constructor(width, height) {
        const half = Math.min(
            BORG_HALF_SIZE,
            Math.min(width, height) * BORG_ARENA_SIZE_RATIO,
        );
        // Choose the least crowded corner, including player clearance, rather
        // than spawning the machine on top of a ship or an existing rock.
        const inset = half * Math.SQRT2 + 12;
        const positions = [
            {x: inset, y: inset},
            {x: width - inset, y: inset},
            {x: width - inset, y: height - inset},
            {x: inset, y: height - inset},
        ];
        // Add perimeter candidates as the fleet grows; include earlier cubes in
        // clearance so reinforcements spread around the arena instead of stacking.
        const divisions = Math.max(2, Math.ceil(sessionField / 4));
        for (let step = 1; step < divisions; step += 1) {
            const fraction = step / divisions;
            const x = inset + (width - inset * 2) * fraction;
            const y = inset + (height - inset * 2) * fraction;
            positions.push(
                {x, y: inset},
                {x, y: height - inset},
                {x: inset, y},
                {x: width - inset, y},
            );
        }
        let position = positions[0];
        let bestClearance = -Infinity;
        for (const candidate of positions) {
            let clearance = Infinity;
            for (const ship of starships) {
                clearance = Math.min(
                    clearance,
                    Math.hypot(candidate.x - ship.x, candidate.y - ship.y) - ship.radius,
                );
            }
            for (const rock of physicalTargets()) {
                clearance = Math.min(
                    clearance,
                    Math.hypot(candidate.x - rock.x, candidate.y - rock.y) - rock.radius,
                );
            }
            if (clearance > bestClearance) {
                position = candidate;
                bestClearance = clearance;
            }
        }
        super({
            radius: half * Math.SQRT2,
            localVertices: [
                {x: -half, y: -half},
                {x: half, y: -half},
                {x: half, y: half},
                {x: -half, y: half},
            ],
            x: position.x,
            y: position.y,
            velocityX: 0,
            velocityY: 0,
            density: ASTEROID_MAX_DENSITY * BORG_MASS_MULTIPLIER,
            rotation: 0.12,
            angularVelocity: 0.035,
        });
        this.half = half;
        this.hull = BORG_HULL;
        this.faces = Array.from({length: 4}, () => ({
            shield: BORG_FACE_SHIELD,
            adaptation: BORG_FACE_BASE_ALLOCATION,
            burst: 0,
            quiet: 10,
            impact: 0,
            resistance: 0,
            warning: 0,
        }));
        this.scars = [];
        this.time = 0;
        this.recovery = 0;
        this.absorptionPulse = 0;
        this.transferCooldown = 0;
        this.transferPulse = 0;
        /** @type {BorgCube | undefined} Recipient of the visible radiation tether. */
        this.transferTarget = undefined;
        this.engineX = 0;
        this.engineY = 0;
        this.contactBudget = BORG_CONTACT_DAMAGE_CAP;
        this.fireCooldown = BORG_FIRE_INTERVAL;
        this.fireCharge = 0;
        /** @type {Starship | undefined} Assigned starship target under collective tactics. */
        this.targetStarship = undefined;
        this.fireAngle = 0;
        this.muzzleFlash = 0;
        this.wreckTexture = undefined;
        this.texture = this.createTexture();
    }

    /** @returns {boolean} Whether the cube can still attack or receive damage. */
    get alive() {
        return this.hull > 0;
    }

    /**
     * Resize the encounter's physical and visual geometry together. Preserve
     * combat progress and velocity when a window becomes smaller or larger.
     * @param {number} width Arena width in CSS pixels.
     * @param {number} height Arena height in CSS pixels.
     * @returns {void}
     */
    keepInside(width, height) {
        const half = Math.max(
            0.1,
            Math.min(
                BORG_HALF_SIZE,
                Math.min(width, height) * BORG_ARENA_SIZE_RATIO,
            ),
        );
        if (half !== this.half) {
            const ratio = half / this.half;
            this.half = half;
            this.radius = half * Math.SQRT2;
            this.localVertices = Object.freeze(
                this.localVertices.map((vertex) =>
                    Object.freeze({x: vertex.x * ratio, y: vertex.y * ratio}),
                ),
            );
            this.momentOfInertiaValue *= ratio ** 2;
            for (const scar of this.scars) {
                scar.x *= ratio;
                scar.y *= ratio;
                scar.radius *= ratio;
            }
            this.geometryRotation = undefined;
        }
        super.keepInside(width, height);
    }

    /**
     * Bake layered greebles once: raised metal plates, trenches, conduits and
     * green machinery. All relief remains inside the physical square silhouette.
     * @param {boolean} [powered] Whether the machinery's green lights are on.
     * @returns {HTMLCanvasElement} Cached opaque hull skin.
     */
    createTexture(powered = true) {
        const texture = document.createElement("canvas");
        texture.width = BORG_TEXTURE_SIZE;
        texture.height = BORG_TEXTURE_SIZE;
        const skin = texture.getContext("2d");
        skin.fillStyle = "#101a14";
        skin.fillRect(0, 0, texture.width, texture.height);
        for (let row = 0; row < 16; row += 1) {
            for (let column = 0; column < 16; column += 1) {
                const value = (row * 31 + column * 17 + row * column * 7) % 23;
                const x = column * 20 + 2;
                const y = row * 20 + 2;
                const width = 10 + (value % 8);
                const height = 8 + (value % 10);
                skin.fillStyle = value % 3 === 0 ? "#33443a" : "#223128";
                skin.fillRect(x, y, width, height);
                skin.fillStyle = "#526459";
                skin.fillRect(x, y, width, 1);
                skin.fillRect(x, y, 1, height);
                skin.fillStyle = "#050a07";
                skin.fillRect(x + width - 2, y + 2, 2, height - 2);
                skin.fillRect(x + 2, y + height - 2, width - 2, 2);
                if (powered && value % 3 === 0) {
                    skin.fillStyle = value % 2 === 0 ? "#80ef97" : "#368e50";
                    skin.fillRect(x + 3, y + 4, 2, Math.max(2, height - 8));
                    skin.fillRect(x + 7, y + 4, Math.max(2, width - 10), 1);
                }
            }
        }
        skin.strokeStyle = "#020604";
        skin.lineWidth = 6;
        for (const offset of [80, 160, 240]) {
            skin.beginPath();
            skin.moveTo(offset, 0);
            skin.lineTo(offset, offset);
            skin.lineTo(320, offset);
            skin.stroke();
            skin.strokeStyle = "#415c47";
            skin.lineWidth = 1;
            skin.stroke();
            skin.strokeStyle = "#020604";
            skin.lineWidth = 6;
        }
        return texture;
    }

    /**
     * @param {Vector2} point World contact position.
     * @returns {Vector2} Contact in hull-local coordinates.
     */
    localPoint(point) {
        const x = point.x - this.x;
        const y = point.y - this.y;
        const cosine = Math.cos(this.rotation);
        const sine = Math.sin(this.rotation);
        return {x: x * cosine + y * sine, y: -x * sine + y * cosine};
    }

    /**
     * @param {Vector2} point World contact or threat position.
     * @returns {number} Clockwise edge index, starting at the top edge.
     */
    faceAt(point) {
        const local = this.localPoint(point);
        return Math.abs(local.x) > Math.abs(local.y)
            ? local.x > 0
                ? 1
                : 3
            : local.y > 0
                ? 2
                : 0;
    }

    /**
     * Resolve a hit against current routing, then reinforce the attacked face
     * by taking power proportionally from the other faces. Full routing grants
     * phaser immunity even when the face's separate rechargeable buffer is spent.
     * @param {Vector2} point Swept projectile contact in world coordinates.
     * @returns {void}
     */
    hitPhaser(point) {
        if (!this.alive) return;
        const face = this.faces[this.faceAt(point)];
        const resistance =
            face.adaptation +
            (1 - face.adaptation) * face.burst * BORG_BURST_RESISTANCE;
        const damage = BORG_PHASER_DAMAGE * (1 - resistance);
        const absorbed = Math.min(face.shield, damage * BORG_SHIELD_ABSORPTION);
        face.shield -= absorbed;
        face.resistance = resistance;
        face.impact = BORG_IMPACT_SECONDS;
        face.quiet = 0;
        face.burst = Math.min(1, face.burst + BORG_BURST_PER_HIT);
        this.routeFacePower(
            face,
            Math.min(1, face.adaptation + BORG_ADAPTATION_PER_HIT),
        );
        this.damageHull(damage - absorbed, point);
    }

    /**
     * Conserve the full routing budget during reinforcement and quiet recovery.
     * If one face owned all power, share its released power equally; otherwise
     * preserve the other faces' relative allocations. Quiet recovery instead
     * replenishes faces below 25%, including faces left at zero by full routing.
     * Assign the last remainder directly to prevent accumulated rounding drift.
     * @param {BorgCube["faces"][number]} face Face whose allocation changes.
     * @param {number} allocation New allocation in the inclusive range [0, 1].
     * @param {boolean} [equalize] Return released reinforcement toward equal routing.
     * @returns {void}
     */
    routeFacePower(face, allocation, equalize = false) {
        const otherAllocation = this.faces.reduce((sum, other) => {
            if (other === face) return sum;
            return (
                sum +
                (equalize
                    ? Math.max(0, BORG_FACE_BASE_ALLOCATION - other.adaptation)
                    : other.adaptation)
            );
        }, 0);
        const available = equalize
            ? face.adaptation - allocation
            : 1 - allocation;
        face.adaptation = allocation;
        let remaining = available;
        let otherCount = this.faces.length - 1;
        for (const other of this.faces) {
            if (other === face) continue;
            const weight = equalize
                ? Math.max(0, BORG_FACE_BASE_ALLOCATION - other.adaptation)
                : other.adaptation;
            const share =
                otherCount === 1
                    ? remaining
                    : Math.min(
                          remaining,
                          otherAllocation > 0
                              ? available * (weight / otherAllocation)
                              : available / (this.faces.length - 1),
                      );
            other.adaptation = (equalize ? other.adaptation : 0) + share;
            remaining -= share;
            otherCount -= 1;
        }
    }

    /**
     * @param {number} impulse Magnitude of the actual physical contact impulse.
     * @param {Vector2} point Shared contact position in world coordinates.
     * @returns {void}
     */
    hitBody(impulse, point) {
        if (!this.alive || impulse <= COLLISION_EPSILON) return;
        const damage = Math.min(
            this.contactBudget,
            impulse * BORG_IMPULSE_DAMAGE_SCALE,
        );
        this.contactBudget -= damage;
        const face = this.faces[this.faceAt(point)];
        face.shield = Math.max(0, face.shield - damage);
        face.quiet = 0;
        face.impact = BORG_IMPACT_SECONDS;
        face.resistance = 0;
        this.damageHull(damage, point);
    }

    /**
     * Record permanent scars at the event source. Bound the presentation queue;
     * hull damage itself remains authoritative after the scar queue fills.
     * @param {number} damage Nonnegative hull damage after shield absorption.
     * @param {Vector2} point World contact position.
     * @returns {void}
     */
    damageHull(damage, point) {
        if (!this.alive || damage <= 0) return;
        this.hull = Math.max(0, this.hull - damage);
        const local = this.localPoint(point);
        this.scars.push({
            x: Math.max(-this.half + 5, Math.min(this.half - 5, local.x)),
            y: Math.max(-this.half + 5, Math.min(this.half - 5, local.y)),
            radius: Math.min(14, 3 + damage * 0.55),
        });
        if (this.scars.length > BORG_MAX_SCARS) this.scars.shift();
        emitSparksAt(point, damage * SPARK_ENERGY_PER_PARTICLE * 0.8);
        if (!this.alive) {
            // Defeat is a single transition. Keep the body's pose and momentum;
            // only powered systems stop. The wreck is never fragmented or removed.
            this.wreckTexture = this.createTexture(false);
            this.fireCharge = 0;
            this.fireCooldown = 0;
            this.muzzleFlash = 0;
            this.recovery = 0;
            this.engineX = 0;
            this.engineY = 0;
            for (const face of this.faces) {
                face.shield = 0;
                face.adaptation = 0;
                face.burst = 0;
                face.impact = 0;
                face.warning = 0;
            }
            emitSparksAt(
                this,
                MAX_SPARKS_PER_INTERACTION * SPARK_ENERGY_PER_PARTICLE,
            );
            empSound.playRandom();
        }
    }

    /**
     * @param {number} width Arena width in CSS pixels.
     * @param {number} height Arena height in CSS pixels.
     * @param {number} deltaTime Active simulation seconds.
     * @returns {void}
     */
    update(width, height, deltaTime) {
        this.time += deltaTime;
        this.absorptionPulse = Math.max(0, this.absorptionPulse - deltaTime);
        if (!this.alive) {
            // A wreck has no navigation, braking, repair or weapons. Contact and
            // wall impulses are the only things that can change its free motion.
            super.update(width, height, deltaTime);
            return;
        }
        this.contactBudget = Math.min(
            BORG_CONTACT_DAMAGE_CAP,
            this.contactBudget +
            (BORG_CONTACT_DAMAGE_CAP / BORG_CONTACT_BUDGET_SECONDS) * deltaTime,
        );
        for (const face of this.faces) {
            face.quiet += deltaTime;
            face.impact = Math.max(0, face.impact - deltaTime);
            face.warning = Math.max(0, face.warning - deltaTime * 2);
            if (face.quiet > BORG_BURST_QUIET_SECONDS)
                face.burst = Math.max(
                    0,
                    face.burst - BORG_BURST_DECAY * deltaTime,
                );
            // Quiet reinforcement relaxes toward equal routing, returning all
            // released energy to the other faces instead of deleting it.
            if (
                face.quiet > BORG_ADAPTATION_QUIET_SECONDS &&
                face.adaptation > BORG_FACE_BASE_ALLOCATION
            )
                this.routeFacePower(
                    face,
                    Math.max(
                        BORG_FACE_BASE_ALLOCATION,
                        face.adaptation - BORG_ADAPTATION_DECAY * deltaTime,
                    ),
                    true,
                );
        }
        const powerUsed =
            this.faces.reduce(
                (sum, face) => sum + face.adaptation * BORG_REINFORCEMENT_POWER,
                0,
            ) +
            Math.max(...this.faces.map((face) => face.burst)) * BORG_BURST_POWER;
        this.recovery = 0;
        for (const face of this.faces) {
            if (face.quiet > BORG_REPAIR_DELAY && face.shield < BORG_FACE_SHIELD) {
                const repair =
                    BORG_SHIELD_REPAIR_RATE * Math.max(0, 1 - powerUsed) * deltaTime;
                face.shield = Math.min(BORG_FACE_SHIELD, face.shield + repair);
                this.recovery = Math.max(this.recovery, 1 - powerUsed);
            }
        }
        this.navigate(width, height, deltaTime);
        super.update(width, height, deltaTime);
        this.updateWeapon(deltaTime);
    }

    /**
     * Locate a muzzle just outside the actual square, rather than outside its
     * larger bounding circle. Launching clear of the hull needs no owner immunity:
     * a pulse that ricochets back can hit its own source normally.
     * @param {number} [angle] World firing heading in radians.
     * @param {number} [rotation] Hull rotation at the expected launch time.
     * @returns {number} Distance from the center to a clear projectile muzzle.
     */
    muzzleDistance(angle = this.fireAngle, rotation = this.rotation) {
        const localAngle = angle - rotation;
        const surfaceDistance =
            this.half /
            Math.max(
                Math.abs(Math.cos(localAngle)),
                Math.abs(Math.sin(localAngle)),
            );
        return surfaceDistance + BULLET_HALF_LENGTH + BULLET_COLLISION_OFFSET;
    }

    /** @returns {Vector2} World launch position at the committed firing heading. */
    muzzlePosition() {
        const distance = this.muzzleDistance();
        return {
            x: this.x + Math.cos(this.fireAngle) * distance,
            y: this.y + Math.sin(this.fireAngle) * distance,
        };
    }

    /**
     * Lead current linear motion through the remaining charge and projectile
     * flight. Projectiles do not inherit cube velocity, so only the future
     * launch origin uses its motion. Refine the angle-dependent square muzzle
     * with a small bounded iteration instead of duplicating the stable solver.
     * Future thrust, turns and wall bounces remain unknown to the weapon.
     * @param {number} delay Remaining simulation seconds before launch.
     * @returns {number} World heading for an intercept, or a finite direct bearing.
     */
    aimAtTarget(delay) {
        const originX = this.x + this.velocityX * delay;
        const originY = this.y + this.velocityY * delay;
        const targetShip =
            this.targetStarship && this.targetStarship.alive
                ? this.targetStarship
                : nearestStarship(this);
        const recipient = targetShip;
        if (recipient === undefined) return this.rotation;
        const target = {
            x: recipient.x + recipient.velocityX * delay,
            y: recipient.y + recipient.velocityY * delay,
            velocityX: recipient.velocityX,
            velocityY: recipient.velocityY,
        };
        let angle = Math.atan2(target.y - originY, target.x - originX);
        for (let iteration = 0; iteration < 5; iteration += 1) {
            const time = linearInterceptTime(
                this,
                target,
                BULLET_SPEED,
                this.muzzleDistance(
                    angle,
                    this.rotation + this.angularVelocity * delay,
                ),
                originX,
                originY,
            );
            if (time === undefined) break;
            angle = Math.atan2(
                target.y + target.velocityY * time - originY,
                target.x + target.velocityX * time - originX,
            );
        }
        return angle;
    }

    /**
     * Track ballistic lead while charging, then lock a visibly committed shot
     * for the final reaction window. All clocks freeze on pause. Recoil balances
     * the departing projectile's launch impulse.
     * @param {number} deltaTime Active simulation seconds since the last step.
     * @returns {void}
     */
    updateWeapon(deltaTime) {
        if (!this.alive) return;
        this.muzzleFlash = Math.max(0, this.muzzleFlash - deltaTime);
        if (this.fireCharge > 0) {
            const remainingCharge = Math.max(0, this.fireCharge - deltaTime);
            if (this.fireCharge > BORG_AIM_LOCK_SECONDS) {
                this.fireAngle = this.aimAtTarget(remainingCharge);
            }
            this.fireCharge = remainingCharge;
            if (this.fireCharge > 0) return;
            const muzzle = this.muzzlePosition();
            const bullet = new Bullet({
                ...muzzle,
                angle: this.fireAngle,
                mass: BORG_BULLET_MASS,
                lineWidth: BORG_BULLET_LINE_WIDTH,
                source: "borg",
                materialColor: BORG_GREEN,
            });
            applyBodyImpulse(
                this,
                -bullet.mass * bullet.velocityX,
                -bullet.mass * bullet.velocityY,
                muzzle,
            );
            bullets.push(bullet);
            this.muzzleFlash = BORG_MUZZLE_FLASH_SECONDS;
            this.fireCooldown = BORG_FIRE_INTERVAL;
            heavyShotSound.playRandom();
            return;
        }
        this.fireCooldown = Math.max(0, this.fireCooldown - deltaTime);
        if (this.fireCooldown > 0) return;
        // At contact distance the ordinary body collision supplies the threat;
        // avoid spawning a shot inside the ship's shield circle.
        const opponent =
            this.targetStarship && this.targetStarship.alive
                ? this.targetStarship
                : nearestStarship(this);
        if (
            opponent === undefined ||
            Math.hypot(opponent.x - this.x, opponent.y - this.y) <=
                this.radius + STARSHIP_RADIUS + BULLET_HALF_LENGTH
        )
            return;
        this.fireCharge = BORG_FIRE_CHARGE_SECONDS;
        this.fireAngle = this.aimAtTarget(this.fireCharge);
    }

    /**
     * Slow pursuit provides pressure without predicting player movement.
     * Project rocks and collective members (including wrecks) to closest
     * approach and push away from threatened regions.
     * When focusing in a multi-cube group, cubes coordinate encirclement
     * offsets around the target to cut off escape lanes.
     * Engines cannot instantly cancel inertia or dodge a rock already touching.
     * @param {number} width Arena width in CSS pixels.
     * @param {number} height Arena height in CSS pixels.
     * @param {number} deltaTime Active simulation seconds.
     * @returns {void}
     */
    navigate(width, height, deltaTime) {
        const opponent =
            this.targetStarship && this.targetStarship.alive
                ? this.targetStarship
                : nearestStarship(this);
        let pursuitX = (opponent?.x ?? this.x) - this.x;
        let pursuitY = (opponent?.y ?? this.y) - this.y;
        if (opponent !== undefined) {
            const focusGroup = borgCubes.filter(
                (cube) => cube.alive && cube.targetStarship === opponent,
            );
            if (focusGroup.length >= BORG_FOCUS_GROUP_MIN_SIZE) {
                const groupIndex = focusGroup.indexOf(this);
                if (groupIndex >= 0) {
                    const spreadAngle =
                        ((groupIndex - (focusGroup.length - 1) / 2) * Math.PI) /
                        Math.max(2, focusGroup.length);
                    const distanceToTarget = Math.hypot(pursuitX, pursuitY);
                    const baseAngle = Math.atan2(pursuitY, pursuitX);
                    const flankAngle = baseAngle + spreadAngle;
                    const offsetDistance = Math.min(
                        140,
                        distanceToTarget * 0.35,
                    );
                    const targetOffsetX =
                        Math.cos(flankAngle + Math.PI) * offsetDistance;
                    const targetOffsetY =
                        Math.sin(flankAngle + Math.PI) * offsetDistance;
                    pursuitX = opponent.x + targetOffsetX - this.x;
                    pursuitY = opponent.y + targetOffsetY - this.y;
                }
            }
        }
        const pursuit = normalizedVector(pursuitX, pursuitY);
        let steerX = pursuit.x * BORG_PURSUIT_WEIGHT;
        let steerY = pursuit.y * BORG_PURSUIT_WEIGHT;
        for (const rock of physicalTargets()) {
            if (rock === this) continue;
            const x = rock.x - this.x;
            const y = rock.y - this.y;
            const vx = rock.velocityX - this.velocityX;
            const vy = rock.velocityY - this.velocityY;
            const velocitySquared = vx * vx + vy * vy;
            const time =
                velocitySquared > COLLISION_EPSILON
                    ? Math.max(
                        0,
                        Math.min(
                            BORG_AVOIDANCE_LOOKAHEAD,
                            -(x * vx + y * vy) / velocitySquared,
                        ),
                    )
                    : 0;
            const futureX = x + vx * time;
            const futureY = y + vy * time;
            const distance = Math.hypot(futureX, futureY);
            const clearance = this.radius + rock.radius + BORG_AVOIDANCE_MARGIN;
            if (distance >= clearance) continue;
            // Head-on approaches need a lateral escape, not merely reverse thrust.
            const away =
                distance > COLLISION_EPSILON
                    ? normalizedVector(-futureX, -futureY)
                    : normalizedVector(-vy, vx);
            const urgency = (1 - distance / clearance) * 3;
            steerX += away.x * urgency;
            steerY += away.y * urgency;
            this.faces[this.faceAt(rock)].warning = Math.max(
                this.faces[this.faceAt(rock)].warning,
                Math.min(1, urgency),
            );
        }
        const margin = Math.min(BORG_WALL_MARGIN, width * 0.18, height * 0.18);
        const edges = [
            {distance: this.x - this.radius, x: 1, y: 0},
            {distance: width - this.x - this.radius, x: -1, y: 0},
            {distance: this.y - this.radius, x: 0, y: 1},
            {distance: height - this.y - this.radius, x: 0, y: -1},
        ];
        for (const edge of edges) {
            const urgency = Math.max(
                0,
                1 - edge.distance / Math.max(1, margin),
            );
            steerX += edge.x * urgency * 3;
            steerY += edge.y * urgency * 3;
        }
        const strength = Math.min(1, Math.hypot(steerX, steerY));
        const steering = normalizedVector(steerX, steerY);
        this.engineX = steering.x * strength;
        this.engineY = steering.y * strength;
        this.velocityX += this.engineX * BORG_ACCELERATION * deltaTime;
        this.velocityY += this.engineY * BORG_ACCELERATION * deltaTime;
        // Engines brake finite overspeed instead of deleting collision momentum.
        const speed = Math.hypot(this.velocityX, this.velocityY);
        if (speed > BORG_MAX_SPEED) {
            const ratio =
                Math.max(
                    BORG_MAX_SPEED,
                    speed - BORG_ACCELERATION * deltaTime,
                ) / speed;
            this.velocityX *= ratio;
            this.velocityY *= ratio;
        }
        this.angularVelocity = Math.max(
            -BORG_MAX_TURN_SPEED,
            Math.min(BORG_MAX_TURN_SPEED, this.angularVelocity),
        );
    }

    /** @returns {void} Show harmless dissipation without a healing symbol. */
    drawAbsorptionPulse() {
        if (this.absorptionPulse <= 0) return;
        const progress =
            1 - this.absorptionPulse / BORG_ABSORPTION_PULSE_SECONDS;
        const half = this.half * (0.95 - progress * 0.25);
        context.save();
        context.strokeStyle = BORG_GREEN;
        context.globalAlpha = (1 - progress) * 0.25;
        context.lineWidth = 1;
        context.strokeRect(-half, -half, half * 2, half * 2);
        context.restore();
    }

    /** @returns {void} Draw a fading radiation tether in world coordinates. */
    drawTransfer() {
        const target = this.transferTarget;
        if (this.transferPulse <= 0 || !this.alive || !target?.alive) return;
        const remaining = this.transferPulse / BORG_TRANSFER_PULSE_SECONDS;
        const progress = 1 - remaining;
        const opacity = remaining * BORG_TRANSFER_BRIGHTNESS;
        context.save();
        context.lineCap = "round";
        context.strokeStyle = BORG_GREEN;
        context.beginPath();
        context.moveTo(this.x, this.y);
        context.lineTo(target.x, target.y);
        context.lineWidth = BORG_TRANSFER_HALO_WIDTH;
        context.globalAlpha = opacity * 0.25;
        context.stroke();
        context.lineWidth = BORG_TRANSFER_BEAM_WIDTH;
        context.globalAlpha = opacity * 0.85;
        context.stroke();
        context.strokeStyle = "#e6ffe9";
        context.lineWidth = 1.5;
        context.stroke();
        context.fillStyle = "#e6ffe9";
        for (let packet = 0; packet < BORG_TRANSFER_PACKET_COUNT; packet += 1) {
            const fraction =
                (progress * 2 + packet / BORG_TRANSFER_PACKET_COUNT) % 1;
            context.beginPath();
            context.arc(
                this.x + (target.x - this.x) * fraction,
                this.y + (target.y - this.y) * fraction,
                BORG_TRANSFER_PACKET_RADIUS,
                0,
                Math.PI * 2,
            );
            context.fill();
        }
        context.restore();
    }

    /** @returns {void} Draw the powered cube or its intact, unlit wreck. */
    draw() {
        context.save();
        context.translate(this.x, this.y);
        context.rotate(this.rotation);
        const half = this.half;
        context.drawImage(
            this.wreckTexture ?? this.texture,
            -half,
            -half,
            half * 2,
            half * 2,
        );
        // Beveled metal and inset plate seams suggest depth without painting a
        // decorative protrusion outside the collision hull.
        context.strokeStyle = this.alive ? "#71947c" : "#4d5650";
        context.lineWidth = 2;
        context.strokeRect(-half + 1, -half + 1, half * 2 - 2, half * 2 - 2);
        context.strokeStyle = "#020704";
        context.lineWidth = 3;
        context.strokeRect(-half + 6, -half + 6, half * 2 - 12, half * 2 - 12);
        for (const scar of this.scars) {
            context.fillStyle = "#020403";
            context.beginPath();
            context.arc(scar.x, scar.y, scar.radius, 0, Math.PI * 2);
            context.fill();
            context.strokeStyle = "#754e2a";
            context.lineWidth = 1;
            context.stroke();
        }
        this.drawHullDamage();
        if (!this.alive) {
            context.restore();
            return;
        }
        for (let index = 0; index < this.faces.length; index += 1) {
            const face = this.faces[index];
            context.save();
            context.rotate((index * Math.PI) / 2);
            const charge = face.shield / BORG_FACE_SHIELD;
            const edgeHalfLength = Math.max(0, half - 7);
            // A muted rail marks the full range; its luminous center is the
            // fraction routed to this face. Zero routing leaves only the rail.
            context.strokeStyle = BORG_ROUTING_TRACK_COLOR;
            context.lineWidth = BORG_ROUTING_LINE_WIDTH;
            context.beginPath();
            context.moveTo(-edgeHalfLength, -half + 4);
            context.lineTo(edgeHalfLength, -half + 4);
            context.stroke();
            if (face.adaptation > 0) {
                context.strokeStyle = BORG_GREEN;
                context.globalAlpha = BORG_ROUTING_OPACITY;
                context.beginPath();
                context.moveTo(-edgeHalfLength * face.adaptation, -half + 4);
                context.lineTo(edgeHalfLength * face.adaptation, -half + 4);
                context.stroke();
            }
            // Adapted hull machinery remains visible after shield charge is spent;
            // its resistance still affects incoming fire on this face.
            const intensity =
                (0.18 + face.adaptation * 0.8) * (0.3 + charge * 0.7);
            context.strokeStyle = BORG_GREEN;
            context.globalAlpha = intensity;
            context.lineWidth = 1 + face.adaptation * 2;
            // Circuit branches grow with directional allocation. Sustained-fire
            // adaptation adds closely spaced transverse bars on that same face.
            for (
                let branch = 0;
                branch < Math.ceil(face.adaptation * 12);
                branch += 1
            ) {
                const x = -half + 12 + (branch * (half * 2 - 24)) / 12;
                context.beginPath();
                context.moveTo(x, -half + 4);
                context.lineTo(x, -half + 9 + face.adaptation * 13);
                context.lineTo(x + 5, -half + 9 + face.adaptation * 13);
                context.stroke();
            }
            context.globalAlpha = face.burst * 0.6;
            for (let band = 0; band < Math.ceil(face.burst * 4); band += 1) {
                context.strokeRect(
                    -half + 9,
                    -half + 8 + band * 4,
                    half * 2 - 18,
                    2,
                );
            }
            if (face.warning > 0) {
                context.globalAlpha =
                    face.warning * (0.4 + 0.6 * Math.abs(Math.sin(this.time * 9)));
                context.strokeStyle = "#d0ffa0";
                context.lineWidth = 2;
                context.strokeRect(-half + 3, -half + 3, half * 2 - 6, 5);
            }
            if (face.impact > 0) {
                const progress = 1 - face.impact / BORG_IMPACT_SECONDS;
                context.globalAlpha = (1 - progress) * 0.9;
                context.strokeStyle = face.resistance > 0.35 ? BORG_GREEN : LCARS_GOLD;
                context.lineWidth = 1 + (1 - face.resistance) * 3;
                context.beginPath();
                context.ellipse(
                    0,
                    -half + 4,
                    Math.max(1, progress * half),
                    3 + (1 - face.resistance) * progress * 16,
                    0,
                    0,
                    Math.PI * 2,
                );
                context.stroke();
            }
            context.restore();
        }
        if (this.recovery > 0) {
            context.save();
            context.beginPath();
            context.rect(-half + 8, -half + 8, half * 2 - 16, half * 2 - 16);
            context.clip();
            const sweep = ((this.time * 0.45) % 1) * half * 2 - half;
            context.globalAlpha = this.recovery * 0.35;
            context.fillStyle = BORG_GREEN;
            context.fillRect(-half + 8, sweep, half * 2 - 16, 2);
            context.restore();
        }
        this.drawAbsorptionPulse();
        this.drawWeapon();
        // Exhaust is opposite the actual commanded acceleration, so machinery
        // identifies the maneuver that avoids the currently highlighted threat.
        const engine = this.localPoint({
            x: this.x + this.engineX,
            y: this.y + this.engineY,
        });
        const length = Math.hypot(engine.x, engine.y);
        if (length > 0.05) {
            context.rotate(Math.atan2(engine.y, engine.x));
            context.strokeStyle = BORG_GREEN;
            context.globalAlpha = length * 0.65;
            context.lineWidth = 3;
            context.beginPath();
            for (const offset of [-9, 0, 9]) {
                context.moveTo(-half * 0.65, offset);
                context.lineTo(-half * 0.65 + 7 + length * 8, offset);
            }
            context.stroke();
        }
        context.restore();
    }

    /** @returns {void} Draw a committed charge direction and actual muzzle flash. */
    drawWeapon() {
        if (this.fireCharge <= 0 && this.muzzleFlash <= 0) return;
        const muzzle = this.localPoint(this.muzzlePosition());
        const localAngle = this.fireAngle - this.rotation;
        const charge =
            this.fireCharge > 0 ? 1 - this.fireCharge / BORG_FIRE_CHARGE_SECONDS : 1;
        const flash = this.muzzleFlash / BORG_MUZZLE_FLASH_SECONDS;
        context.save();
        context.translate(muzzle.x, muzzle.y);
        context.rotate(localAngle);
        context.globalAlpha = 0.45 + charge * 0.55;
        context.strokeStyle =
            this.fireCharge > 0 && this.fireCharge <= BORG_AIM_LOCK_SECONDS
                ? "#d0ffd7"
                : BORG_GREEN;
        context.lineWidth = 2;
        context.beginPath();
        context.arc(
            -BULLET_HALF_LENGTH,
            0,
            3 + charge * 5 + flash * 4,
            0,
            Math.PI * 2,
        );
        context.stroke();
        context.setLineDash([4, 5]);
        context.globalAlpha = 0.25 + charge * 0.4;
        context.beginPath();
        context.moveTo(0, 0);
        context.lineTo(40 + charge * 28, 0);
        context.stroke();
        context.restore();
    }

    /**
     * Show absolute hull loss across the whole body, not just repeated impact
     * points along one edge. Black trenches widen, warm fissures lengthen, and
     * an increasing share of machinery goes dark. Derive every extent from
     * hull state so capped impact scars and recovered shields cannot erase it.
     * @returns {void}
     */
    drawHullDamage() {
        const damage = Math.max(0, Math.min(1, 1 - this.hull / BORG_HULL));
        if (damage <= 0) return;
        const half = this.half;
        context.save();
        // Damage stays inside the unchanged physical hull; green shield ripples
        // can still play over its rim independently of the damaged structure.
        context.beginPath();
        context.rect(-half, -half, half * 2, half * 2);
        context.clip();
        context.fillStyle = "#000000";
        context.globalAlpha = damage * 0.28;
        context.fillRect(-half, -half, half * 2, half * 2);
        context.globalAlpha = 1;
        const cellSize = (half * 2) / BORG_HULL_DAMAGE_GRID;
        const cellCount = BORG_HULL_DAMAGE_GRID ** 2;
        for (let index = 0; index < cellCount; index += 1) {
            // Seven is coprime to sixteen: failure visits each cell exactly once
            // in a scattered order instead of resembling a left-to-right HUD bar.
            const severity = Math.max(
                0,
                Math.min(1, damage * cellCount - ((index * 7) % cellCount)),
            );
            if (severity <= 0) continue;
            const x =
                -half + (index % BORG_HULL_DAMAGE_GRID) * cellSize + cellSize * 0.12;
            const y =
                -half +
                Math.floor(index / BORG_HULL_DAMAGE_GRID) * cellSize +
                cellSize * 0.12;
            context.globalAlpha = severity;
            context.fillStyle = "#030504";
            // Torn plate edges avoid turning structural damage into neat readouts.
            context.beginPath();
            context.moveTo(x + cellSize * 0.08, y);
            context.lineTo(x + cellSize * 0.48, y + cellSize * 0.04);
            context.lineTo(x + cellSize * 0.76, y);
            context.lineTo(x + cellSize * 0.69, y + cellSize * 0.4);
            context.lineTo(x + cellSize * 0.76, y + cellSize * 0.68);
            context.lineTo(x + cellSize * 0.38, y + cellSize * 0.76);
            context.lineTo(x, y + cellSize * 0.68);
            context.lineTo(x + cellSize * 0.05, y + cellSize * 0.3);
            context.closePath();
            context.fill();
            context.strokeStyle = "#874526";
            context.lineWidth = half * 0.014;
            context.stroke();
            // Exposed internals retain a steady warm glow with restrained flicker;
            // they read as structural failure rather than another green shield.
            context.globalAlpha =
                severity *
                (this.alive ? 0.65 + 0.15 * Math.sin(this.time * 7 + index) : 0.45);
            context.fillStyle = this.alive ? "#ff6737" : "#6b3d28";
            context.fillRect(
                x + cellSize * 0.16,
                y + cellSize * 0.28,
                cellSize * 0.4,
                cellSize * 0.08,
            );
            context.fillStyle = this.alive ? "#ffd28a" : "#856548";
            context.fillRect(
                x + cellSize * 0.38,
                y + cellSize * 0.28,
                cellSize * 0.12,
                cellSize * 0.05,
            );
        }
        context.globalAlpha = 1;
        context.lineJoin = "round";
        context.lineCap = "round";
        for (const route of BORG_HULL_FRACTURES) {
            // A hit immediately reveals a short crack; subsequent hull loss grows
            // its reach continuously, including between plate-failure thresholds.
            const reach = Math.min(
                route.length - 1,
                (0.04 + damage * 0.96) * (route.length - 1),
            );
            const completed = Math.floor(reach);
            context.beginPath();
            context.moveTo(route[0].x * half, route[0].y * half);
            for (let index = 1; index <= completed; index += 1) {
                context.lineTo(route[index].x * half, route[index].y * half);
            }
            if (completed < route.length - 1) {
                const start = route[completed];
                const end = route[completed + 1];
                const fraction = reach - completed;
                context.lineTo(
                    (start.x + (end.x - start.x) * fraction) * half,
                    (start.y + (end.y - start.y) * fraction) * half,
                );
            }
            context.strokeStyle = "#010302";
            context.lineWidth = half * (0.025 + damage * 0.055);
            context.stroke();
            context.strokeStyle = this.alive ? "#b34526" : "#523528";
            context.lineWidth = half * (0.012 + damage * 0.025);
            context.stroke();
            context.strokeStyle = this.alive ? "#ffad61" : "#806349";
            context.lineWidth = half * (0.005 + damage * 0.009);
            context.stroke();
        }
        context.restore();
    }
}

/**
 * Negotiate mutually preferred pairs among available live cubes. The healthiest
 * offers to the least healthy, which requests the healthiest in return. Pairing
 * extremes maximizes the reduction in squared hull dispersion: (a-b)^2 / 2.
 * Exchanges are instantaneous, conserve total hull, and never revive wrecks.
 * Sorting once avoids a quadratic negotiation search; no range restriction
 * makes fleet-wide support independent of arena size and weapon interception.
 * @param {number} deltaTime Active simulation seconds; pause freezes all clocks.
 * @returns {void}
 */
function updateBorgHealthTransfers(deltaTime) {
    for (const cube of borgCubes) {
        cube.transferCooldown = Math.max(0, cube.transferCooldown - deltaTime);
        cube.transferPulse = Math.max(0, cube.transferPulse - deltaTime);
        if (cube.transferPulse === 0) cube.transferTarget = undefined;
    }
    const available = borgCubes
        .filter((cube) => cube.alive && cube.transferCooldown === 0)
        .sort((first, second) => first.hull - second.hull);
    for (
        let low = 0, high = available.length - 1;
        low < high;
        low += 1, high -= 1
    ) {
        const recipient = available[low];
        const donor = available[high];
        if (donor.hull - recipient.hull < BORG_TRANSFER_MIN_DIFFERENCE) break;
        const average = recipient.hull + (donor.hull - recipient.hull) / 2;
        donor.hull = average;
        recipient.hull = average;
        donor.transferCooldown = BORG_TRANSFER_COOLDOWN_SECONDS;
        recipient.transferCooldown = BORG_TRANSFER_COOLDOWN_SECONDS;
        donor.transferTarget = recipient;
        donor.transferPulse = BORG_TRANSFER_PULSE_SECONDS;
    }
}

/** @type {number} Round-robin cursor distributing adaptation across live cubes. */
let borgTacticsCubeIndex = 0;

/**
 * Score one cube's current opportunity using live distance and target reserves.
 * @param {BorgCube} cube Cube considering a target.
 * @param {Starship} target Eligible target.
 * @param {number} arenaDiagonal Positive distance normalization scale.
 * @returns {number} Local tactical value, excluding collective group bonuses.
 */
function scoreBorgTarget(cube, target, arenaDiagonal) {
    const healthRatio =
        ((target.hullState ?? SHIP_MAX_STATE) +
            (target.shieldState ?? SHIELD_MAX_STATE)) /
        (SHIP_MAX_STATE + SHIELD_MAX_STATE);
    return (
        -(Math.hypot(cube.x - target.x, cube.y - target.y) / arenaDiagonal) *
            BORG_FOCUS_DISTANCE_WEIGHT +
        (1 - Math.max(0, Math.min(1, healthRatio))) *
            BORG_FOCUS_VULNERABILITY_WEIGHT +
        (target === playerShip ? BORG_FOCUS_PLAYER_PRIORITY_WEIGHT : 0)
    );
}

/**
 * Value of a single focus group; excessive concentration leaves other threats free.
 * @param {number} count Cubes assigned to the target.
 * @param {number} shipCount Eligible enemy ships.
 * @returns {number} Group contribution to the collective tactical score.
 */
function scoreBorgFocusGroup(count, shipCount) {
    return (
        (count >= BORG_FOCUS_GROUP_MIN_SIZE ? BORG_FOCUS_SYNERGY_BONUS : 0) -
        (shipCount > 1
            ? Math.max(0, count - 3) * BORG_FOCUS_OVERSATURATION_PENALTY
            : 0)
    );
}

/**
 * Adapt one cube's assignment per simulation step rather than searching for a
 * global optimum. Only the two affected groups need rescoring, so work grows
 * linearly with fleet size. Local optima are intentional: Borg adapt gradually.
 * Invalid targets are repaired immediately, including during spawn protection.
 * @param {number} width Arena width in CSS pixels.
 * @param {number} height Arena height in CSS pixels.
 * @returns {void}
 */
function updateBorgFleetTactics(width, height) {
    const state = {index: borgTacticsCubeIndex};
    updateFleetTactics(
        borgCubes.filter((cube) => cube.alive),
        starships.filter(
            (ship) => ship.alive && ship.spawnImmunityRemaining <= 0,
        ),
        state,
        (cube) => cube.targetStarship,
        (cube, target) => {
            cube.targetStarship = target;
        },
        scoreBorgTarget,
        width,
        height,
    );
    borgTacticsCubeIndex = state.index;
}

/**
 * Shared Borg assignment algorithm. Only faction eligibility, target storage,
 * and reserve scoring are adapters; thresholds and every gain calculation stay identical.
 * @template A, T
 * @param {A[]} liveCubes Eligible attackers, in fleet order.
 * @param {T[]} liveShips Eligible targets, in world order.
 * @param {{index: number}} state Independent round-robin cursor.
 * @param {(attacker: A) => T | undefined} getTarget Read an assignment.
 * @param {(attacker: A, target: T | undefined) => void} setTarget Store an assignment.
 * @param {(attacker: A, target: T, diagonal: number) => number} scoreTarget Local opportunity score.
 * @param {number} width Arena width in CSS pixels.
 * @param {number} height Arena height in CSS pixels.
 * @returns {void}
 */
function updateFleetTactics(
    liveCubes,
    liveShips,
    state,
    getTarget,
    setTarget,
    scoreTarget,
    width,
    height,
) {
    /** @type {Map<T, number>} Live assignment counts for each eligible target. */
    const counts = new Map(liveShips.map((ship) => [ship, 0]));
    for (const cube of liveCubes) {
        if (!getTarget(cube) || !counts.has(getTarget(cube))) {
            // Spread emergency replacements across eligible ships. Ordinary
            // adaptation subsequently assembles groups using live opportunities.
            setTarget(
                cube,
                liveShips.length > 0
                    ? liveShips[state.index % liveShips.length]
                    : undefined,
            );
            state.index += 1;
        }
        const assignedTarget = getTarget(cube);
        if (assignedTarget) {
            counts.set(assignedTarget, (counts.get(assignedTarget) ?? 0) + 1);
        }
    }
    if (liveCubes.length === 0 || liveShips.length === 0) {
        state.index = 0;
        return;
    }
    const cube = liveCubes[state.index % liveCubes.length];
    state.index = (state.index + 1) % liveCubes.length;
    const currentTarget = getTarget(cube);
    if (!currentTarget) return;
    const currentCount = counts.get(currentTarget) ?? 0;
    const focusGroupCount = [...counts.values()].filter(
        (count) => count >= BORG_FOCUS_GROUP_MIN_SIZE,
    ).length;
    const arenaDiagonal = Math.max(1, Math.hypot(width, height));
    const currentScore = scoreTarget(cube, currentTarget, arenaDiagonal);
    let bestGain = BORG_FOCUS_HYSTERESIS_BONUS;
    let bestTarget = currentTarget;
    for (const target of liveShips) {
        if (target === currentTarget) continue;
        const targetCount = counts.get(target) ?? 0;
        const nextGroupCount =
            focusGroupCount -
            (currentCount === BORG_FOCUS_GROUP_MIN_SIZE ? 1 : 0) +
            (targetCount === BORG_FOCUS_GROUP_MIN_SIZE - 1 ? 1 : 0);
        const coverageGain =
            liveShips.length > 1 && liveCubes.length >= 4
                ? (Number(nextGroupCount >= 2) - Number(focusGroupCount >= 2)) *
                  BORG_FOCUS_MULTI_GROUP_BONUS
                : 0;
        const gain =
            scoreTarget(cube, target, arenaDiagonal) -
            currentScore +
            scoreBorgFocusGroup(currentCount - 1, liveShips.length) -
            scoreBorgFocusGroup(currentCount, liveShips.length) +
            scoreBorgFocusGroup(targetCount + 1, liveShips.length) -
            scoreBorgFocusGroup(targetCount, liveShips.length) +
            coverageGain;
        if (gain > bestGain) {
            bestGain = gain;
            bestTarget = target;
        }
    }
    setTarget(cube, bestTarget);
}

// Helpers prioritize live Borg cubes, then coordinate asteroid clearing once
// every cube is defeated. The player never inflates automatic group counts.
/** @type {{index: number}} Independent round-robin cursor for helper assignments. */
const starfleetTacticsState = {index: 0};

/**
 * Apply the same distance and vulnerability weights to enemy reserves.
 * @param {Starship} ship Attacking helper.
 * @param {Asteroid} target Live cube or asteroid after the Borg fleet is defeated.
 * @param {number} diagonal Positive arena diagonal.
 * @returns {number} Local opportunity value.
 */
function scoreStarfleetTarget(ship, target, diagonal) {
    // Rocks have no rechargeable reserves; distance and group scoring decide
    // their assignments without inventing a hull-based vulnerability advantage.
    const healthRatio =
        target instanceof BorgCube
            ? (target.hull +
                  target.faces.reduce((sum, face) => sum + face.shield, 0)) /
              (BORG_HULL + 4 * BORG_FACE_SHIELD)
            : 1;
    return (
        -(Math.hypot(ship.x - target.x, ship.y - target.y) / diagonal) *
            BORG_FOCUS_DISTANCE_WEIGHT +
        (1 - Math.max(0, Math.min(1, healthRatio))) *
            BORG_FOCUS_VULNERABILITY_WEIGHT
    );
}

/**
 * Coordinate helper targets before navigation reads their assignments.
 * @param {number} width Arena width in CSS pixels.
 * @param {number} height Arena height in CSS pixels.
 * @returns {void}
 */
function updateStarfleetTactics(width, height) {
    const liveCubes = borgCubes.filter((cube) => cube.alive);
    updateFleetTactics(
        starships.filter((ship) => ship !== playerShip && ship.alive),
        liveCubes.length > 0 ? liveCubes : asteroids,
        starfleetTacticsState,
        (ship) => ship.fleetTarget,
        (ship, target) => {
            ship.fleetTarget = target;
        },
        scoreStarfleetTarget,
        width,
        height,
    );
}

class Bullet {
    /**
     * @param {Object} options Projectile launch configuration.
     * @param {number} options.x World muzzle x position.
     * @param {number} options.y World muzzle y position.
     * @param {number} options.angle World launch heading in radians.
     * @param {number} [options.speed] Launch speed in CSS pixels per second.
     * @param {number} [options.mass] Positive physical mass retained through ricochets.
     * @param {number} [options.lineWidth] Painted pulse thickness in CSS pixels.
     * @param {"starship"|"borg"} [options.source] Origin for attribution and the Borg zero-ricochet rule.
     * @param {string} [options.materialColor] Launch color retained for the projectile lifetime.
     */
    constructor({
                    x,
                    y,
                    angle,
                    speed = BULLET_SPEED,
                    mass = BULLET_MASS,
                    lineWidth = BULLET_LINE_WIDTH,
                    source = "starship",
                    materialColor = undefined,
                }) {
        this.x = x;
        this.y = y;
        this.angle = angle;
        this.previousX = x;
        this.previousY = y;
        this.velocityX = Math.cos(angle) * speed;
        this.velocityY = Math.sin(angle) * speed;
        this.mass = mass;
        this.lineWidth = lineWidth;
        this.source = source;
        this.reflectionCount = 0;
        this.materialColor = materialColor;
        this.gradient = undefined;
    }

    /**
     * Count a bounce without changing the pulse's launch color or cached paint.
     * @returns {void}
     */
    recordReflection() {
        this.reflectionCount += 1;
    }

    update(deltaTime) {
        this.previousX = this.x;
        this.previousY = this.y;
        this.x += this.velocityX * deltaTime;
        this.y += this.velocityY * deltaTime;
    }

    syncAngle() {
        this.angle = Math.atan2(this.velocityY, this.velocityX);
    }

    /**
     * Reflect from a wall and lose the normal component's dissipated energy.
     * @param {Vector2} normal Wall normal pointing along the incoming travel.
     * @param {number} [bounceCoefficient] Normal restitution coefficient.
     * @returns {void}
     */
    reflect(normal, bounceCoefficient = BOUNCINESS) {
        const normalVelocity =
            this.velocityX * normal.x + this.velocityY * normal.y;

        this.velocityX -= (1 + bounceCoefficient) * normalVelocity * normal.x;
        this.velocityY -= (1 + bounceCoefficient) * normalVelocity * normal.y;
        this.syncAngle();
        this.recordReflection();
    }

    /**
     * Store paint in pulse-local coordinates. Canvas transforms gradients when
     * painting, so motion, rotation and viewport density need no new stops.
     * The cache belongs to the pulse and is released with it. Launch colors
     * remain stable after all contacts so friendly and enemy fire stay distinct.
     * @returns {CanvasGradient} Soft-ended paint for the current material color.
     */
    createGradient() {
        const gradient = context.createLinearGradient(
            -BULLET_HALF_LENGTH,
            0,
            BULLET_HALF_LENGTH,
            0,
        );

        // Transparent ends soften the phaser silhouette; its origin retains
        // the same color even after a ricochet.
        gradient.addColorStop(0, "rgba(0, 0, 0, 0)");
        gradient.addColorStop(0.3, this.materialColor ?? LCARS_AMBER);
        gradient.addColorStop(0.5, this.materialColor ?? LCARS_GOLD);
        gradient.addColorStop(0.7, this.materialColor ?? LCARS_AMBER);
        gradient.addColorStop(1, "rgba(0, 0, 0, 0)");
        return gradient;
    }

    draw() {
        context.save();
        context.translate(this.x, this.y);
        context.rotate(this.angle);
        context.beginPath();
        context.moveTo(-BULLET_HALF_LENGTH, 0);
        context.lineTo(BULLET_HALF_LENGTH, 0);
        context.strokeStyle = this.gradient ??= this.createGradient();
        context.lineWidth = this.lineWidth;
        context.lineCap = "butt";
        context.stroke();
        context.restore();
    }
}

/**
 * A short-lived visual particle emitted by a dissipative contact. Sparks have
 * no collision body and therefore cannot change gameplay state.
 */
class Spark {
    /**
     * @param {Vector2} origin Contact position where the spark begins.
     */
    constructor({x, y}) {
        const direction = randomBetween(0, Math.PI * 2);
        const speed = randomBetween(SPARK_MIN_SPEED, SPARK_MAX_SPEED);

        this.x = x;
        this.y = y;
        this.velocityX = Math.cos(direction) * speed;
        this.velocityY = Math.sin(direction) * speed;
        this.lifetime = randomBetween(SPARK_MIN_LIFETIME, SPARK_MAX_LIFETIME);
        this.lifeRemaining = this.lifetime;
        this.intensity = randomBetween(
            SPARK_MIN_INTENSITY,
            SPARK_MAX_INTENSITY,
        );
    }

    /**
     * Advance the particle and apply only presentation-level drag.
     * @param {number} deltaTime Elapsed real time in seconds.
     * @returns {void}
     */
    update(deltaTime) {
        if (!Number.isFinite(deltaTime)) {
            return;
        }

        const safeDeltaTime = Math.max(0, deltaTime);
        const damping = Math.exp(-SPARK_VELOCITY_DAMPING * safeDeltaTime);
        this.x += this.velocityX * safeDeltaTime;
        this.y += this.velocityY * safeDeltaTime;
        this.velocityX *= damping;
        this.velocityY *= damping;
        this.lifeRemaining -= safeDeltaTime;
    }

    /**
     * @returns {boolean} Whether the particle still has visible lifetime.
     */
    get isAlive() {
        return this.lifeRemaining > 0;
    }

    /**
     * Draw the particle as a small bright core with a soft additive glow.
     * @returns {void}
     */
    draw() {
        const lifeRatio = Math.max(0, this.lifeRemaining / this.lifetime);
        const alpha = this.intensity * lifeRatio ** 2;

        // The caller batches the canvas state for all particles. A translucent
        // outer disc provides a cheap additive glow without per-particle
        // save/restore or shadow-blur rasterization.
        context.globalAlpha = alpha * SPARK_GLOW_ALPHA;
        context.beginPath();
        context.arc(this.x, this.y, SPARK_GLOW_RADIUS, 0, Math.PI * 2);
        context.fill();
        context.globalAlpha = alpha;
        context.beginPath();
        context.arc(this.x, this.y, SPARK_CORE_RADIUS, 0, Math.PI * 2);
        context.fill();
    }
}

/**
 * Create one fully randomized asteroid using the original game composition.
 * @param {number} width Viewport width in CSS pixels.
 * @param {number} height Viewport height in CSS pixels.
 * @returns {Asteroid}
 */
function createAsteroid(width, height) {
    const radius = randomBetween(ASTEROID_MIN_RADIUS, ASTEROID_MAX_RADIUS);
    const vertexCount = randomIntegerBetween(
        ASTEROID_MIN_VERTICES,
        ASTEROID_MAX_VERTICES,
    );
    const direction = randomBetween(0, Math.PI * 2);
    const speed = randomBetween(ASTEROID_MIN_SPEED, ASTEROID_MAX_SPEED);

    return new Asteroid({
        radius,
        angles: createOrderedAngles(vertexCount),
        density: randomBetween(ASTEROID_MIN_DENSITY, ASTEROID_MAX_DENSITY),
        x: randomCoordinate(width, radius),
        y: randomCoordinate(height, radius),
        velocityX: Math.cos(direction) * speed,
        velocityY: Math.sin(direction) * speed,
        rotation: randomBetween(0, Math.PI * 2),
        angularVelocity: randomBetween(
            ASTEROID_MIN_ANGULAR_SPEED,
            ASTEROID_MAX_ANGULAR_SPEED,
        ),
    });
}

/**
 * @param {Vector2[]} vertices
 * @param {number} velocityX
 * @param {number} velocityY
 * @param {number} mass
 * @param {number} density
 * @param {number} [rotation]
 * @param {number} [angularVelocity]
 * @returns {Asteroid}
 */
function createAsteroidFromPolygon(
    vertices,
    velocityX,
    velocityY,
    mass,
    density,
    rotation = 0,
    angularVelocity = 0,
) {
    const center = polygonCentroid(vertices);
    const cosine = Math.cos(rotation);
    const sine = Math.sin(rotation);
    const localVertices = vertices.map((vertex) => ({
        x: (vertex.x - center.x) * cosine + (vertex.y - center.y) * sine,
        y: -(vertex.x - center.x) * sine + (vertex.y - center.y) * cosine,
    }));
    const radius = Math.max(
        ...localVertices.map((vertex) => Math.hypot(vertex.x, vertex.y)),
    );
    const area = polygonArea(vertices);

    return new Asteroid({
        radius,
        localVertices,
        x: center.x,
        y: center.y,
        velocityX,
        velocityY,
        density,
        rotation,
        angularVelocity,
        additionalMass: mass - density * area,
    });
}

/**
 * Measure the phrase with the browser's actual font metrics. Canvas engines
 * do not agree on where `textBaseline = "top"` places Antonio's visible cap
 * height, so centering uses these bounds instead of nominal font pixels.
 * @param {number} fontSize Requested font size in CSS pixels.
 * @returns {{ ascent: number, lineHeight: number, widestLine: number }}
 */
function phraseTextMetrics(fontSize) {
    const cachedMetrics = phraseMetricsCache.get(fontSize);

    if (cachedMetrics !== undefined) {
        return cachedMetrics;
    }

    context.save();
    context.font = `${PHRASE_FONT_WEIGHT} ${fontSize}px ${PHRASE_FONT_FAMILY}`;
    const firstLineMetrics = context.measureText(PHRASE_LINES[0]);
    const widestLine = Math.max(
        ...PHRASE_LINES.concat(PHRASE_ALERT_LINES).map(
            (phraseLine) => context.measureText(phraseLine).width,
        ),
    );
    context.restore();
    const ascent = Number.isFinite(firstLineMetrics.actualBoundingBoxAscent)
        ? firstLineMetrics.actualBoundingBoxAscent
        : fontSize;
    const descent = Number.isFinite(firstLineMetrics.actualBoundingBoxDescent)
        ? firstLineMetrics.actualBoundingBoxDescent
        : 0;

    const metrics = {
        ascent,
        lineHeight: Math.max(1, ascent + descent),
        widestLine,
    };
    phraseMetricsCache.set(fontSize, metrics);

    return metrics;
}

// A measurement made before Antonio finishes loading uses the fallback font.
// Invalidate that small cache once fonts settle so the next frame reproduces
// the same final layout as measuring on every frame did.
void document.fonts.ready.then(() => phraseMetricsCache.clear());

/**
 * Choose one scale that keeps the background phrase inside the viewport.
 * @param {number} width Viewport width in CSS pixels.
 * @param {number} height Viewport height in CSS pixels.
 * @returns {number}
 */
function phraseFontSizeForViewport(width, height) {
    const availableWidth = Math.max(0, width - PHRASE_MARGIN * 2);
    const availableHeight = Math.max(0, height - PHRASE_MARGIN * 2);
    const baseMetrics = phraseTextMetrics(PHRASE_BASE_FONT_SIZE);
    const lineCount = PHRASE_LINES.length + Number(alertLevel > 0);

    return Math.max(
        1,
        Math.min(
            PHRASE_BASE_FONT_SIZE,
            (PHRASE_BASE_FONT_SIZE * availableWidth) / baseMetrics.widestLine,
            (PHRASE_BASE_FONT_SIZE *
                Math.max(
                    0,
                    availableHeight - PHRASE_LINE_GAP * (lineCount - 1),
                )) /
            baseMetrics.lineHeight,
        ),
    );
}

function generateAsteroids(width, height) {
    if (asteroidsGenerated || width <= 0 || height <= 0) {
        return;
    }

    const asteroidCount = Math.max(
        1,
        ASTEROID_BASE_COUNT - sessionField * ASTEROID_COUNT_PER_BORG,
    );
    asteroids.push(
        ...Array.from({length: asteroidCount}, () =>
            createAsteroid(width, height),
        ),
    );
    for (
        let index = 0;
        index < reinforcementCountForField(sessionField);
        index += 1
    ) {
        borgCubes.push(new BorgCube(width, height));
    }
    asteroidsGenerated = true;
}

/**
 * Return the Borg cube count for a field. The first round teaches asteroid
 * combat alone; later rounds add one cube regardless of friendly losses.
 * @param {number} field One-based session field number.
 * @returns {number} Number of cubes.
 */
function reinforcementCountForField(field) {
    if (!Number.isFinite(field) || field < 1) {
        return 0;
    }
    return Math.max(0, field - 1);
}

/**
 * Rebuild repaired survivors plus one reinforcement after victory; defeat
 * restores the field's starting fleet. Only the survivor count carries over
 * to the next field. Helpers use the
 * same ordinary autopilot and weapon gates as the player, but their input is
 * never exposed to DOM controls. Keeping the player at index zero preserves
 * all bridge, alert, and keyboard references across field transitions.
 * @param {number} width Arena width in CSS pixels.
 * @param {number} height Arena height in CSS pixels.
 * @returns {void}
 */
function configureHelpingFleet(width, height) {
    const helperCount = gameWon
        ? starships.filter((ship) => ship !== playerShip && ship.alive).length + 1
        : fieldStartingHelperCount;
    fieldStartingHelperCount = helperCount;
    starships.length = 1;

    for (let helperIndex = 0; helperIndex < helperCount; helperIndex += 1) {
        starships.push(new Starship(0, 0));
    }

    const centerX = width / 2;
    const centerY = height / 2;
    const safeDistance = Math.min(
        HELPER_SPAWN_DISTANCE,
        Math.max(0, Math.min(width, height) / 2 - STARSHIP_RADIUS),
    );

    playerShip.reset(centerX, centerY);
    clearPressedKeys(playerShip);

    for (let helperIndex = 0; helperIndex < helperCount; helperIndex += 1) {
        const helper = starships[helperIndex + 1];
        const angle =
            -Math.PI / 2 + (helperIndex * Math.PI * 2) / Math.max(1, helperCount);
        helper.reset(
            constrainPosition(
                centerX + Math.cos(angle) * safeDistance,
                helper.radius,
                width,
            ),
            constrainPosition(
                centerY + Math.sin(angle) * safeDistance,
                helper.radius,
                height,
            ),
            wrapAngle(angle + Math.PI),
        );
        helper.controls.autopilotEnabled = true;
        helper.controls.autoGunnerEnabled = true;
        syncPressedKeys(helper);
    }
}

function updateBullets(deltaTime) {
    for (
        let bulletIndex = bullets.length - 1;
        bulletIndex >= 0;
        bulletIndex -= 1
    ) {
        const bullet = bullets[bulletIndex];
        bullet.update(deltaTime);
    }
}

/**
 * Advance and prune sparks independently from the gameplay simulation. This
 * lets an impact finish its visual fade while the player is reading a pause
 * or failure screen without giving the particles any gameplay influence.
 * @param {number} deltaTime Elapsed real time in seconds.
 * @returns {void}
 */
function updateSparks(deltaTime) {
    // Compact in place while preserving paint order. Repeated splice calls
    // shift the remaining array for every expired particle in a contact burst.
    let aliveCount = 0;
    for (let sparkIndex = 0; sparkIndex < sparks.length; sparkIndex += 1) {
        const spark = sparks[sparkIndex];
        spark.update(deltaTime);

        if (spark.isAlive) {
            sparks[aliveCount] = spark;
            aliveCount += 1;
        }
    }
    sparks.length = aliveCount;
}

/**
 * Rebuild the effective held-key state from its independent input producers.
 * Keeping manual and autopilot keys separate lets a human input disable the
 * autopilot without allowing one producer to forge the other producer's
 * events. Settle manual turn timing at each edge; the combined held-key set
 * supplies thrust, braking, rotation, firing, and command-strip highlights.
 * Wall avoidance is an independent key producer with priority over autopilot helm.
 * @param {Starship} ship Hull and independent controller being operated.
 * @returns {void}
 */
function syncPressedKeys(ship) {
    const time = performance.now();
    applyTurnInput(ship, ship.controls.manualTurnControl.advance(time));
    const controls = ship.controls;
    controls.pressedKeys.clear();
    const steeringKeys = ["KeyA", "KeyD", "ArrowLeft", "ArrowRight"];
    const manuallySteering = steeringKeys.some((key) =>
        controls.manualPressedKeys.has(key),
    );
    const automatedInput = controls.wallAvoidanceActive
        ? controls.wallAvoidancePressedKeys
        : controls.autopilotPressedKeys;
    controls.automatedDesiredAngle = controls.wallAvoidanceActive
        ? controls.wallAvoidanceDesiredAngle
        : controls.autopilotDesiredAngle;
    for (const input of [
        controls.manualPressedKeys,
        controls.autopilotPressedKeys,
        controls.autoGunnerPressedKeys,
        controls.wallAvoidancePressedKeys,
    ]) {
        for (const key of input) {
            if (
                controls.wallAvoidanceActive &&
                input !== controls.wallAvoidancePressedKeys &&
                ["KeyW", "KeyS", "ArrowUp", "ArrowDown"].includes(key)
            )
                continue;
            // Only the winning helm producer supplies turn keys. Brake and
            // thrust remain ordinary merged inputs; braking takes priority.
            if (
                steeringKeys.includes(key) &&
                input !== controls.manualPressedKeys &&
                (manuallySteering || input !== automatedInput)
            )
                continue;
            controls.pressedKeys.add(key);
        }
    }
    controls.turnTargetAngle =
        !manuallySteering && controls.wallAvoidanceActive
            ? controls.wallAvoidanceDesiredAngle
            : undefined;
    controls.manualTurnControl.setDirection(
        manuallySteering || controls.wallAvoidanceActive
            ? turnDirectionForKeys(controls.pressedKeys)
            : 0,
        time,
    );
}

/**
 * Clear all input sources. This is used for pause, focus loss, and life
 * transitions so no stale held key can survive a state boundary.
 * @param {Starship} ship Hull and independent controller being operated.
 * @returns {void}
 */
function clearPressedKeys(ship) {
    ship.controls.autopilotTurnDirection = 0;
    ship.controls.autopilotTurnTimeRemaining = AUTOPILOT_TURN_REACTION_SECONDS;
    ship.controls.manualTurnControl.reset();
    ship.aimAssist.reset();
    ship.controls.manualPressedKeys.clear();
    ship.controls.autopilotPressedKeys.clear();
    ship.controls.autoGunnerPressedKeys.clear();
    ship.controls.wallAvoidancePressedKeys.clear();
    ship.controls.wallAvoidanceActive = false;
    ship.controls.turnTargetAngle = undefined;
    ship.controls.pressedKeys.clear();
}

/**
 * Return the corresponding automated control to the player.
 * @param {Starship} ship Hull and independent controller being operated.
 * @param {string} controlKey Manual flight or firing control supplied.
 * @returns {void}
 */
function disableAutomationForManualInput(ship, controlKey) {
    // Manual helm overrides only piloting; manual fire overrides only gunnery.
    // This lets the player fly with automatic shots or fire during autopilot.
    if (controlKey === FIRE_KEY) {
        ship.controls.autoGunnerEnabled = false;
        ship.controls.autoGunnerBurstActive = false;
        ship.controls.autoGunnerPressedKeys.clear();
    } else {
        ship.controls.autopilotEnabled = false;
        ship.controls.autopilotPressedKeys.clear();
    }
    syncPressedKeys(ship);
}

/**
 * Toggle autopilot and reset the flight input edge state. T itself is a mode
 * control, not one of the simulated gameplay inputs, so it is never added to
 * either held-key set.
 * @param {Starship} ship Hull and independent controller being operated.
 * @returns {void}
 */
function toggleAutopilot(ship) {
    ship.controls.autopilotEnabled = !ship.controls.autopilotEnabled;
    ship.controls.autopilotDesiredAngle = ship.angle;
    ship.controls.autopilotTargetLock = undefined;
    ship.controls.autopilotEscapeTarget = undefined;
    ship.controls.autopilotTargetLockTimeRemaining = 0;
    ship.controls.autopilotAttackTimeRemaining = 0;
    ship.controls.autopilotAttackRoll = 1;
    ship.controls.autopilotDecisionTime = ship.controls.autopilotEnabled
        ? AUTOPILOT_UPDATE_INTERVAL
        : 0;
    ship.controls.autopilotTurnDirection = 0;
    ship.controls.autopilotTurnTimeRemaining = AUTOPILOT_TURN_REACTION_SECONDS;
    ship.controls.manualTurnControl.reset();
    ship.aimAssist.reset();
    for (const key of ship.controls.manualPressedKeys) {
        if (key !== FIRE_KEY) ship.controls.manualPressedKeys.delete(key);
    }
    ship.controls.autopilotPressedKeys.clear();
    syncPressedKeys(ship);
}

/**
 * Toggle automatic firing without changing helm or manual input state.
 * @param {Starship} ship Hull and independent controller being operated.
 * @returns {void}
 */
function toggleAutoGunner(ship) {
    ship.controls.autoGunnerEnabled = !ship.controls.autoGunnerEnabled;
    ship.controls.autoGunnerBurstActive = false;
    ship.controls.autoGunnerPressedKeys.clear();
    syncPressedKeys(ship);
}

/**
 * Supply the autopilot's current held controls through the same set consumed
 * by normal movement and firing. No ship, asteroid, health, or bullet state
 * is changed here.
 * @param {Starship} ship Hull and independent controller being operated.
 * @param {Iterable<string>} keys W/A/S/D flight controls to hold.
 * @returns {void}
 */
function setAutopilotInput(ship, keys) {
    ship.controls.autopilotPressedKeys.clear();

    if (ship.controls.autopilotEnabled && !shipFailureActive && !gameWon) {
        for (const key of keys) {
            ship.controls.autopilotPressedKeys.add(key);
        }
    }

    syncPressedKeys(ship);
}

/**
 * Return the signed shortest turn from the current angle to a desired angle.
 * Positive values correspond to the existing clockwise D input.
 * @param {number} desiredAngle
 * @param {number} currentAngle
 * @returns {number}
 */
function shortestAngleDifference(desiredAngle, currentAngle) {
    const fullTurn = Math.PI * 2;
    return (
        ((((desiredAngle - currentAngle + Math.PI) % fullTurn) + fullTurn) %
            fullTurn) -
        Math.PI
    );
}

/**
 * Convert current shield and hull state into extra avoidance distance. A full
 * shield is intentionally treated as a renewable buffer: only shield below
 * the recovery threshold adds caution, while hull damage always adds caution.
 * @param {Starship} ship Hull and independent controller being operated.
 * @returns {number} Additional safe distance in CSS pixels.
 */
function autopilotHealthSafetyMargin(ship) {
    const shieldRatio = Math.max(
        0,
        Math.min(1, ship.shieldState / SHIELD_MAX_STATE),
    );
    const hullRatio = Math.max(0, Math.min(1, ship.hullState / SHIP_MAX_STATE));
    const shieldRecoveryRatio = Math.max(
        0,
        (AUTOPILOT_SHIELD_RECOVERY_THRESHOLD - shieldRatio) /
        AUTOPILOT_SHIELD_RECOVERY_THRESHOLD,
    );
    const hullDamageRatio = 1 - hullRatio;

    return (
        shieldRecoveryRatio * AUTOPILOT_SHIELD_RECOVERY_MARGIN +
        hullDamageRatio * AUTOPILOT_HULL_DAMAGE_MARGIN
    );
}

/**
 * Hold ordinary A/D input through a correction, releasing on alignment or
 * reversal. A short reaction pause between presses and separate start/stop
 * thresholds suppress rapid alternating taps without changing tactical goals.
 * @param {Starship} ship Hull and independent controller being operated.
 * @param {Set<string>} input Controls receiving the steering keys.
 * @param {number} deltaTime Elapsed simulation time in seconds.
 * @returns {void}
 */
function applyAutopilotTurnInput(ship, input, deltaTime) {
    input.delete("KeyA");
    input.delete("KeyD");
    ship.controls.autopilotTurnTimeRemaining = Math.max(
        0,
        ship.controls.autopilotTurnTimeRemaining - Math.max(0, deltaTime),
    );
    const error = shortestAngleDifference(
        ship.controls.autopilotDesiredAngle,
        ship.angle,
    );
    const desiredDirection = Math.sign(error);
    if (
        ship.controls.autopilotTurnDirection !== 0 &&
        (Math.abs(error) <= AUTOPILOT_TURN_STOP_TOLERANCE ||
            desiredDirection !== ship.controls.autopilotTurnDirection)
    ) {
        ship.controls.autopilotTurnDirection = 0;
        ship.controls.autopilotTurnTimeRemaining = AUTOPILOT_TURN_REACTION_SECONDS;
    } else if (
        ship.controls.autopilotTurnDirection === 0 &&
        ship.controls.autopilotTurnTimeRemaining === 0 &&
        Math.abs(error) > AUTOPILOT_TURN_START_TOLERANCE
    ) {
        ship.controls.autopilotTurnDirection = desiredDirection;
    }
    if (ship.controls.autopilotTurnDirection !== 0) {
        input.add(ship.controls.autopilotTurnDirection > 0 ? "KeyD" : "KeyA");
    }
}

/**
 * Solve a linear interception for either a world-speed projectile or an
 * attacking ship. Bullets do not inherit the source's velocity. The launch/contact
 * offset avoids over-leading close targets; stable roots avoid cancellation.
 * Constant-velocity kinematics: https://en.wikipedia.org/wiki/Equations_of_motion
 * Solve |r + v*t| = launchOffset + approachSpeed*t. No future collision,
 * wall bounce, target rotation, or ship movement is predicted.
 * Unreachable targets have no marker rather than an incorrect firing cue.
 * @param {Pick<PhysicsBody, "x"|"y">} origin Firing hull; never an implicit player origin.
 * @param {Pick<PhysicsBody, "x"|"y"|"velocityX"|"velocityY">} target Moving target in world coordinates.
 * @param {number} [approachSpeed] Projectile or desired ship speed in pixels/second.
 * @param {number} [launchOffset] Muzzle offset or combined ram-contact radii.
 * @param {number} [originX] Launch origin x position, defaulting to the firing hull.
 * @param {number} [originY] Launch origin y position, defaulting to the firing hull.
 * @returns {number | undefined} Earliest nonnegative interception time in seconds.
 */
function linearInterceptTime(
    origin,
    target,
    approachSpeed = BULLET_SPEED,
    launchOffset = STARSHIP_RADIUS + BULLET_HALF_LENGTH,
    originX = origin.x,
    originY = origin.y,
) {
    const x = target.x - originX;
    const y = target.y - originY;
    const muzzle = launchOffset;
    const a = target.velocityX ** 2 + target.velocityY ** 2 - approachSpeed ** 2;
    const b =
        2 * (x * target.velocityX + y * target.velocityY - muzzle * approachSpeed);
    const c = x ** 2 + y ** 2 - muzzle ** 2;
    let time = 0;
    if (c > 0) {
        if (Math.abs(a) <= COLLISION_EPSILON) {
            time = Math.abs(b) > COLLISION_EPSILON ? -c / b : Infinity;
        } else {
            const discriminant = b ** 2 - 4 * a * c;
            time = Infinity;
            if (discriminant >= 0) {
                const q = -0.5 * (b + (b >= 0 ? 1 : -1) * Math.sqrt(discriminant));
                const first = q / a;
                const second = Math.abs(q) > COLLISION_EPSILON ? c / q : -1;
                time = Math.min(
                    first > 0 ? first : Infinity,
                    second > 0 ? second : Infinity,
                );
            }
        }
    }
    return Number.isFinite(time) && time >= 0 ? time : undefined;
}

/**
 * Retain autopilot's bounded lookahead and current-bearing fallback.
 * @param {Starship} ship Hull and independent controller being operated.
 * @param {Asteroid} asteroid Moving target read from the world.
 * @param {number} approachSpeed Projectile or ship speed in CSS pixels/second.
 * @param {number} launchOffset Muzzle or ram-contact offset in CSS pixels.
 * @returns {number} World-space firing heading in radians.
 */
function autopilotAimAngle(
    ship,
    asteroid,
    approachSpeed = BULLET_SPEED,
    launchOffset = STARSHIP_RADIUS + BULLET_HALF_LENGTH,
) {
    const interceptTime = linearInterceptTime(
        ship,
        asteroid,
        approachSpeed,
        launchOffset,
    );
    const time =
        interceptTime !== undefined &&
        interceptTime <= AUTOPILOT_MAX_LOOKAHEAD_SECONDS
            ? interceptTime
            : 0;
    return Math.atan2(
        asteroid.y - ship.y + asteroid.velocityY * time,
        asteroid.x - ship.x + asteroid.velocityX * time,
    );
}

/**
 * Prefer a nearby, large target that needs little nose rotation. Momentum no
 * longer dictates which direction to aim: braking can preserve an engagement
 * without thrusting back and forth through it.
 * @param {Starship} ship Hull and independent controller being operated.
 * @param {Asteroid} asteroid Candidate read from the world.
 * @returns {number} Lower scores are easier engagements.
 */
function autopilotTargetScore(ship, asteroid) {
    const distance = Math.hypot(asteroid.x - ship.x, asteroid.y - ship.y);
    const turn = Math.abs(
        shortestAngleDifference(autopilotAimAngle(ship, asteroid), ship.angle),
    );
    return (
        distance +
        turn * AUTOPILOT_TARGET_TURN_COST -
        asteroid.radius * AUTOPILOT_TARGET_SIZE_WEIGHT
    );
}

/**
 * Hold an engagement through small score changes; release destroyed targets
 * immediately. Endgame uses the same policy rather than an infinite lock.
 * @param {Starship} ship Hull and independent controller being operated.
 * @param {number} deltaTime Seconds since the previous navigation decision.
 * @returns {Asteroid | undefined} Selected aiming and positioning target.
 */
function autopilotTarget(ship, deltaTime) {
    // Fleet assignments enforce Borg priority and replace destroyed rocks.
    if (ship !== playerShip) {
        return ship.fleetTarget && isLiveTarget(ship.fleetTarget)
            ? ship.fleetTarget
            : undefined;
    }
    ship.controls.autopilotTargetLockTimeRemaining = Math.max(
        0,
        ship.controls.autopilotTargetLockTimeRemaining - deltaTime,
    );
    const lockedTargetIsPresent =
        ship.controls.autopilotTargetLock !== undefined &&
        isLiveTarget(ship.controls.autopilotTargetLock);
    if (
        lockedTargetIsPresent &&
        ship.controls.autopilotTargetLockTimeRemaining > 0
    ) {
        return ship.controls.autopilotTargetLock;
    }
    let selectedAsteroid = undefined;
    let selectedScore = Infinity;
    for (const asteroid of combatTargets()) {
        const score = autopilotTargetScore(ship, asteroid);
        if (score < selectedScore) {
            selectedAsteroid = asteroid;
            selectedScore = score;
        }
    }
    if (
        lockedTargetIsPresent &&
        autopilotTargetScore(ship, ship.controls.autopilotTargetLock) <=
        selectedScore + AUTOPILOT_TARGET_SWITCH_ADVANTAGE
    ) {
        ship.controls.autopilotTargetLockTimeRemaining =
            AUTOPILOT_TARGET_RECHECK_SECONDS;
        return ship.controls.autopilotTargetLock;
    }
    ship.controls.autopilotTargetLock = selectedAsteroid;
    ship.controls.autopilotTargetLockTimeRemaining =
        AUTOPILOT_TARGET_COMMITMENT_SECONDS;
    return selectedAsteroid;
}

/**
 * Test the actual muzzle trajectory against every moving asteroid. This
 * opportunistic shot check is independent of navigation, ship speed, and wall
 * avoidance. Relative-motion closest approach also catches crossing targets
 * that a fixed angular cone would miss or over-lead.
 * @param {Starship} ship Hull and independent controller being operated.
 * @returns {boolean} Whether a direct shot has a useful predicted contact.
 */
function autoGunnerHasShot(ship) {
    const directionX = Math.cos(ship.angle);
    const directionY = Math.sin(ship.angle);
    const muzzle = STARSHIP_RADIUS + BULLET_HALF_LENGTH;
    const helperMustFightBorg =
        ship !== playerShip && borgCubes.some((cube) => cube.alive);
    for (const asteroid of combatTargets()) {
        // Asteroid shots become eligible only after the last live cube falls.
        if (helperMustFightBorg && !(asteroid instanceof BorgCube)) continue;
        const x = asteroid.x - ship.x - directionX * muzzle;
        const y = asteroid.y - ship.y - directionY * muzzle;
        const velocityX = asteroid.velocityX - directionX * BULLET_SPEED;
        const velocityY = asteroid.velocityY - directionY * BULLET_SPEED;
        const velocitySquared = velocityX ** 2 + velocityY ** 2;
        if (velocitySquared <= COLLISION_EPSILON) {
            continue;
        }
        const time = -(x * velocityX + y * velocityY) / velocitySquared;
        if (time < 0 || time > AUTOPILOT_MAX_LOOKAHEAD_SECONDS) {
            continue;
        }
        const clearance =
            asteroid.radius * AUTO_GUNNER_FIRE_RADIUS_RATIO + BULLET_HALF_LENGTH;
        if (
            (x + velocityX * time) ** 2 + (y + velocityY * time) ** 2 <=
            clearance ** 2
        ) {
            return true;
        }
    }
    return false;
}

/**
 * @param {Starship} ship Hull whose own body must be excluded.
 * @yields {Asteroid | Starship} Solid obstacles, including other live helpers.
 */
function* navigationObstacles(ship) {
    yield* physicalTargets();
    for (const other of starships) {
        if (other !== ship && other.alive) yield other;
    }
}

/**
 * Find a solid body's predicted closest approach or incomplete escape.
 * Relative linear motion is enough for a useful warning between frames; the
 * collision solver remains the authority when bodies actually touch.
 * @param {Starship} ship Hull and independent controller being operated.
 * @param {Asteroid} [ramTarget] Intended rock contact to allow during a ram.
 * @returns {{ asteroid: Asteroid | Starship, distance: number,
 *   safeDistance: number } | undefined} Solid body needing avoidance.
 */
function autopilotThreat(ship, ramTarget = undefined) {
    const safeMargin =
        AUTOPILOT_BASE_SAFE_MARGIN + autopilotHealthSafetyMargin(ship);
    let selectedThreat = undefined;
    let selectedScore = Infinity;

    for (const asteroid of navigationObstacles(ship)) {
        if (asteroid === ramTarget) continue;
        const relativeX = asteroid.x - ship.x;
        const relativeY = asteroid.y - ship.y;
        const relativeVelocityX = asteroid.velocityX - ship.velocityX;
        const relativeVelocityY = asteroid.velocityY - ship.velocityY;
        const distance = Math.hypot(relativeX, relativeY);
        const safeDistance = STARSHIP_RADIUS + asteroid.radius + safeMargin;
        const velocitySquared = relativeVelocityX ** 2 + relativeVelocityY ** 2;
        const closestTime =
            velocitySquared > COLLISION_EPSILON
                ? Math.max(
                    0,
                    Math.min(
                        AUTOPILOT_MAX_LOOKAHEAD_SECONDS,
                        -(relativeX * relativeVelocityX + relativeY * relativeVelocityY) /
                        velocitySquared,
                    ),
                )
                : 0;
        const futureX = relativeX + relativeVelocityX * closestTime;
        const futureY = relativeY + relativeVelocityY * closestTime;
        const futureDistance = Math.hypot(futureX, futureY);
        const closingSpeed =
            distance > COLLISION_EPSILON
                ? -(relativeX * relativeVelocityX + relativeY * relativeVelocityY) /
                distance
                : 0;
        // Keep clearing the safety zone after turning away. Dropping this threat
        // as soon as velocity points outward would make engagement brake the
        // escape and immediately send the ship back into the same heavy body.
        const isNearNow = distance <= safeDistance;
        const isPredictedNear =
            closingSpeed > 0 &&
            futureDistance <= safeDistance &&
            closestTime <= AUTOPILOT_MAX_LOOKAHEAD_SECONDS;

        if (!isNearNow && !isPredictedNear) {
            continue;
        }

        // Compare distance from the collision surface. Adding radius to center
        // distance would rank a tiny rock ahead of an imminent cube hit.
        const score =
            futureDistance -
            STARSHIP_RADIUS -
            asteroid.radius +
            closestTime * AUTOPILOT_THREAT_TIME_COST;

        if (score < selectedScore) {
            selectedThreat = {
                asteroid,
                distance,
                safeDistance,
            };
            selectedScore = score;
        }
    }

    return selectedThreat;
}

/**
 * Choose an escape lane using the same body envelopes as obstacle avoidance.
 * Forecast ordinary thrust after the nose can turn; compare wall and moving
 * body clearance midway and at the end. This is a steering preference only:
 * movement, weapon availability and impact damage stay on their normal paths.
 * @param {Starship} ship Hull and independent controller being operated.
 * @param {Asteroid | Starship} obstacle Body whose safety zone must be cleared.
 * @param {number} width Arena width in CSS pixels.
 * @param {number} height Arena height in CSS pixels.
 * @returns {number} World heading with the most predicted free space.
 */
function autopilotEscapeAngle(ship, obstacle, width, height) {
    const away = Math.atan2(ship.y - obstacle.y, ship.x - obstacle.x);
    let selectedAngle = away;
    let selectedClearance = -Infinity;
    for (const offset of AUTOPILOT_ESCAPE_ANGLE_OFFSETS) {
        const angle = away + offset;
        const turnTime =
            Math.abs(shortestAngleDifference(angle, ship.angle)) / ROTATION_SPEED +
            AUTOPILOT_TURN_REACTION_SECONDS;
        let clearance = Infinity;
        for (const fraction of AUTOPILOT_ESCAPE_SAMPLE_FRACTIONS) {
            const time = AUTOPILOT_ESCAPE_LOOKAHEAD_SECONDS * fraction;
            const thrustTime = Math.max(0, time - turnTime);
            const thrustDistance = MOVEMENT_RESPONSIVENESS * thrustTime ** 2 * 0.5;
            const x =
                ship.x + ship.velocityX * time + Math.cos(angle) * thrustDistance;
            const y =
                ship.y + ship.velocityY * time + Math.sin(angle) * thrustDistance;
            clearance = Math.min(
                clearance,
                x - STARSHIP_RADIUS,
                width - STARSHIP_RADIUS - x,
                y - STARSHIP_RADIUS,
                height - STARSHIP_RADIUS - y,
            );
            for (const body of navigationObstacles(ship)) {
                clearance = Math.min(
                    clearance,
                    Math.hypot(
                        x - body.x - body.velocityX * time,
                        y - body.y - body.velocityY * time,
                    ) -
                    STARSHIP_RADIUS -
                    body.radius,
                );
            }
        }
        if (clearance > selectedClearance) {
            selectedAngle = angle;
            selectedClearance = clearance;
        }
    }
    return selectedAngle;
}

/**
 * Check each wall against outward stopping distance. A ship already moving
 * inward can continue its engagement; corners combine their inward normals
 * rather than alternating between two perpendicular escape headings.
 * @param {Starship} ship Hull and independent controller being operated.
 * @param {number} width Arena width in CSS pixels.
 * @param {number} height Arena height in CSS pixels.
 * @param {number} [collisionCourseStep] Use imminent-contact thresholds for this step.
 * @returns {{ desiredAngle: number, brake: boolean } | undefined} Wall response.
 */
function autopilotWallThreat(
    ship,
    width,
    height,
    collisionCourseStep = undefined,
) {
    const margin = autopilotCanApproach(ship)
        ? AUTOPILOT_RAM_WALL_MARGIN
        : AUTOPILOT_WALL_SAFE_MARGIN + autopilotHealthSafetyMargin(ship);
    const edges = [
        { distance: ship.x - STARSHIP_RADIUS, x: 1, y: 0, extent: width },
        {
            distance: width - ship.x - STARSHIP_RADIUS,
            x: -1,
            y: 0,
            extent: width,
        },
        { distance: ship.y - STARSHIP_RADIUS, x: 0, y: 1, extent: height },
        {
            distance: height - ship.y - STARSHIP_RADIUS,
            x: 0,
            y: -1,
            extent: height,
        },
    ];
    let inwardX = 0;
    let inwardY = 0;
    let brake = false;
    for (const edge of edges) {
        const clearance = Math.min(
            margin,
            edge.extent * AUTOPILOT_WALL_MARGIN_RATIO,
        );
        const inwardSpeed = ship.velocityX * edge.x + ship.velocityY * edge.y;
        const outwardSpeed = Math.max(0, -inwardSpeed);
        const stoppingDistance =
            (outwardSpeed * Math.hypot(ship.velocityX, ship.velocityY)) /
            (2 * MOVEMENT_RESPONSIVENESS);
        if (collisionCourseStep !== undefined) {
            // A nearby wall contributes no normal unless velocity points at it.
            // Buffer scales with closing speed, so tiny glancing drift stays free.
            const triggerDistance = Math.min(
                WALL_AVOIDANCE_STOPPING_CAP,
                stoppingDistance +
                    outwardSpeed * WALL_AVOIDANCE_REACTION_SECONDS,
            );
            if (
                outwardSpeed <= COLLISION_EPSILON ||
                edge.distance >
                    triggerDistance + outwardSpeed * collisionCourseStep
            )
                continue;
        } else if (
            inwardSpeed >= AUTOPILOT_MIN_COAST_SPEED ||
            edge.distance > clearance + stoppingDistance
        ) {
            continue;
        }
        brake ||=
            outwardSpeed >
            (collisionCourseStep === undefined
                ? AUTOPILOT_MIN_COAST_SPEED
                : COLLISION_EPSILON);
        inwardX += edge.x;
        inwardY += edge.y;
    }
    return inwardX === 0 && inwardY === 0
        ? undefined
        : { desiredAngle: Math.atan2(inwardY, inwardX), brake };
}

/**
 * Calculate affordable attack risk from current shields and hull. Rechecking
 * the same roll as shields fall aborts an unsafe pass immediately, while a
 * fresh roll only arrives at the next commitment boundary. This prevents
 * random steering jitter and preserves ordinary damage and regeneration.
 * @param {Starship} ship Hull and independent controller being operated.
 * @returns {number} Attack probability from zero to one.
 */
function autopilotAttackProbability(ship) {
    const shieldRatio = Math.max(
        0,
        Math.min(1, ship.shieldState / SHIELD_MAX_STATE),
    );
    const hullRatio = Math.max(0, Math.min(1, ship.hullState / SHIP_MAX_STATE));
    const availableShield = Math.max(
        0,
        (shieldRatio - AUTOPILOT_ATTACK_MIN_SHIELD_RATIO) /
        (1 - AUTOPILOT_ATTACK_MIN_SHIELD_RATIO),
    );
    const probability =
        AUTOPILOT_ATTACK_PROBABILITY *
        availableShield ** AUTOPILOT_ATTACK_SHIELD_EXPONENT *
        Math.sqrt(hullRatio);
    return probability;
}

/**
 * Compare one committed roll with shield-weighted risk; close passes are more
 * common than rams, so regenerated shields fund useful shots as well as hits.
 * @param {Starship} ship Hull and independent controller being operated.
 * @returns {boolean} Whether approaching within phaser burst range is affordable.
 */
function autopilotCanApproach(ship) {
    return ship.controls.autopilotAttackRoll < autopilotAttackProbability(ship);
}

/**
 * Reserve deliberate contact for the boldest subset of affordable passes.
 * Cube hulls do not fragment on contact, so ramming them spends ship health
 * without the rock-clearing benefit. Engage that durable body with phasers.
 * @param {Starship} ship Hull and independent controller being operated.
 * @param {Asteroid | undefined} target Selected combat body.
 * @returns {boolean} Whether this pass may commit to ramming.
 */
function autopilotCanRam(ship, target) {
    return (
        target !== undefined &&
        !(target instanceof BorgCube) &&
        ship.controls.autopilotAttackRoll <
        autopilotAttackProbability(ship) * AUTOPILOT_RAM_PROBABILITY_RATIO
    );
}

/**
 * Mix close-range phaser passes with velocity-corrected rock ramming and
 * ordinary contact fragmentation. Keep durable cube encounters at range.
 * Ranged positioning between shield-weighted attack passes lets shields
 * regenerate; hull damage reduces risk without disabling later attacks.
 * Walls trigger braking rather than a wasteful impact.
 * Independent firing exploits any useful shot throughout the maneuver.
 * @param {Starship} ship Hull and independent controller being operated.
 * @param {number} deltaTime Elapsed simulation time in seconds.
 * @param {number} width Arena width in CSS pixels.
 * @param {number} height Arena height in CSS pixels.
 * @returns {void}
 */
function updateAutopilotInput(ship, deltaTime, width, height) {
    if (
        !ship.controls.autopilotEnabled ||
        gamePaused ||
        shipFailureActive ||
        gameWon
    ) {
        ship.controls.autopilotDecisionTime = 0;
        setAutopilotInput(ship, []);
        return;
    }
    ship.controls.autopilotDecisionTime += Math.max(0, deltaTime);
    const input = new Set(ship.controls.autopilotPressedKeys);
    if (ship.controls.autopilotDecisionTime >= AUTOPILOT_UPDATE_INTERVAL) {
        const decisionDeltaTime = ship.controls.autopilotDecisionTime;
        ship.controls.autopilotDecisionTime = 0;
        input.delete("KeyW");
        input.delete("KeyS");
        ship.controls.autopilotAttackTimeRemaining -= decisionDeltaTime;
        if (ship.controls.autopilotAttackTimeRemaining <= 0) {
            ship.controls.autopilotAttackRoll = Math.random();
            ship.controls.autopilotAttackTimeRemaining =
                AUTOPILOT_ATTACK_COMMITMENT_SECONDS;
        }
        const target = autopilotTarget(ship, decisionDeltaTime);
        const wall = autopilotWallThreat(ship, width, height);
        const ram = autopilotCanRam(ship, target);
        const threat = autopilotThreat(ship, ram ? target : undefined);
        const speed = Math.hypot(ship.velocityX, ship.velocityY);
        ship.controls.autopilotDesiredAngle =
            target === undefined ? ship.angle : autopilotAimAngle(ship, target);
        // Inside a body's safety zone, choose a lane that also accounts for walls.
        // A wall-only heading can otherwise pin the ship against a pursuing cube.
        const escapingBody =
            threat !== undefined && threat.distance < threat.safeDistance;
        ship.controls.autopilotEscapeTimeRemaining = Math.max(
            0,
            ship.controls.autopilotEscapeTimeRemaining - decisionDeltaTime,
        );
        if (!escapingBody) ship.controls.autopilotEscapeTarget = undefined;
        if (wall !== undefined && !escapingBody) {
            ship.controls.autopilotDesiredAngle = applyWallAvoidanceInput(
                ship, input, wall,
            );
        } else if (threat !== undefined) {
            // Turn toward clearance even while braking. Continuing to aim at the
            // combat target until speed falls lets repeated impacts reset the turn.
            if (
                ship.controls.autopilotEscapeTarget !== threat.asteroid ||
                ship.controls.autopilotEscapeTimeRemaining === 0 ||
                // Wall danger interrupts commitment before an escape becomes a crash.
                wall !== undefined
            ) {
                ship.controls.autopilotEscapeHeading = autopilotEscapeAngle(
                    ship,
                    threat.asteroid,
                    width,
                    height,
                );
                ship.controls.autopilotEscapeTarget = escapingBody
                    ? threat.asteroid
                    : undefined;
                ship.controls.autopilotEscapeTimeRemaining =
                    AUTOPILOT_ESCAPE_COMMITMENT_SECONDS;
            }
            ship.controls.autopilotDesiredAngle =
                ship.controls.autopilotEscapeHeading;
            const towardThreatSpeed =
                threat.distance > COLLISION_EPSILON
                    ? ((threat.asteroid.x - ship.x) * ship.velocityX +
                        (threat.asteroid.y - ship.y) * ship.velocityY) /
                    threat.distance
                    : speed;
            if (towardThreatSpeed > AUTOPILOT_MIN_COAST_SPEED || wall?.brake) {
                input.add("KeyS");
            } else if (escapingBody) {
                // Incoming asteroid motion cannot be stopped by braking the ship.
                // Keep accelerating away rather than braking that escape next time.
                const escapeSpeed =
                    (ship.velocityX - threat.asteroid.velocityX) *
                    Math.cos(ship.controls.autopilotDesiredAngle) +
                    (ship.velocityY - threat.asteroid.velocityY) *
                    Math.sin(ship.controls.autopilotDesiredAngle);
                if (
                    Math.abs(
                        shortestAngleDifference(
                            ship.controls.autopilotDesiredAngle,
                            ship.angle,
                        ),
                    ) <= AUTOPILOT_THRUST_ALIGNMENT_TOLERANCE &&
                    escapeSpeed < AUTOPILOT_CRUISE_SPEED
                ) {
                    input.add("KeyW");
                }
            }
        } else if (target !== undefined && ram) {
            // Pursue the predicted contact point rather than the rock's old position.
            // Forward motion continues through the hit; the solver decides whether
            // its real contact impulse cuts the rock, with no autopilot damage bonus.
            const courseAngle = autopilotAimAngle(
                ship,
                target,
                AUTOPILOT_RAM_SPEED,
                STARSHIP_RADIUS + target.radius * 0.5,
            );
            const correctionX =
                Math.cos(courseAngle) * AUTOPILOT_RAM_SPEED - ship.velocityX;
            const correctionY =
                Math.sin(courseAngle) * AUTOPILOT_RAM_SPEED - ship.velocityY;
            const correctionSpeed = Math.hypot(correctionX, correctionY);
            const forwardSpeed =
                ship.velocityX * Math.cos(courseAngle) +
                ship.velocityY * Math.sin(courseAngle);
            // Thrust toward the velocity correction, not simply the target bearing.
            // This removes sideways drift during a pass instead of orbiting the rock.
            ship.controls.autopilotDesiredAngle =
                correctionSpeed > AUTOPILOT_VELOCITY_CORRECTION_TOLERANCE
                    ? Math.atan2(correctionY, correctionX)
                    : autopilotAimAngle(ship, target);
            const angleError = Math.abs(
                shortestAngleDifference(
                    ship.controls.autopilotDesiredAngle,
                    ship.angle,
                ),
            );
            if (
                forwardSpeed < -AUTOPILOT_MIN_COAST_SPEED ||
                speed > AUTOPILOT_RAM_SPEED + AUTOPILOT_RAM_SPEED_MARGIN
            ) {
                input.add("KeyS");
            } else if (
                angleError <= AUTOPILOT_RAM_THRUST_TOLERANCE &&
                correctionSpeed > AUTOPILOT_VELOCITY_CORRECTION_TOLERANCE
            ) {
                input.add("KeyW");
            }
        } else if (target !== undefined) {
            const closePass =
                !(target instanceof BorgCube) && autopilotCanApproach(ship);
            const cruiseSpeed = closePass
                ? AUTOPILOT_CLOSE_SPEED
                : AUTOPILOT_CRUISE_SPEED;
            const x = target.x - ship.x;
            const y = target.y - ship.y;
            const distance = Math.hypot(x, y);
            const range =
                STARSHIP_RADIUS +
                target.radius +
                Math.min(
                    closePass ? AUTOPILOT_CLOSE_RANGE : AUTOPILOT_ENGAGEMENT_RANGE,
                    Math.min(width, height) * AUTOPILOT_ENGAGEMENT_RANGE_RATIO,
                );
            const closingSpeed =
                distance > COLLISION_EPSILON
                    ? (x * (ship.velocityX - target.velocityX) +
                        y * (ship.velocityY - target.velocityY)) /
                    distance
                    : 0;
            const stoppingDistance =
                Math.max(0, closingSpeed) ** 2 / (2 * MOVEMENT_RESPONSIVENESS);
            const aimError = Math.abs(
                shortestAngleDifference(
                    ship.controls.autopilotDesiredAngle,
                    ship.angle,
                ),
            );
            const noseSpeed =
                ship.velocityX * Math.cos(ship.controls.autopilotDesiredAngle) +
                ship.velocityY * Math.sin(ship.controls.autopilotDesiredAngle);
            if (
                speed > cruiseSpeed ||
                (speed > AUTOPILOT_MIN_COAST_SPEED &&
                    ((closingSpeed > 0 && distance - range <= stoppingDistance) ||
                        noseSpeed < -AUTOPILOT_MIN_COAST_SPEED))
            ) {
                input.add("KeyS");
            } else if (
                distance > range + AUTOPILOT_APPROACH_HYSTERESIS &&
                speed < cruiseSpeed &&
                noseSpeed >= -AUTOPILOT_MIN_COAST_SPEED &&
                aimError <= AUTOPILOT_THRUST_ALIGNMENT_TOLERANCE
            ) {
                input.add("KeyW");
            }
        }
    }
    applyAutopilotTurnInput(ship, input, deltaTime);
    setAutopilotInput(ship, input);
}

/**
 * Recheck firing after this frame's rotation and movement, immediately before
 * the normal weapon cooldown consumes Space. A lost solution stops firing;
 * a newly aligned rock can be engaged on the very same simulation step.
 * @param {Starship} ship Hull and independent controller being operated.
 * @returns {void}
 */
function updateAutoGunnerFiring(ship) {
    if (
        !ship.controls.autoGunnerEnabled ||
        gamePaused ||
        shipFailureActive ||
        gameWon
    ) {
        ship.controls.autoGunnerPressedKeys.clear();
        syncPressedKeys(ship);
        return;
    }
    // Finishing a burst is useful; dribbling hot shots forever is inefficient.
    // Cool while navigating to the next attack, then spend that heat on a burst.
    if (ship.phaserHeat >= PHASER_OVERHEAT_THRESHOLD) {
        ship.controls.autoGunnerBurstActive = false;
    }
    const hasShot = autoGunnerHasShot(ship);
    if (
        hasShot &&
        ship.phaserHeat <=
        PHASER_OVERHEAT_THRESHOLD * AUTO_GUNNER_BURST_START_HEAT_RATIO
    ) {
        ship.controls.autoGunnerBurstActive = true;
    }
    if (hasShot && ship.controls.autoGunnerBurstActive) {
        ship.controls.autoGunnerPressedKeys.add(FIRE_KEY);
    } else {
        ship.controls.autoGunnerPressedKeys.delete(FIRE_KEY);
    }
    syncPressedKeys(ship);
}

/**
 * Request one pulse through the shared cadence and heat gates. Heat may rise
 * above the limit with a shot, but firing resumes as soon as it drops below
 * that same limit. Taps and auto-gunner use precisely the same thermal rule.
 * @param {Starship} ship Hull and independent controller being operated.
 * @returns {void}
 */
function tryFireBullet(ship) {
    if (gamePaused || shipFailureActive || gameWon) {
        return;
    }
    ship.tryFire();
}

/**
 * Cool throughout active simulation, even when firing is released. Pausing
 * freezes heat with the world; missed time never becomes a catch-up volley.
 * @param {Starship} ship Hull and independent controller being operated.
 * @param {number} deltaTime Elapsed simulation time in seconds.
 * @returns {void}
 */
function updateBulletFiring(ship, deltaTime) {
    if (
        gamePaused ||
        shipFailureActive ||
        gameWon ||
        !Number.isFinite(deltaTime)
    ) {
        return;
    }
    ship.coolWeapon(deltaTime);
    if (ship.controls.pressedKeys.has(FIRE_KEY)) tryFireBullet(ship);
}

/**
 * The drawing buffer follows the displayed size and device pixel ratio so
 * rendering stays crisp without changing the game's CSS-pixel coordinates.
 */
function resizeCanvas() {
    const {width, height} = canvas.getBoundingClientRect();
    const pixelRatio = window.devicePixelRatio || 1;
    const bufferWidth = Math.round(width * pixelRatio);
    const bufferHeight = Math.round(height * pixelRatio);

    // Layout notifications can repeat without changing the drawing surface.
    // Avoid clearing its state and rebuilding wall gradients unnecessarily.
    if (
        width <= 0 ||
        height <= 0 ||
        (width === viewportWidth &&
            height === viewportHeight &&
            canvas.width === bufferWidth &&
            canvas.height === bufferHeight)
    ) {
        return;
    }

    const gameplayHeight = gameplayHeightForViewport(height);

    viewportWidth = width;
    viewportHeight = height;

    canvas.width = bufferWidth;
    canvas.height = bufferHeight;
    context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
    // Resizing resets the canvas state and changes gradient coordinates. The
    // next draw lazily rebuilds this presentation-only cache once.
    dangerWallGradients = undefined;
    starfieldPaths = createStarfieldPaths(width, gameplayHeight);

    if (previousFrameTime === undefined) {
        for (const ship of starships) {
            ship.x = width / 2;
            ship.y = gameplayHeight / 2;
        }
    }
    for (const ship of starships) ship.keepInside(width, gameplayHeight);

    generateAsteroids(width, gameplayHeight);
    for (const cube of borgCubes) cube.keepInside(width, gameplayHeight);

    for (const asteroid of asteroids) {
        asteroid.keepInside(width, gameplayHeight);
    }

    drawGame(width, height);
}

/**
 * Reserve the fixed command-console band outside the physical simulation.
 * @param {number} viewportHeight Full canvas height in CSS pixels.
 * @returns {number} Height available to gameplay and wall collisions.
 */
function gameplayHeightForViewport(viewportHeight) {
    return Math.max(0, viewportHeight - LCARS_CONSOLE_HEIGHT);
}

function constrainPosition(position, radius, extent) {
    return constrainPositionToRange(position, radius, extent - radius, extent);
}

function constrainPositionToRange(position, minimum, maximum, extent) {
    return maximum <= minimum
        ? extent / 2
        : Math.min(Math.max(position, minimum), maximum);
}

/**
 * Estimate hull loss from a short burst of heavy contacts, using the same
 * pre-impact shield transmission and damage cap as the collision model.
 * @param {Starship} ship Hull shown by the bridge alert output.
 * @param {number} contactCount Number of consecutive full-budget contacts.
 * @returns {number} Hull points required to survive the burst.
 */
function alertHullLoss(ship, contactCount) {
    let charge = ship.shieldState;
    let loss = 0;
    for (let contact = 0; contact < contactCount; contact += 1) {
        loss +=
            COLLISION_DAMAGE_BUDGET_CAP *
            (1 - charge / SHIELD_MAX_STATE) *
            SHIP_DAMAGE_COEFFICIENT;
        charge = Math.max(
            0,
            charge - COLLISION_DAMAGE_BUDGET_CAP * SHIELD_DAMAGE_COEFFICIENT,
        );
    }
    return loss;
}

/**
 * Escalate immediately after damage; clear only after sustained recovery.
 * Yellow sounds only on escalation from healthy; recovery from red is silent.
 * Red remains a single cue per ship life.
 * Entry enables appropriate assistance once, so manual overrides continue to
 * work while an alert persists. Recovery leaves the selected modes enabled.
 * @param {Starship} ship Hull shown by the bridge alert output.
 * @param {number} deltaTime Active simulation seconds since the last update.
 * @returns {void}
 */
function updateAlert(ship, deltaTime) {
    // Destruction has its own failure screen; alarms must precede it to help.
    if (!ship.alive) return;
    const activeSeconds = Number.isFinite(deltaTime)
        ? Math.max(0, deltaTime)
        : 0;
    alertHullLossRate =
        alertHullLossRate *
            Math.exp(-activeSeconds / ALERT_DAMAGE_MEMORY_SECONDS) +
        Math.max(0, alertPreviousHullState - ship.hullState) /
            ALERT_DAMAGE_MEMORY_SECONDS;
    alertPreviousHullState = ship.hullState;
    const previousLevel = alertLevel;
    const redLoss = Math.min(
        alertHullLoss(ship, ALERT_RED_CONTACT_COUNT),
        alertHullLossRate * ALERT_RED_DAMAGE_PROJECTION_SECONDS,
    );
    const yellowLoss = Math.min(
        alertHullLoss(ship, ALERT_YELLOW_CONTACT_COUNT),
        alertHullLossRate * ALERT_YELLOW_DAMAGE_PROJECTION_SECONDS,
    );
    const nextLevel =
        ship.hullState <= redLoss ? 2 : ship.hullState <= yellowLoss ? 1 : 0;
    if (nextLevel >= alertLevel) {
        alertLevel = nextLevel;
        alertRecoveryTime = 0;
    } else {
        const recoveryLoss = alertLevel === 2 ? redLoss : yellowLoss;
        alertRecoveryTime =
            ship.hullState > recoveryLoss + ALERT_CLEAR_RESERVE_MARGIN
                ? alertRecoveryTime + activeSeconds
                : 0;
        if (alertRecoveryTime >= ALERT_CLEAR_DELAY_SECONDS) {
            alertLevel = nextLevel;
            alertRecoveryTime = 0;
        }
    }
    if (alertLevel !== previousLevel && alertLevel > 0) {
        if (!ship.aimAssist.enabled) ship.aimAssist.toggle();
        if (alertLevel === 2 && !ship.controls.autopilotEnabled)
            toggleAutopilot(ship);
    }
    if (alertLevel === 1 && previousLevel === 0) {
        yellowAlertSound.playRandom();
    }
    if (alertLevel === 2 && !redAlertSoundPlayed) {
        redAlertSoundPlayed = true;
        redAlertSound.playRandom();
    }
}

/**
 * Begin a fresh field after destruction or a completed field. Achievements
 * reset only after the previous round's result screen has been shown.
 * Rebuilding the world retries the lost field from scratch, including its
 * starting fleet, instead of leaving the player inside the fatal collision.
 * @param {number} width Viewport width in CSS pixels.
 * @param {number} height Viewport height in CSS pixels.
 * @returns {void}
 */
function restartGame(width, height) {
    // Only victory advances progress; destruction retries the current field.
    roundAchievements.clear();
    if (gameWon) sessionField += 1;
    fieldAsteroidDamage.ramming = 0;
    fieldAsteroidDamage.blasters = 0;
    configureHelpingFleet(width, height);
    redAlertSoundPlayed = false;
    alertLevel = 0;
    alertRecoveryTime = 0;
    alertHullLossRate = 0;
    alertPreviousHullState = SHIP_MAX_STATE;
    shipFailureActive = false;
    shipFailureTimeRemaining = 0;
    gameWon = false;
    bullets.length = 0;
    sparks.length = 0;
    // A new sector returns all assistance to manual control, including after
    // destruction or victory. Clear input and locks through the shared reset.
    asteroids.length = 0;
    asteroidsGenerated = false;
    borgCubes.length = 0;
    borgTacticsCubeIndex = 0;
    starfleetTacticsState.index = 0;
    generateAsteroids(width, height);
}

/**
 * Start the short frozen state shown after the hull reaches zero. The render
 * loop remains alive so the animated bars and the explanation stay visible.
 * @returns {void}
 */
function beginShipFailure() {
    if (shipFailureActive) {
        return;
    }

    shipFailureActive = true;
    shipFailureTimeRemaining = SHIP_FAILURE_DISPLAY_SECONDS;
    defeatSound.playRandom();
    for (const ship of starships) {
        clearPressedKeys(ship);
        ship.phaserShotCooldown = 0;
    }
}

/**
 * Unlock the ramming challenge before displaying achievements.
 * Rammer requires strictly more ramming damage in the completed field; ties
 * (including an empty comparison) never qualify. Earned badges belong only to that field.
 * Keep the result visible until the player starts another field, separately
 * from the ordinary pause state.
 * @returns {void}
 */
function beginWin() {
    if (
        gameWon ||
        shipFailureActive ||
        asteroids.length > 0 ||
        borgCubes.some((cube) => cube.alive)
    ) {
        return;
    }

    gameWon = true;
    if (fieldAsteroidDamage.ramming > fieldAsteroidDamage.blasters) {
        roundAchievements.add("rammer");
    }
    gamePaused = true;
    winSound.playRandom();
    for (const bullet of bullets) {
        emitSparksAt({x: bullet.x, y: bullet.y}, bodyKineticEnergy(bullet));
    }
    bullets.length = 0;
    for (const ship of starships) {
        clearPressedKeys(ship);
        ship.phaserShotCooldown = 0;
    }
}

/**
 * Count down the failure message and start the next life when it has been
 * readable for the configured display interval.
 * @param {number} deltaTime Elapsed real time in seconds.
 * @param {number} width Viewport width in CSS pixels.
 * @param {number} height Viewport height in CSS pixels.
 * @returns {void}
 */
function updateShipFailure(deltaTime, width, height) {
    if (!shipFailureActive || !Number.isFinite(deltaTime)) {
        return;
    }

    shipFailureTimeRemaining = Math.max(
        0,
        shipFailureTimeRemaining - Math.max(0, deltaTime),
    );

    if (shipFailureTimeRemaining <= 0) {
        restartGame(width, height);
    }
}

/**
 * Credit direct asteroid hits using the ship damage system's impulse scale.
 * Use the uncapped impact value: shield absorption and the ship's protective
 * contact budget describe damage received, not damage inflicted on a rock.
 * @param {ContactResponse} response Impulse transferred during the hit.
 * @param {"ramming" | "blasters"} source Attack responsible for the contact.
 * @returns {void}
 */
function recordAsteroidDamage(response, source) {
    const damage = contactImpulseMagnitude(response) * COLLISION_DAMAGE_SCALE;

    if (!Number.isFinite(damage) || damage <= 0) {
        return;
    }

    // Saturate totals rather than letting an extreme input poison the comparison
    // with Infinity. Ordinary impacts remain far below this numeric boundary.
    fieldAsteroidDamage[source] = Math.min(
        Number.MAX_VALUE,
        fieldAsteroidDamage[source] + damage,
    );
}

/**
 * Move one displayed bar value toward its authoritative target.
 * @param {number} currentValue Current displayed percentage.
 * @param {number} targetValue Authoritative percentage.
 * @param {number} maximumChange Maximum movement this frame.
 * @returns {number}
 */
function moveBarValueToward(currentValue, targetValue, maximumChange) {
    if (!Number.isFinite(targetValue)) {
        return currentValue;
    }

    const distance = targetValue - currentValue;

    return Math.abs(distance) <= maximumChange
        ? targetValue
        : currentValue + Math.sign(distance) * maximumChange;
}

/**
 * Animate a hull's shield rim and status bars together, including while paused.
 * @param {Starship} ship Hull whose presentation values are advanced.
 * @param {number} deltaTime Elapsed real time in seconds.
 * @returns {void}
 */
function updateDisplayedStatusBars(deltaTime, ship) {
    if (!Number.isFinite(deltaTime)) {
        return;
    }

    const maximumChange = STATUS_BAR_ANIMATION_SPEED * Math.max(0, deltaTime);
    ship.displayedShieldState = moveBarValueToward(
        ship.displayedShieldState,
        ship.shieldState,
        maximumChange,
    );
    ship.displayedHullState = moveBarValueToward(
        ship.displayedHullState,
        ship.hullState,
        maximumChange,
    );
}

/**
 * Draw the two persistent ship-life indicators in the upper-right corner.
 * These are game UI, not debug output, so they remain visible when debugging
 * is disabled and while the paused help screen is open.
 * @param {number} width Viewport width in CSS pixels.
 * @returns {number|undefined} Left edge of the health bars when drawn.
 */
function drawStatusBars(width) {
    const barWidth = Math.min(
        STATUS_BAR_WIDTH,
        Math.max(0, width - STATUS_BAR_MARGIN * 2),
    );

    if (barWidth <= 0) {
        return undefined;
    }

    const barX = width - barWidth - STATUS_BAR_MARGIN;
    const barTop = LCARS_CONSOLE_TOP;

    const bars = [
        {
            label: "SHIELD",
            state: playerShip.displayedShieldState,
            color: LCARS_LILAC,
        },
        {
            label: "HULL",
            state: playerShip.displayedHullState,
            // Keep a steady warning visible even when the console has no text gap.
            color:
                alertLevel === 2
                    ? LCARS_ALERT_RED
                    : alertLevel === 1
                        ? LCARS_GOLD
                        : LCARS_CORAL,
        },
    ];

    context.save();
    context.font = `700 13px ${LCARS_BODY_FONT_FAMILY}`;
    context.textBaseline = "middle";

    for (let barIndex = 0; barIndex < bars.length; barIndex += 1) {
        const bar = bars[barIndex];
        const barY = barTop + barIndex * (STATUS_BAR_HEIGHT + STATUS_BAR_GAP);
        const fillWidth = barWidth * (bar.state / SHIELD_MAX_STATE);

        context.beginPath();
        context.roundRect(barX, barY, barWidth, STATUS_BAR_HEIGHT, 11);
        // A quiet tinted track keeps the indicator in the same filled, borderless
        // LCARS vocabulary as the command strip; the previous outlined lettering
        // read like a legacy widget beside the solid controls.
        context.fillStyle = bar.color;
        context.globalAlpha = 0.35;
        context.fill();
        context.globalAlpha = 1;
        context.save();
        context.clip();
        context.fillStyle = bar.color;
        context.fillRect(barX, barY, fillWidth, STATUS_BAR_HEIGHT);
        context.restore();

        context.fillStyle = LCARS_BLACK;
        context.textAlign = "left";
        context.fillText(bar.label, barX + 8, barY + STATUS_BAR_HEIGHT / 2);
        context.textAlign = "right";
        context.fillText(
            `${Math.round(bar.state)}%`,
            barX + barWidth - 8,
            barY + STATUS_BAR_HEIGHT / 2,
        );
    }

    context.restore();

    return barX;
}

/**
 * Split spare console space into danger and positive automatic-helm lanes.
 * Dim blinking text stays readable between pulses, including while paused.
 * @param {number|undefined} controlRightX Right edge of the fire control.
 * @param {number|undefined} statusBarsLeft Left edge of the health bars.
 * @returns {void}
 */
function drawAlert(controlRightX, statusBarsLeft) {
    if (!Number.isFinite(controlRightX) || !Number.isFinite(statusBarsLeft)) {
        return;
    }

    const alertLeft = controlRightX + ALERT_EDGE_GAP;
    const alertRight = statusBarsLeft - ALERT_EDGE_GAP;
    const availableWidth = alertRight - alertLeft;
    const blinkIsBright =
        Math.floor(
            window.performance.now() / RED_ALERT_BLINK_INTERVAL_MILLISECONDS,
        ) %
            2 ===
        0;
    const lanes = [
        {
            text: alertLevel === 2 ? "RED ALERT" : "YELLOW ALERT",
            visible: alertLevel > 0,
            color: alertLevel === 2 ? LCARS_ALERT_RED : LCARS_GOLD,
            blinking: alertLevel === 2,
        },
        {
            text: "AUTOPILOT",
            visible:
                playerShip.controls.autopilotEnabled ||
                playerShip.controls.wallAvoidanceActive,
            color: LCARS_AUTOPILOT_GREEN,
            blinking: true,
        },
    ];

    context.save();
    context.font = `700 21px ${LCARS_FONT_FAMILY}`;
    context.textAlign = "right";
    context.textBaseline = "middle";
    // Ghost legends share the danger row like overlapping old LCD segments.
    // Paint all ghosts first so an inactive legend cannot dim an active one.
    // Both LCD lanes share the right edge beside the health bars.
    /**
     * @param {number} index Zero-based console lane.
     * @returns {number} Lane center y in CSS pixels.
     */
    const laneY = (index) =>
        LCARS_CONSOLE_TOP + (STATUS_BARS_HEIGHT * (index + 0.5)) / lanes.length;
    // Reserve the left half-lane only when both legends fit; compact consoles
    // prioritize the active emergency cue without overlapping right-side text.
    const leftLanes = [
        {
            text: "OVERHEATING",
            active:
                playerShip.phaserHeat >
                PHASER_OVERHEAT_THRESHOLD * PHASER_WARNING_HEAT_RATIO,
            color: LCARS_CORAL,
        },
        {
            text: "COLLISION COURSE",
            active: playerShip.controls.wallAvoidanceActive,
            color: LCARS_GOLD,
        },
    ];
    for (const [index, lane] of leftLanes.entries()) {
        const leftWidth = context.measureText(lane.text).width;
        const rightWidth = context.measureText(lanes[index].text).width;
        if (
            leftWidth > availableWidth ||
            (lanes[index].visible &&
                leftWidth + rightWidth + ALERT_EDGE_GAP > availableWidth)
        ) {
            if (index === 1 && lane.active) {
                context.save();
                context.font = `700 16px ${LCARS_FONT_FAMILY}`;
                context.textAlign = "right";
                context.globalAlpha = 1;
                const right = viewportWidth - ALERT_EDGE_GAP;
                const labelWidth = context.measureText(lane.text).width;
                const top = LCARS_CONSOLE_HEIGHT + ALERT_EDGE_GAP;
                context.fillStyle = LCARS_BLACK;
                context.fillRect(
                    right - labelWidth - ALERT_EDGE_GAP,
                    top,
                    labelWidth + ALERT_EDGE_GAP * 2,
                    24,
                );
                context.fillStyle = lane.color;
                context.fillText(lane.text, right, top + 12);
                context.restore();
            }
            continue;
        }
        context.textAlign = "left";
        context.fillStyle = lane.color;
        context.globalAlpha = lane.active ? 1 : ALERT_LCD_SILHOUETTE_OPACITY;
        context.fillText(lane.text, alertLeft, laneY(index));
        context.textAlign = "right";
    }
    const legends = [
        { text: "RED ALERT", color: LCARS_ALERT_RED, index: 0 },
        { text: "YELLOW ALERT", color: LCARS_GOLD, index: 0 },
        { text: "AUTOPILOT", color: LCARS_AUTOPILOT_GREEN, index: 1 },
    ];
    for (const legend of legends) {
        if (context.measureText(legend.text).width > availableWidth) continue;
        context.fillStyle = legend.color;
        context.globalAlpha = ALERT_LCD_SILHOUETTE_OPACITY;
        context.fillText(legend.text, alertRight, laneY(legend.index));
    }
    for (const [index, lane] of lanes.entries()) {
        if (
            !lane.visible ||
            context.measureText(lane.text).width > availableWidth
        )
            continue;
        context.fillStyle = lane.color;
        context.globalAlpha = lane.blinking && !blinkIsBright ? 0.18 : 1;
        context.fillText(lane.text, alertRight, laneY(index));
    }
    context.restore();
}

/**
 * Draw the simulator identity and active alert as a quiet arena background.
 * The alert shares the title opacity and stays steady to avoid distracting
 * flashes behind moving hazards; the console carries the urgent red blink.
 * @param {number} width Viewport width in CSS pixels.
 * @param {number} height Viewport height in CSS pixels.
 * @returns {void}
 */
function drawPhraseBackground(width, height) {
    const fontSize = phraseFontSizeForViewport(width, height);
    const metrics = phraseTextMetrics(fontSize);
    const lineHeight = metrics.lineHeight + PHRASE_LINE_GAP;
    const lineCount = PHRASE_LINES.length + Number(alertLevel > 0);
    const blockHeight =
        metrics.lineHeight * lineCount + PHRASE_LINE_GAP * (lineCount - 1);
    const firstBaseline = (height - blockHeight) / 2 + metrics.ascent;

    context.save();
    context.font = `${PHRASE_FONT_WEIGHT} ${fontSize}px ${PHRASE_FONT_FAMILY}`;
    context.fillStyle = LCARS_LAVENDER;
    context.globalAlpha = PHRASE_OPACITY;
    context.textAlign = "center";
    context.textBaseline = "alphabetic";

    for (let lineIndex = 0; lineIndex < PHRASE_LINES.length; lineIndex += 1) {
        context.fillText(
            PHRASE_LINES[lineIndex],
            width / 2,
            firstBaseline + lineIndex * lineHeight,
        );
    }

    if (alertLevel > 0) {
        context.fillStyle = alertLevel === 2 ? LCARS_ALERT_RED : LCARS_GOLD;
        context.fillText(
            PHRASE_ALERT_LINES[alertLevel],
            width / 2,
            firstBaseline + PHRASE_LINES.length * lineHeight,
        );
    }

    context.restore();
}

/**
 * Build the immutable wall paints for the current canvas size. CanvasGradient
 * objects remain valid between frames and are invalidated by resizeCanvas().
 * @param {number} width Playfield width in CSS pixels.
 * @param {number} height Playfield height in CSS pixels.
 * @param {number} thickness Wall glow thickness in CSS pixels.
 * @returns {{top: CanvasGradient, bottom: CanvasGradient, left: CanvasGradient, right: CanvasGradient}}
 */
function createDangerWallGradients(width, height, thickness) {
    const top = context.createLinearGradient(0, 0, 0, thickness);
    top.addColorStop(0, WALL_GLOW_COLOR);
    top.addColorStop(1, WALL_GLOW_FADE_COLOR);

    const bottom = context.createLinearGradient(
        0,
        height,
        0,
        height - thickness,
    );
    bottom.addColorStop(0, WALL_GLOW_COLOR);
    bottom.addColorStop(1, WALL_GLOW_FADE_COLOR);

    const left = context.createLinearGradient(0, 0, thickness, 0);
    left.addColorStop(0, WALL_GLOW_COLOR);
    left.addColorStop(1, WALL_GLOW_FADE_COLOR);

    const right = context.createLinearGradient(width, 0, width - thickness, 0);
    right.addColorStop(0, WALL_GLOW_COLOR);
    right.addColorStop(1, WALL_GLOW_FADE_COLOR);

    return {top, bottom, left, right};
}

/**
 * Draw the four physical arena boundaries as a restrained danger glow. The
 * gradients fade inward so the edge remains legible while the play field
 * stays clear; this is presentation only and does not change wall physics.
 * @param {number} width Viewport width in CSS pixels.
 * @param {number} height Viewport height in CSS pixels.
 * @returns {void}
 */
function drawDangerWalls(width, height) {
    const thickness = Math.min(
        WALL_GLOW_THICKNESS,
        Math.max(1, Math.min(width, height) / 2),
    );

    dangerWallGradients ??= createDangerWallGradients(width, height, thickness);
    context.save();

    // Gradients provide the complete inward glow. A shadow on these full-edge
    // rectangles duplicates that effect while forcing Safari to rasterize four
    // large blur regions on every frame.
    context.fillStyle = dangerWallGradients.top;
    context.fillRect(0, 0, width, thickness);

    context.fillStyle = dangerWallGradients.bottom;
    context.fillRect(0, height - thickness, width, thickness);

    context.fillStyle = dangerWallGradients.left;
    context.fillRect(0, 0, thickness, height);

    context.fillStyle = dangerWallGradients.right;
    context.fillRect(width - thickness, 0, thickness, height);

    context.strokeStyle = WALL_GLOW_COLOR;
    context.lineWidth = 2;
    context.beginPath();
    context.rect(1, 1, Math.max(0, width - 2), Math.max(0, height - 2));
    context.stroke();
    context.restore();
}

/**
 * Draw all active impact particles above the bodies and below any help or
 * status overlay, keeping the burst visible without obscuring player-facing
 * instructions.
 * @returns {void}
 */
function drawSparks() {
    if (sparks.length === 0) {
        return;
    }

    context.save();
    context.globalCompositeOperation = "lighter";
    context.fillStyle = SPARK_COLOR;
    for (const spark of sparks) {
        spark.draw();
    }
    context.restore();
}

/**
 * Clear the LCARS command console above the physical arena. Buttons and status
 * read cleanly on black without decorative rails competing behind them.
 * @param {number} width Viewport width in CSS pixels.
 * @returns {void}
 */
function drawLCARSCommandConsole(width) {
    context.save();
    context.fillStyle = LCARS_BLACK;
    context.fillRect(0, 0, width, LCARS_CONSOLE_HEIGHT);
    context.restore();
}

/**
 * Build the two star-size paths only when the viewport changes. Positions are
 * random and cosmetic, sampled once at startup; resizing consumes no randomness.
 * @param {number} width Arena width in CSS pixels.
 * @param {number} height Arena height in CSS pixels.
 * @returns {Path2D[]} Small and large star paths.
 */
function createStarfieldPaths(width, height) {
    const paths = [new Path2D(), new Path2D()];
    for (let index = 0; index < STARFIELD_COUNT; index += 1) {
        const large = index % 4 === 0;
        const size = large ? STARFIELD_LARGE_SIZE : STARFIELD_SMALL_SIZE;
        const x = STARFIELD_POSITIONS[index].x * Math.max(0, width - size);
        const y = STARFIELD_POSITIONS[index].y * Math.max(0, height - size);
        paths[large ? 1 : 0].rect(x, y, size, size);
    }
    return paths;
}

/**
 * Blend the shield's LCARS colors continuously so damage and regeneration do
 * not cause abrupt warning-color switches. Inputs are six-digit hex colors.
 * @param {string} fromColor Color at the lower charge endpoint.
 * @param {string} toColor Color at the upper charge endpoint.
 * @param {number} fraction Blend amount between zero and one.
 * @returns {string} Canvas-compatible RGB color.
 */
function blendShieldColors(fromColor, toColor, fraction) {
    const from = Number.parseInt(fromColor.slice(1), 16);
    const to = Number.parseInt(toColor.slice(1), 16);
    /**
     * @param {number} shift Bit offset of the red, green, or blue channel.
     * @returns {number} Blended eight-bit channel value.
     */
    const blendChannel = (shift) => {
        const start = (from >> shift) & 255;
        const end = (to >> shift) & 255;
        return Math.round(start + (end - start) * fraction);
    };
    return `rgb(${blendChannel(16)}, ${blendChannel(8)}, ${blendChannel(0)})`;
}

/**
 * Render the starship inside its circular collision shield. Cached normalized
 * paths avoid per-frame geometry allocations; the coral bow marker makes
 * heading readable even when the saucer is seen among asteroid fragments.
 * @param {Starship} ship Friendly hull to render with the shared silhouette.
 * @returns {void}
 */
function drawStarship(ship) {
    context.save();
    context.translate(ship.x, ship.y);
    const opacity = ship === playerShip ? 1 : FRIENDLY_STARSHIP_OPACITY;
    // Destroyed helpers keep their physical hull but lose all powered cues.
    if (ship !== playerShip && !ship.alive) {
        context.rotate(ship.angle);
        context.scale(STARSHIP_RADIUS, STARSHIP_RADIUS);
        context.globalAlpha = FRIENDLY_WRECK_OPACITY;
        context.fillStyle = LCARS_LAVENDER;
        context.fill(STARSHIP_SILHOUETTE);
        context.strokeStyle = LCARS_BLACK;
        context.lineWidth = 3 / STARSHIP_RADIUS;
        context.stroke(STARSHIP_WRECK_FRACTURES);
        context.restore();
        return;
    }
    // Share the HUD's animated charge so both indicators agree during impacts.
    // The whole rim changes together: missing arcs would imply a physical gap.
    const shieldRatio = Math.max(
        0,
        Math.min(1, ship.displayedShieldState / SHIELD_MAX_STATE),
    );
    const healthy = shieldRatio > SHIELD_WARNING_RATIO;
    const colorFraction = healthy
        ? (shieldRatio - SHIELD_WARNING_RATIO) / (1 - SHIELD_WARNING_RATIO)
        : Math.max(
              0,
              (shieldRatio - SHIELD_CRITICAL_RATIO) /
                  (SHIELD_WARNING_RATIO - SHIELD_CRITICAL_RATIO),
          );
    // Immunity uses the same rim and halo on every friendly hull.
    context.strokeStyle =
        ship.spawnImmunityRemaining > 0
            ? SHIELD_SPAWN_IMMUNITY_COLOR
            : blendShieldColors(
                  healthy ? LCARS_AMBER : LCARS_ALERT_RED,
                  healthy ? LCARS_LILAC : LCARS_AMBER,
                  colorFraction,
              );
    context.beginPath();
    context.arc(0, 0, STARSHIP_RADIUS, 0, Math.PI * 2);
    context.globalAlpha = opacity * SHIELD_HALO_OPACITY * shieldRatio;
    context.lineWidth = SHIELD_HALO_WIDTH;
    context.stroke();
    context.globalAlpha =
        opacity *
        (SHIELD_DEPLETED_OPACITY + (1 - SHIELD_DEPLETED_OPACITY) * shieldRatio);
    context.lineWidth = SHIELD_RIM_WIDTH;
    context.stroke();
    context.globalAlpha = opacity;

    context.rotate(ship.angle);
    context.scale(STARSHIP_RADIUS, STARSHIP_RADIUS);
    // Hull identity remains visible regardless of helm mode or shield charge.
    context.fillStyle = ship === playerShip ? LCARS_GOLD : LCARS_LAVENDER;
    context.fill(STARSHIP_SILHOUETTE);
    context.strokeStyle = LCARS_BLACK;
    context.lineWidth = 1 / STARSHIP_RADIUS;
    context.stroke(STARSHIP_SILHOUETTE);
    context.strokeStyle = LCARS_LILAC;
    context.lineWidth = 2 / STARSHIP_RADIUS;
    context.stroke(STARSHIP_DETAILS);
    context.fillStyle = LCARS_CORAL;
    context.fill(STARSHIP_HEADING_MARKER);
    context.restore();
}

/**
 * Draw the training arena, then its moving bodies and bridge overlays.
 * @param {number} width Viewport width in CSS pixels.
 * @param {number} height Viewport height in CSS pixels.
 * @returns {void}
 */
function drawGame(width, height) {
    const playfieldHeight = gameplayHeightForViewport(height);

    context.fillStyle = LCARS_BLACK;
    context.fillRect(0, 0, width, height);
    context.save();
    context.translate(0, LCARS_CONSOLE_HEIGHT);
    context.save();
    context.globalAlpha = STARFIELD_OPACITY;
    context.fillStyle = LCARS_LILAC;
    context.fill(starfieldPaths[0]);
    context.fillStyle = LCARS_TEXT;
    context.fill(starfieldPaths[1]);
    context.restore();
    drawPhraseBackground(width, playfieldHeight);
    drawDangerWalls(width, playfieldHeight);

    // Asteroids are drawn after the background so the player remains visually
    // legible when the two shapes overlap. The phrase itself is never a physics
    // body and cannot be collided with, cut, or counted in telemetry.
    for (const asteroid of asteroids) {
        asteroid.draw();
    }

    for (const cube of borgCubes) cube.drawTransfer();
    for (const cube of borgCubes) cube.draw();

    for (const bullet of bullets) {
        bullet.draw();
    }

    drawAimAssist(width, playfieldHeight);
    drawBorgFocusLock(width, playfieldHeight);
    drawStarfleetFocus(width, playfieldHeight);
    for (const ship of starships) drawStarship(ship);

    drawSparks();

    if (shipFailureActive) {
        drawShipFailure(width, playfieldHeight);
    } else if (gameWon) {
        drawWinScreen(width, playfieldHeight);
    } else if (gamePaused) {
        drawPauseHelp(width, playfieldHeight);
    }
    context.restore();

    drawLCARSCommandConsole(width);
    const controlRightX = drawFlightControls(width);
    const statusBarsLeft = drawStatusBars(width);
    drawAlert(controlRightX, statusBarsLeft);
}

/**
 * Draw a target ring and the true predicted intercept point. Clip predictions
 * to the arena instead of pinning an offscreen point to a false aim position.
 * @param {number} width Arena width in CSS pixels.
 * @param {number} height Arena height in CSS pixels.
 * @returns {void}
 */
function drawAimAssist(width, height) {
    const target = playerShip.aimAssist.target;
    if (
        !playerShip.aimAssist.enabled ||
        target === undefined ||
        shipFailureActive ||
        gameWon
    )
        return;
    context.save();
    context.beginPath();
    context.rect(0, 0, width, height);
    context.clip();
    context.strokeStyle = LCARS_GOLD;
    context.lineWidth = 1.5;
    context.beginPath();
    context.arc(
        target.x,
        target.y,
        target.radius + AIM_ASSIST_TARGET_PADDING,
        0,
        Math.PI * 2,
    );
    context.stroke();
    const time = linearInterceptTime(playerShip, target);
    if (time !== undefined) {
        const x = target.x + target.velocityX * time;
        const y = target.y + target.velocityY * time;
        if (Number.isFinite(x) && Number.isFinite(y)) {
            const radius = AIM_ASSIST_MARKER_RADIUS;
            const gap = AIM_ASSIST_MARKER_GAP;
            context.beginPath();
            context.arc(x, y, radius, 0, Math.PI * 2);
            context.moveTo(x - radius - gap, y);
            context.lineTo(x - gap, y);
            context.moveTo(x + gap, y);
            context.lineTo(x + radius + gap, y);
            context.moveTo(x, y - radius - gap);
            context.lineTo(x, y - gap);
            context.moveTo(x, y + gap);
            context.lineTo(x, y + radius + gap);
            context.stroke();
        }
    }
    context.restore();
}

/**
 * Lavender brackets identify helper assignments, including a lone helper, so
 * the player can support the fleet without enabling automatic controls.
 * @param {number} width Arena width in CSS pixels.
 * @param {number} height Arena height in CSS pixels.
 * @returns {void}
 */
function drawStarfleetFocus(width, height) {
    if (shipFailureActive || gameWon) return;
    /** @type {Map<Asteroid, number>} Helper counts for visible live targets. */
    const groups = new Map();
    for (const ship of starships) {
        if (
            ship === playerShip ||
            !ship.alive ||
            !ship.fleetTarget ||
            !isLiveTarget(ship.fleetTarget)
        )
            continue;
        groups.set(ship.fleetTarget, (groups.get(ship.fleetTarget) ?? 0) + 1);
    }
    context.save();
    context.beginPath();
    context.rect(0, 0, width, height);
    context.clip();
    context.strokeStyle = LCARS_LAVENDER;
    context.fillStyle = LCARS_LAVENDER;
    context.lineWidth = 2;
    context.font = `700 12px ${LCARS_FONT_FAMILY}`;
    context.textAlign = "center";
    context.textBaseline = "top";
    for (const [target, count] of groups) {
        const radius = target.radius + BORG_FOCUS_LOCK_BRACKET_PADDING;
        context.beginPath();
        for (const x of [-1, 1])
            for (const y of [-1, 1]) {
                context.moveTo(
                    target.x + x * (radius - 9),
                    target.y + y * radius,
                );
                context.lineTo(target.x + x * radius, target.y + y * radius);
                context.lineTo(
                    target.x + x * radius,
                    target.y + y * (radius - 9),
                );
            }
        context.stroke();
        const label = `STARFLEET ×${count}`;
        const halfWidth = context.measureText(label).width / 2 + 4;
        context.fillText(
            label,
            Math.max(halfWidth, Math.min(width - halfWidth, target.x)),
            Math.max(4, Math.min(height - 16, target.y + radius + 5)),
        );
    }
    context.restore();
}

/**
 * Render the poisonous Borg green locked-on target markers and cybernetic focus
 * effects for any starship targeted by at least one Borg cube. A lone attacker
 * deserves the same visible warning as a coordinated group.
 * @param {number} width Arena width in CSS pixels.
 * @param {number} height Arena height in CSS pixels.
 * @returns {void}
 */
function drawBorgFocusLock(width, height) {
    if (shipFailureActive || gameWon) {
        return;
    }

    const liveCubes = borgCubes.filter((cube) => cube.alive);
    if (liveCubes.length === 0) {
        return;
    }

    const animTime = performance.now() / 1000;
    const pulse = 0.5 + 0.5 * Math.sin(animTime * 6);

    context.save();
    context.beginPath();
    context.rect(0, 0, width, height);
    context.clip();

    for (const ship of starships) {
        if (!ship.alive || ship.spawnImmunityRemaining > 0) continue;

        const focusingCubes = liveCubes.filter(
            (cube) => cube.targetStarship === ship,
        );
        const focusCount = focusingCubes.length;
        if (focusCount === 0) {
            continue;
        }

        const radius =
            ship.radius + BORG_FOCUS_LOCK_BRACKET_PADDING + pulse * 2.5;
        const cornerLength = 9;

        // 1. Poisonous Borg green telemetry laser beams converging from focusing cubes
        context.strokeStyle = BORG_FOCUS_LOCK_BEAM;
        context.lineWidth = 1.5;
        context.setLineDash([4, 6]);
        context.lineDashOffset = -animTime * 36;
        for (const cube of focusingCubes) {
            context.beginPath();
            context.moveTo(cube.x, cube.y);
            context.lineTo(ship.x, ship.y);
            context.stroke();
        }
        context.setLineDash([]);

        // 2. Faint toxic green scanning aura behind the targeted ship
        context.fillStyle = `rgba(119, 255, 136, ${0.06 + pulse * 0.05})`;
        context.beginPath();
        context.arc(ship.x, ship.y, radius, 0, Math.PI * 2);
        context.fill();

        // 3. Rotating segmented cybernetic reticle ring
        const rotationAngle = animTime * BORG_FOCUS_LOCK_ROTATION_SPEED;
        context.strokeStyle = BORG_FOCUS_LOCK_COLOR;
        context.lineWidth = 2;
        context.beginPath();
        for (let arcIndex = 0; arcIndex < 4; arcIndex += 1) {
            const startAngle = rotationAngle + (arcIndex * Math.PI) / 2 + 0.18;
            const endAngle = startAngle + Math.PI / 2 - 0.36;
            context.arc(ship.x, ship.y, radius - 2, startAngle, endAngle);
        }
        context.stroke();

        // 4. Cybernetic square corner brackets framing the ship
        context.strokeStyle = BORG_FOCUS_LOCK_ACCENT;
        context.lineWidth = 2.5;
        const halfBox = radius + 3;
        context.beginPath();
        // Top-Left corner
        context.moveTo(ship.x - halfBox, ship.y - halfBox + cornerLength);
        context.lineTo(ship.x - halfBox, ship.y - halfBox);
        context.lineTo(ship.x - halfBox + cornerLength, ship.y - halfBox);
        // Top-Right corner
        context.moveTo(ship.x + halfBox - cornerLength, ship.y - halfBox);
        context.lineTo(ship.x + halfBox, ship.y - halfBox);
        context.lineTo(ship.x + halfBox, ship.y - halfBox + cornerLength);
        // Bottom-Right corner
        context.moveTo(ship.x + halfBox, ship.y + halfBox - cornerLength);
        context.lineTo(ship.x + halfBox, ship.y + halfBox);
        context.lineTo(ship.x + halfBox - cornerLength, ship.y + halfBox);
        // Bottom-Left corner
        context.moveTo(ship.x - halfBox + cornerLength, ship.y + halfBox);
        context.lineTo(ship.x - halfBox, ship.y + halfBox);
        context.lineTo(ship.x - halfBox, ship.y + halfBox - cornerLength);
        context.stroke();

        // 5. Poisonous Borg HUD telemetry lock badge
        const badgeX = ship.x + halfBox + 6;
        const badgeY = ship.y - halfBox;
        const badgeWidth = 96;
        const badgeHeight = 22;

        context.fillStyle = "rgba(10, 26, 14, 0.88)";
        context.strokeStyle = BORG_FOCUS_LOCK_COLOR;
        context.lineWidth = 1;
        context.beginPath();
        context.roundRect(
            badgeX,
            badgeY,
            badgeWidth,
            badgeHeight,
            [2, 6, 6, 2],
        );
        context.fill();
        context.stroke();

        context.textAlign = "left";
        context.textBaseline = "middle";
        context.fillStyle = BORG_FOCUS_LOCK_ACCENT;
        context.font = `700 12px ${LCARS_FONT_FAMILY}`;
        context.fillText(`BORG FOCUS x${focusCount}`, badgeX + 7, badgeY + 11);

        // Status pips for each focusing cube
        for (let pipIndex = 0; pipIndex < focusCount; pipIndex += 1) {
            const pipX = badgeX + badgeWidth - 8 - pipIndex * 7;
            const pipY = badgeY + 11;
            context.fillStyle = BORG_FOCUS_LOCK_COLOR;
            context.beginPath();
            context.arc(pipX, pipY, 2, 0, Math.PI * 2);
            context.fill();
        }
    }

    context.restore();
}

/**
 * Draw one LCARS control button with a large command and smaller action.
 * Active controls receive a bright inset, keeping their base color and label
 * readable while making held manual and autopilot input equally visible.
 * @param {number} x Left edge in CSS pixels.
 * @param {number} y Top edge in CSS pixels.
 * @param {number} width Button width in CSS pixels.
 * @param {number} height Button height in CSS pixels.
 * @param {string} title Large command label.
 * @param {string} detail Small action label.
 * @param {string} color Resting LCARS fill color.
 * @param {boolean} active Whether the control is currently engaged.
 * @param {boolean} [leftCap=false] Whether to round the left end of the row.
 * @returns {void}
 */
function drawFlightControlButton(
    x,
    y,
    width,
    height,
    title,
    detail,
    color,
    active,
    leftCap = false,
) {
    context.save();
    context.fillStyle = color;
    context.beginPath();
    context.roundRect(x, y, width, height, leftCap ? [height / 2, 4, 4, 4] : 4);
    context.fill();

    if (active) {
        context.strokeStyle = LCARS_TEXT;
        context.lineWidth = FLIGHT_CONTROL_ACTIVE_INSET;
        context.beginPath();
        context.roundRect(
            x + FLIGHT_CONTROL_ACTIVE_INSET / 2,
            y + FLIGHT_CONTROL_ACTIVE_INSET / 2,
            Math.max(0, width - FLIGHT_CONTROL_ACTIVE_INSET),
            Math.max(0, height - FLIGHT_CONTROL_ACTIVE_INSET),
            leftCap ? [height / 2, 3, 3, 3] : 3,
        );
        context.stroke();
    }

    const horizontalPadding = Math.min(16, Math.max(7, width * 0.12));
    context.textAlign = "left";
    context.textBaseline = "middle";
    context.fillStyle = LCARS_BLACK;
    context.font = `${FLIGHT_CONTROL_TITLE_WEIGHT} 21px ${LCARS_FONT_FAMILY}`;
    context.fillText(
        title,
        x + horizontalPadding,
        y + 22,
        width - horizontalPadding * 2,
    );
    context.font = `${FLIGHT_CONTROL_DETAIL_WEIGHT} 12px ${LCARS_BODY_FONT_FAMILY}`;
    context.fillText(
        detail,
        x + horizontalPadding,
        y + 42,
        width - horizontalPadding * 2,
    );
    context.restore();
}

/**
 * Draw the persistent flight-control row. Gameplay buttons read the effective
 * key set shared by manual helm and autopilot. Each cap recognizes both keys
 * for its gameplay action, so arrow-key input is represented as faithfully as
 * the labelled WASD shortcut without adding a second state model.
 * @param {number} width The viewport width in CSS pixels.
 * @returns {number|undefined} Right edge of the final control button.
 */
function drawFlightControls(width) {
    if (width <= LCARS_FRAME_MARGIN * 2) {
        return undefined;
    }

    const titleWidth = Math.min(
        LCARS_MODE_WIDTH,
        Math.max(0, width - LCARS_FRAME_MARGIN * 2),
    );
    const statusWidth = Math.min(
        STATUS_BAR_WIDTH,
        Math.max(0, width - LCARS_FRAME_MARGIN * 2 - titleWidth - 12),
    );
    const rowWidth = Math.max(
        0,
        width - LCARS_FRAME_MARGIN * 2 - statusWidth - FLIGHT_CONTROL_GAP,
    );
    const keyButtonCount = 9;
    const desiredKeyWidth = FLIGHT_CONTROL_KEY_WIDTH;
    const rowScale = Math.min(
        1,
        rowWidth /
        (titleWidth +
            desiredKeyWidth * keyButtonCount +
            FLIGHT_CONTROL_GAP * keyButtonCount),
    );
    const buttonHeight = STATUS_BARS_HEIGHT;
    let buttonX = LCARS_FRAME_MARGIN;
    const controls = [
        [
            AUTOPILOT_TOGGLE_KEY_LABEL,
            "AUTOPILOT",
            LCARS_AMBER,
            playerShip.controls.autopilotEnabled,
        ],
        [
            AUTO_GUNNER_TOGGLE_KEY_LABEL,
            "AUTO-GUNNER",
            LCARS_GOLD,
            playerShip.controls.autoGunnerEnabled,
        ],
        [PAUSE_KEY_LABEL, "PAUSE", LCARS_CORAL, gamePaused],
        [
            AIM_ASSIST_TOGGLE_KEY_LABEL,
            "AIM ASSIST",
            LCARS_GOLD,
            playerShip.aimAssist.enabled,
        ],
        [
            "W⏶",
            "THRUST",
            LCARS_LILAC,
            playerShip.controls.pressedKeys.has("KeyW") ||
            playerShip.controls.pressedKeys.has("ArrowUp"),
        ],
        [
            "S⏷",
            "BRAKE",
            LCARS_LAVENDER,
            playerShip.controls.pressedKeys.has("KeyS") ||
            playerShip.controls.pressedKeys.has("ArrowDown"),
        ],
        [
            "A⏴",
            "TURN CCW",
            LCARS_LILAC,
            playerShip.controls.pressedKeys.has("KeyA") ||
            playerShip.controls.pressedKeys.has("ArrowLeft"),
        ],
        [
            "D⏵",
            "TURN CW",
            LCARS_LAVENDER,
            playerShip.controls.pressedKeys.has("KeyD") ||
            playerShip.controls.pressedKeys.has("ArrowRight"),
        ],
        [
            FIRE_KEY_LABEL,
            playerShip.phaserHeat <= COLLISION_EPSILON
                ? "PHASERS"
                : playerShip.phaserHeat >= PHASER_OVERHEAT_THRESHOLD
                    ? `HOT ${Math.max(0, (playerShip.phaserHeat - PHASER_OVERHEAT_THRESHOLD) / PHASER_COOLING_RATE).toFixed(1)}s`
                    : `HEAT ${Math.round((playerShip.phaserHeat / PHASER_OVERHEAT_THRESHOLD) * 100)}%`,
            playerShip.phaserHeat >= PHASER_OVERHEAT_THRESHOLD
                ? LCARS_CORAL
                : LCARS_AMBER,
            playerShip.controls.pressedKeys.has(FIRE_KEY),
        ],
    ];

    drawFlightControlButton(
        buttonX,
        LCARS_CONSOLE_TOP,
        titleWidth * rowScale,
        buttonHeight,
        "HELM CONTROL",
        playerShip.controls.wallAvoidanceActive ||
            playerShip.controls.autopilotEnabled
            ? "AUTOPILOT"
            : "MANUAL HELM",
        playerShip.controls.wallAvoidanceActive ||
            playerShip.controls.autopilotEnabled
            ? LCARS_AMBER
            : LCARS_LILAC,
        playerShip.controls.autopilotEnabled ||
            playerShip.controls.wallAvoidanceActive,
        true,
    );
    buttonX += titleWidth * rowScale + FLIGHT_CONTROL_GAP * rowScale;

    for (const [title, detail, color, active] of controls) {
        drawFlightControlButton(
            buttonX,
            LCARS_CONSOLE_TOP,
            desiredKeyWidth * rowScale,
            buttonHeight,
            title,
            detail,
            color,
            active,
        );
        buttonX += desiredKeyWidth * rowScale + FLIGHT_CONTROL_GAP * rowScale;
    }

    return buttonX - FLIGHT_CONTROL_GAP * rowScale;
}

/**
 * Draw the shared, deliberately open LCARS treatment for modal information.
 * Its asymmetric corners keep the window organic while a single perimeter
 * leaves the message area completely free of decorative, functionless blocks.
 * @param {number} panelWidth Overlay width in CSS pixels.
 * @param {number} panelHeight Overlay height in CSS pixels.
 * @param {string} accent Primary state color.
 * @returns {void}
 */
function drawLCARSOverlayFrame(panelWidth, panelHeight, accent) {
    context.save();
    // A calm silhouette restores a clear window boundary. The asymmetric radius
    // order avoids a generic card while keeping every edge unambiguous.
    context.beginPath();
    context.roundRect(0, 0, panelWidth, panelHeight, [52, 16, 52, 16]);
    context.fillStyle = LCARS_PANEL;
    context.fill();
    context.lineWidth = 5;
    context.strokeStyle = accent;
    context.stroke();
    context.restore();
}

/**
 * Explain why the current life ended while the field retry is delayed. The
 * status bars are drawn afterward so their animated drainage remains visible
 * above the failure treatment.
 * @param {number} width Viewport width in CSS pixels.
 * @param {number} height Viewport height in CSS pixels.
 * @returns {void}
 */
function drawShipFailure(width, height) {
    const panelHeight =
        SHIP_FAILURE_PANEL_HEIGHT +
        Math.ceil(roundAchievements.size / ACHIEVEMENT_COLUMNS) *
            WIN_SCREEN_ACHIEVEMENT_ROW_HEIGHT;
    const failureScale = Math.max(
        0,
        Math.min(
            1,
            (width - 32) / SHIP_FAILURE_PANEL_WIDTH,
            (height - 32) / panelHeight,
        ),
    );

    context.save();
    context.fillStyle = `rgba(0, 0, 0, ${SHIP_FAILURE_BACKDROP_ALPHA})`;
    context.fillRect(0, 0, width, height);

    if (failureScale === 0) {
        context.restore();
        return;
    }

    const panelX = (width - SHIP_FAILURE_PANEL_WIDTH * failureScale) / 2;
    const panelY = (height - panelHeight * failureScale) / 2;

    context.translate(panelX, panelY);
    context.scale(failureScale, failureScale);
    drawLCARSOverlayFrame(SHIP_FAILURE_PANEL_WIDTH, panelHeight, LCARS_RED);

    context.textAlign = "center";
    context.textBaseline = "middle";
    context.fillStyle = LCARS_CORAL;
    context.font = `700 42px ${LCARS_FONT_FAMILY}`;
    context.fillText("SHIP DESTROYED", SHIP_FAILURE_PANEL_WIDTH / 2, 82);
    context.fillStyle = LCARS_TEXT;
    context.font = `500 22px ${LCARS_BODY_FONT_FAMILY}`;
    context.fillText(SHIP_FAILURE_REASON, SHIP_FAILURE_PANEL_WIDTH / 2, 142);
    drawRoundAchievements(SHIP_FAILURE_PANEL_WIDTH, 182);
    context.fillStyle = LCARS_AMBER;
    context.font = `600 23px ${LCARS_BODY_FONT_FAMILY}`;
    context.fillText(
        `RETRY ROUND IN ${Math.max(1, Math.ceil(shipFailureTimeRemaining))}`,
        SHIP_FAILURE_PANEL_WIDTH / 2,
        panelHeight - 56,
    );
    context.restore();
}

/**
 * Draw a flat LCARS achievement tile with a recognizable glyph and caption.
 * Matching asymmetric corners and segmented accents tie it to the console;
 * the name preserves meaning without requiring the player to guess the icon.
 * @param {Readonly<RoundAchievement>} achievement Unlocked catalog entry.
 * @param {number} x Left edge of the badge in panel coordinates.
 * @param {number} y Top edge of the badge in panel coordinates.
 * @returns {void}
 */
function drawAchievementBadge(achievement, x, y) {
    const iconX = (ACHIEVEMENT_BADGE_WIDTH - ACHIEVEMENT_ICON_SIZE) / 2;

    context.save();
    context.translate(x, y);
    context.fillStyle = achievement.color;
    context.beginPath();
    context.roundRect(
        iconX,
        0,
        ACHIEVEMENT_ICON_SIZE,
        ACHIEVEMENT_ICON_SIZE,
        [24, 6, 24, 6],
    );
    context.fill();
    context.save();
    context.translate(iconX, 0);
    context.scale(
        ACHIEVEMENT_ICON_SIZE / ACHIEVEMENT_GLYPH_SIZE,
        ACHIEVEMENT_ICON_SIZE / ACHIEVEMENT_GLYPH_SIZE,
    );
    context.fillStyle = LCARS_BLACK;
    context.fill(achievement.glyph);
    context.restore();

    context.fillStyle = achievement.id === "friendly-fire" ? LCARS_BLACK : LCARS_LILAC;
    context.fillRect(iconX, ACHIEVEMENT_ICON_SIZE + 6, 24, 4);
    context.fillRect(iconX + 30, ACHIEVEMENT_ICON_SIZE + 6, 42, 4);
    context.textAlign = "center";
    context.textBaseline = "middle";
    context.fillStyle = LCARS_TEXT;
    context.font = `700 18px ${LCARS_FONT_FAMILY}`;
    context.fillText(
        achievement.title,
        ACHIEVEMENT_BADGE_WIDTH / 2,
        ACHIEVEMENT_ICON_SIZE + 30,
        ACHIEVEMENT_BADGE_WIDTH,
    );
    context.restore();
}

/**
 * Draw the completed round's badges on victory and destruction screens.
 * @param {number} panelWidth Result panel width in logical pixels.
 * @param {number} y Collection heading center in logical pixels.
 * @returns {void}
 */
function drawRoundAchievements(panelWidth, y) {
    const unlockedAchievements = ROUND_ACHIEVEMENTS.filter((achievement) =>
        roundAchievements.has(achievement.id),
    );
    if (unlockedAchievements.length === 0) return;

    context.fillStyle = LCARS_LILAC;
    context.font = `600 18px ${LCARS_BODY_FONT_FAMILY}`;
    context.fillText("ACHIEVEMENTS", panelWidth / 2, y);
    for (const [index, achievement] of unlockedAchievements.entries()) {
        const row = Math.floor(index / ACHIEVEMENT_COLUMNS);
        const column = index % ACHIEVEMENT_COLUMNS;
        const rowCount = Math.min(
            ACHIEVEMENT_COLUMNS,
            unlockedAchievements.length - row * ACHIEVEMENT_COLUMNS,
        );
        // Center incomplete rows too, so a single unlock feels deliberate and
        // future icons never leave an awkward empty side of the collection.
        const rowWidth =
            rowCount * ACHIEVEMENT_BADGE_WIDTH +
            (rowCount - 1) * ACHIEVEMENT_BADGE_GAP;
        const badgeX =
            (panelWidth - rowWidth) / 2 +
            column * (ACHIEVEMENT_BADGE_WIDTH + ACHIEVEMENT_BADGE_GAP);
        const badgeY = y + 26 + row * WIN_SCREEN_ACHIEVEMENT_ROW_HEIGHT;

        drawAchievementBadge(achievement, badgeX, badgeY);
    }
}

/**
 * Draw the final result over the empty arena and keep the restart instruction
 * aligned with the pause control used everywhere else in the game.
 * @param {number} width Viewport width in CSS pixels.
 * @param {number} height Viewport height in CSS pixels.
 * @returns {void}
 */
function drawWinScreen(width, height) {
    const unlockedAchievements = ROUND_ACHIEVEMENTS.filter((achievement) =>
        roundAchievements.has(achievement.id),
    );
    const panelHeight =
        WIN_SCREEN_PANEL_HEIGHT +
        Math.ceil(unlockedAchievements.length / ACHIEVEMENT_COLUMNS) *
        WIN_SCREEN_ACHIEVEMENT_ROW_HEIGHT;
    const winScale = Math.max(
        0,
        Math.min(
            1,
            (width - 32) / WIN_SCREEN_PANEL_WIDTH,
            (height - 32) / panelHeight,
        ),
    );

    context.save();
    context.fillStyle = `rgba(0, 0, 0, ${WIN_SCREEN_BACKDROP_ALPHA})`;
    context.fillRect(0, 0, width, height);

    if (winScale === 0) {
        context.restore();
        return;
    }

    const panelX = (width - WIN_SCREEN_PANEL_WIDTH * winScale) / 2;
    const panelY = (height - panelHeight * winScale) / 2;

    context.translate(panelX, panelY);
    context.scale(winScale, winScale);
    drawLCARSOverlayFrame(WIN_SCREEN_PANEL_WIDTH, panelHeight, LCARS_LILAC);

    context.textAlign = "center";
    context.textBaseline = "middle";
    context.fillStyle = LCARS_GOLD;
    context.font = `700 46px ${LCARS_FONT_FAMILY}`;
    context.fillText(WIN_SCREEN_TITLE, WIN_SCREEN_PANEL_WIDTH / 2, 86);
    context.fillStyle = LCARS_TEXT;
    context.font = `500 22px ${LCARS_BODY_FONT_FAMILY}`;
    context.fillText(
        `PRESS ${PAUSE_KEY_LABEL} FOR NEXT ROUND`,
        WIN_SCREEN_PANEL_WIDTH / 2,
        144,
    );
    drawRoundAchievements(WIN_SCREEN_PANEL_WIDTH, 184);
    context.restore();
}

/**
 * Draw a responsive pause screen over the frozen game and list every key
 * needed to play. Never add anything except controls to this pause screen.
 * The render loop keeps calling this while paused, so the
 * help remains visible after resize and for every later pause.
 * @param {number} width The viewport width in CSS pixels.
 * @param {number} height The viewport height in CSS pixels.
 * @returns {void}
 */
function drawPauseHelp(width, height) {
    const helpScale = Math.max(
        0,
        Math.min(
            1,
            (width - 32) / HELP_PANEL_WIDTH,
            (height - 32) / HELP_PANEL_HEIGHT,
        ),
    );
    const panelWidth = HELP_PANEL_WIDTH * helpScale;
    const panelHeight = HELP_PANEL_HEIGHT * helpScale;
    const panelX = (width - panelWidth) / 2;
    const panelY = (height - panelHeight) / 2;

    context.save();
    // Keep the frozen phrase visible under both layers of the help treatment:
    // the screen veil dims motion behind it, while the panel remains readable
    // without turning the asteroid composition into an opaque black rectangle.
    context.fillStyle = `rgba(0, 0, 0, ${PAUSE_BACKDROP_ALPHA})`;
    context.fillRect(0, 0, width, height);

    if (helpScale === 0) {
        context.restore();
        return;
    }

    context.translate(panelX, panelY);
    context.scale(helpScale, helpScale);
    drawLCARSOverlayFrame(HELP_PANEL_WIDTH, HELP_PANEL_HEIGHT, LCARS_LAVENDER);

    context.textAlign = "center";
    context.textBaseline = "middle";
    context.fillStyle = LCARS_GOLD;
    context.font = `800 32px ${LCARS_FONT_FAMILY}`;
    context.fillText("SIMULATION PAUSED", HELP_PANEL_WIDTH / 2, 82);
    context.fillStyle = LCARS_LILAC;
    context.font = `600 18px ${LCARS_BODY_FONT_FAMILY}`;
    context.fillText(
        `Press ${PAUSE_KEY_LABEL} to resume`,
        HELP_PANEL_WIDTH / 2,
        112,
    );

    context.textAlign = "left";
    context.font = `700 18px ${LCARS_FONT_FAMILY}`;
    for (let helpIndex = 0; helpIndex < PLAY_HELP.length; helpIndex += 1) {
        const helpItem = PLAY_HELP[helpIndex];
        const rowY = 166 + helpIndex * 42;

        context.fillStyle = helpIndex % 2 === 0 ? LCARS_AMBER : LCARS_LILAC;
        context.beginPath();
        context.roundRect(70, rowY - 16, 112, 30, [15, 3, 3, 15]);
        context.fill();
        context.fillStyle = LCARS_BLACK;
        context.fillText(helpItem.label, 82, rowY);
        context.fillStyle = LCARS_TEXT;
        context.font = `500 18px ${LCARS_BODY_FONT_FAMILY}`;
        context.fillText(helpItem.description, 208, rowY);
        context.font = `700 18px ${LCARS_FONT_FAMILY}`;
    }
    context.restore();
}

/**
 * Move one scalar body coordinate without allocating a result object. This is
 * the hot path used by every moving body on every frame; the loop retains the
 * defensive multi-bounce behavior for tiny viewports.
 * @param {PhysicsBody} body Body whose coordinate and velocity are updated.
 * @param {"x"|"y"} positionProperty Coordinate property to advance.
 * @param {"velocityX"|"velocityY"} velocityProperty Matching velocity property.
 * @param {number} displacement Signed coordinate displacement.
 * @param {number} minimum Inclusive lower coordinate bound.
 * @param {number} maximum Inclusive upper coordinate bound.
 * @param {number} [bounceCoefficient] Normal velocity multiplier without a callback.
 * @param {(normal: Vector2) => void} [onCollision] Contact handler for each wall hit.
 * @returns {void}
 */
function advanceAndReflect(
    body,
    positionProperty,
    velocityProperty,
    displacement,
    minimum,
    maximum,
    bounceCoefficient = 1,
    onCollision,
) {
    if (maximum <= minimum) {
        body[positionProperty] = (minimum + maximum) / 2;
        return;
    }

    let nextPosition = body[positionProperty] + displacement;
    let directionMultiplier = 1;

    while (nextPosition < minimum || nextPosition > maximum) {
        if (nextPosition < minimum) {
            nextPosition = minimum + (minimum - nextPosition);
            directionMultiplier *= -1;
            body[positionProperty] = minimum;
            if (onCollision === undefined) {
                body[velocityProperty] *= bounceCoefficient;
            } else {
                onCollision(
                    positionProperty === "x" ? {x: -1, y: 0} : {x: 0, y: -1},
                );
            }
        }

        if (nextPosition > maximum) {
            nextPosition = maximum - (nextPosition - maximum);
            directionMultiplier *= -1;
            body[positionProperty] = maximum;
            if (onCollision === undefined) {
                body[velocityProperty] *= bounceCoefficient;
            } else {
                onCollision(
                    positionProperty === "x" ? { x: 1, y: 0 } : { x: 0, y: 1 },
                );
            }
        }
    }

    body[positionProperty] = nextPosition;
    if (onCollision === undefined) {
        body[velocityProperty] *= directionMultiplier;
    }
}

/**
 * Resolve one ship-to-wall contact at the shield rim. The shared contact
 * solver applies restitution along the wall normal and a Coulomb-limited
 * friction impulse along the wall. Because the impulse is off-center, its
 * magnitude—and therefore the resulting turn and damage—depends on ship
 * momentum. The static wall has zero velocity and infinite mass, so it adds
 * no momentum of its own.
 * @param {Starship} ship Hull receiving wall damage and solver impulses.
 * @param {Vector2} normal Normal pointing from the ship toward the wall.
 * @returns {ContactResponse}
 */
function resolveShipWallContact(ship, normal) {
    const contactPoint = {
        x: ship.x + normal.x * STARSHIP_RADIUS,
        y: ship.y + normal.y * STARSHIP_RADIUS,
    };
    const beforeEnergy = bodyKineticEnergy(ship);

    const response = applyContactImpulse(
        ship,
        STATIC_WALL_BODY,
        normal,
        contactPoint,
        SHIELD_WALL_FRICTION_COEFFICIENT,
    );
    const afterEnergy = bodyKineticEnergy(ship);

    emitSparksAt(
        contactPoint,
        interactionKineticEnergyLoss(beforeEnergy, afterEnergy),
    );

    if (response.normalImpulse > COLLISION_EPSILON) {
        ship.applyCollisionDamage(contactImpulseMagnitude(response));
        empSound.playRandom();
    }
    applyShipCollisionAngleAdjustment(response, ship);
    return response;
}

/**
 * Turn the ship once at the collision moment without introducing persistent
 * angular momentum. The angular impulse still comes from the same friction
 * calculation, so greater contact momentum or friction produces a larger
 * heading adjustment.
 * @param {Starship} ship Hull receiving the one-time heading adjustment.
 * @param {ContactResponse} response Contact response involving the ship.
 * @returns {void}
 */
function applyShipCollisionAngleAdjustment(response, ship) {
    const uncappedAngleAdjustment =
        (response.firstAngularImpulse / STARSHIP_COLLISION_TURN_INERTIA) *
        SHIP_COLLISION_TURN_RESPONSE;
    const angleAdjustment = Math.max(
        -MAX_SHIP_COLLISION_TURN_ANGLE,
        Math.min(MAX_SHIP_COLLISION_TURN_ANGLE, uncappedAngleAdjustment),
    );

    if (Number.isFinite(uncappedAngleAdjustment)) {
        ship.angle = wrapAngle(ship.angle + angleAdjustment);
    }
}

/**
 * @param {Asteroid} asteroid
 * @param {number} width
 * @param {number} height
 * @returns {void}
 */
function resolveAsteroidWallCollisions(asteroid, width, height) {
    if (width <= 0 || height <= 0) {
        return;
    }

    // Rotation can make a new vertex reach a wall without the center moving.
    // Rechecking a few times handles a corner contact and a corrective shift
    // without allowing a large frame to leave the polygon embedded.
    for (let collisionPass = 0; collisionPass < 4; collisionPass += 1) {
        asteroid.collisionPolygon();
        const bounds = asteroid.worldBounds;
        let changed = false;

        const resolveWall = (normal, penetration) => {
            if (penetration > 0) {
                asteroid.x -= normal.x * penetration;
                asteroid.y -= normal.y * penetration;
                changed = true;
            }

            asteroid.collisionPolygon();
            const contactPoint = supportPoint(asteroid.worldVertices, normal);
            const beforeEnergy = bodyKineticEnergy(asteroid);
            const response = applyContactImpulse(
                asteroid,
                STATIC_WALL_BODY,
                normal,
                contactPoint,
            );
            const afterEnergy = bodyKineticEnergy(asteroid);

            emitSparksAt(
                contactPoint,
                interactionKineticEnergyLoss(beforeEnergy, afterEnergy),
            );
            changed ||= response.normalImpulse > COLLISION_EPSILON;
        };

        if (bounds.minimumX <= COLLISION_EPSILON) {
            resolveWall({x: -1, y: 0}, Math.max(0, -bounds.minimumX));
        }

        if (bounds.maximumX >= width - COLLISION_EPSILON) {
            resolveWall({x: 1, y: 0}, Math.max(0, bounds.maximumX - width));
        }

        if (bounds.minimumY <= COLLISION_EPSILON) {
            resolveWall({x: 0, y: -1}, Math.max(0, -bounds.minimumY));
        }

        if (bounds.maximumY >= height - COLLISION_EPSILON) {
            resolveWall({x: 0, y: 1}, Math.max(0, bounds.maximumY - height));
        }

        if (!changed) {
            return;
        }
    }
}

function normalizedVector(x, y, fallbackX = 1, fallbackY = 0) {
    const length = Math.hypot(x, y);

    return length <= COLLISION_EPSILON
        ? {x: fallbackX, y: fallbackY}
        : {x: x / length, y: y / length};
}

function cross2D(firstX, firstY, secondX, secondY) {
    return firstX * secondY - firstY * secondX;
}

function wrapAngle(angle) {
    const fullTurn = Math.PI * 2;
    return ((angle % fullTurn) + fullTurn) % fullTurn;
}

/** @param {PhysicsBody} body @returns {number} */
function bodyInverseMass(body) {
    return Number.isFinite(body.mass) && body.mass > COLLISION_EPSILON
        ? 1 / body.mass
        : 0;
}

/** @param {PhysicsBody} body @returns {number} */
function bodyInverseMomentOfInertia(body) {
    return Number.isFinite(body.momentOfInertia) &&
    body.momentOfInertia > COLLISION_EPSILON
        ? 1 / body.momentOfInertia
        : 0;
}

/** @param {PhysicsBody} body @returns {number} */
function bodyAngularVelocity(body) {
    return body.angularVelocity ?? 0;
}

/**
 * @param {PhysicsBody} body
 * @param {number} [originX]
 * @param {number} [originY]
 * @returns {number}
 */
function bodyAngularMomentum(body, originX = 0, originY = 0) {
    const linearMomentumX = body.mass * body.velocityX;
    const linearMomentumY = body.mass * body.velocityY;
    const orbitalMomentum = cross2D(
        body.x - originX,
        body.y - originY,
        linearMomentumX,
        linearMomentumY,
    );
    const spinMomentum = Number.isFinite(body.momentOfInertia)
        ? body.momentOfInertia * bodyAngularVelocity(body)
        : 0;

    return orbitalMomentum + spinMomentum;
}

/** @param {PhysicsBody} body @returns {number} */
function bodyKineticEnergy(body) {
    const linearEnergy =
        0.5 * body.mass * (body.velocityX ** 2 + body.velocityY ** 2);
    const rotationalEnergy = Number.isFinite(body.momentOfInertia)
        ? 0.5 * body.momentOfInertia * bodyAngularVelocity(body) ** 2
        : 0;

    return linearEnergy + rotationalEnergy;
}

/** @param {PhysicsBody} body @param {Vector2} point @returns {Vector2} */
function velocityAtPoint(body, point) {
    const offsetX = point.x - body.x;
    const offsetY = point.y - body.y;
    const angularVelocity = bodyAngularVelocity(body);

    return {
        x: body.velocityX - angularVelocity * offsetY,
        y: body.velocityY + angularVelocity * offsetX,
    };
}

/**
 * @param {PhysicsBody} body
 * @param {number} impulseX
 * @param {number} impulseY
 * @param {Vector2} contactPoint
 * @returns {void}
 */
function applyBodyImpulse(body, impulseX, impulseY, contactPoint) {
    const inverseMass = bodyInverseMass(body);
    body.velocityX += impulseX * inverseMass;
    body.velocityY += impulseY * inverseMass;

    const inverseMomentOfInertia = bodyInverseMomentOfInertia(body);

    if (inverseMomentOfInertia > 0 && body.angularVelocity !== undefined) {
        const offsetX = contactPoint.x - body.x;
        const offsetY = contactPoint.y - body.y;
        body.angularVelocity +=
            cross2D(offsetX, offsetY, impulseX, impulseY) * inverseMomentOfInertia;
    }
}

/**
 * @param {PhysicsBody} firstBody
 * @param {PhysicsBody} secondBody
 * @param {number} angularMomentumBefore
 * @returns {void}
 */
function restoreAngularMomentumAfterPositionCorrection(
    firstBody,
    secondBody,
    angularMomentumBefore,
) {
    const angularMomentumAfter =
        bodyAngularMomentum(firstBody) + bodyAngularMomentum(secondBody);
    const angularMomentumCorrection =
        angularMomentumBefore - angularMomentumAfter;
    const firstMoment = Number.isFinite(firstBody.momentOfInertia)
        ? firstBody.momentOfInertia
        : 0;
    const secondMoment = Number.isFinite(secondBody.momentOfInertia)
        ? secondBody.momentOfInertia
        : 0;
    const totalMoment = firstMoment + secondMoment;

    if (totalMoment <= COLLISION_EPSILON) {
        return;
    }

    // Positional overlap correction is a solver convenience rather than a
    // physical impulse. Give its orbital angular-momentum drift back as spin
    // before the real contact response, keeping the isolated pair exactly
    // conservative even when the bodies arrived with tangential momentum.
    const angularVelocityCorrection = angularMomentumCorrection / totalMoment;

    if (firstBody.angularVelocity !== undefined && firstMoment > 0) {
        firstBody.angularVelocity += angularVelocityCorrection;
    }

    if (secondBody.angularVelocity !== undefined && secondMoment > 0) {
        secondBody.angularVelocity += angularVelocityCorrection;
    }
}

function polygonArea(vertices) {
    let twiceArea = 0;

    for (let vertexIndex = 0; vertexIndex < vertices.length; vertexIndex += 1) {
        const firstVertex = vertices[vertexIndex];
        const secondVertex = vertices[(vertexIndex + 1) % vertices.length];
        twiceArea += cross2D(
            firstVertex.x,
            firstVertex.y,
            secondVertex.x,
            secondVertex.y,
        );
    }

    return Math.abs(twiceArea) / 2;
}

/**
 * Return the unit-density polar second moment of a polygon about the origin.
 * Asteroid vertices are centered before this is called, so the result is the
 * rigid body's mass moment of inertia about its center of mass.
 */
/** @param {Vector2[]} vertices @returns {number} */
function polygonMassMomentOfInertia(vertices) {
    let signedMoment = 0;

    for (let vertexIndex = 0; vertexIndex < vertices.length; vertexIndex += 1) {
        const firstVertex = vertices[vertexIndex];
        const secondVertex = vertices[(vertexIndex + 1) % vertices.length];
        const edgeCross = cross2D(
            firstVertex.x,
            firstVertex.y,
            secondVertex.x,
            secondVertex.y,
        );
        const squaredRadiusSum =
            firstVertex.x ** 2 +
            firstVertex.x * secondVertex.x +
            secondVertex.x ** 2 +
            firstVertex.y ** 2 +
            firstVertex.y * secondVertex.y +
            secondVertex.y ** 2;

        signedMoment += edgeCross * squaredRadiusSum;
    }

    return Math.abs(signedMoment) / 12;
}

function polygonBounds(vertices) {
    const bounds = {
        minimumX: 0,
        maximumX: 0,
        minimumY: 0,
        maximumY: 0,
    };

    return updatePolygonBounds(bounds, vertices);
}

/**
 * @param {{minimumX: number, maximumX: number, minimumY: number, maximumY: number}} bounds
 * @param {Vector2[]} vertices
 * @returns {typeof bounds}
 */
function updatePolygonBounds(bounds, vertices) {
    let minimumX = Infinity;
    let maximumX = -Infinity;
    let minimumY = Infinity;
    let maximumY = -Infinity;

    for (const vertex of vertices) {
        minimumX = Math.min(minimumX, vertex.x);
        maximumX = Math.max(maximumX, vertex.x);
        minimumY = Math.min(minimumY, vertex.y);
        maximumY = Math.max(maximumY, vertex.y);
    }

    bounds.minimumX = minimumX;
    bounds.maximumX = maximumX;
    bounds.minimumY = minimumY;
    bounds.maximumY = maximumY;
    return bounds;
}

function polygonCentroid(vertices) {
    let twiceArea = 0;
    let centroidX = 0;
    let centroidY = 0;

    for (let vertexIndex = 0; vertexIndex < vertices.length; vertexIndex += 1) {
        const firstVertex = vertices[vertexIndex];
        const secondVertex = vertices[(vertexIndex + 1) % vertices.length];
        const edgeCross = cross2D(
            firstVertex.x,
            firstVertex.y,
            secondVertex.x,
            secondVertex.y,
        );

        twiceArea += edgeCross;
        centroidX += (firstVertex.x + secondVertex.x) * edgeCross;
        centroidY += (firstVertex.y + secondVertex.y) * edgeCross;
    }

    if (Math.abs(twiceArea) <= COLLISION_EPSILON) {
        const average = vertices.reduce(
            (sum, vertex) => ({x: sum.x + vertex.x, y: sum.y + vertex.y}),
            {x: 0, y: 0},
        );

        return {
            x: average.x / vertices.length,
            y: average.y / vertices.length,
        };
    }

    return {
        x: centroidX / (3 * twiceArea),
        y: centroidY / (3 * twiceArea),
    };
}

function cleanPolygon(vertices) {
    const cleanedVertices = [];

    for (const vertex of vertices) {
        const previousVertex = cleanedVertices.at(-1);

        if (
            previousVertex === undefined ||
            Math.hypot(
                vertex.x - previousVertex.x,
                vertex.y - previousVertex.y,
            ) > COLLISION_EPSILON
        ) {
            cleanedVertices.push(vertex);
        }
    }

    if (cleanedVertices.length > 1) {
        const firstVertex = cleanedVertices[0];
        const lastVertex = cleanedVertices.at(-1);

        if (
            Math.hypot(
                lastVertex.x - firstVertex.x,
                lastVertex.y - firstVertex.y,
            ) <= COLLISION_EPSILON
        ) {
            cleanedVertices.pop();
        }
    }

    return cleanedVertices;
}

/**
 * Clip a convex polygon against one side of the bullet's infinite path. The
 * two clipped polygons retain the original boundary vertices and gain the
 * two new cut intersections, so the visible geometry really is divided by
 * the projectile's line instead of merely replaced with smaller circles.
 */
function clipPolygonByLine(
    vertices,
    linePoint,
    lineDirection,
    keepPositiveSide,
) {
    const clippedVertices = [];
    const sideMultiplier = keepPositiveSide ? 1 : -1;

    for (let vertexIndex = 0; vertexIndex < vertices.length; vertexIndex += 1) {
        const firstVertex = vertices[vertexIndex];
        const secondVertex = vertices[(vertexIndex + 1) % vertices.length];
        const firstSide =
            sideMultiplier *
            cross2D(
                lineDirection.x,
                lineDirection.y,
                firstVertex.x - linePoint.x,
                firstVertex.y - linePoint.y,
            );
        const secondSide =
            sideMultiplier *
            cross2D(
                lineDirection.x,
                lineDirection.y,
                secondVertex.x - linePoint.x,
                secondVertex.y - linePoint.y,
            );
        const firstInside = firstSide >= -COLLISION_EPSILON;
        const secondInside = secondSide >= -COLLISION_EPSILON;

        if (firstInside !== secondInside) {
            const sideDifference = firstSide - secondSide;

            if (Math.abs(sideDifference) > COLLISION_EPSILON) {
                const intersectionRatio = firstSide / sideDifference;
                clippedVertices.push({
                    x:
                        firstVertex.x +
                        (secondVertex.x - firstVertex.x) * intersectionRatio,
                    y:
                        firstVertex.y +
                        (secondVertex.y - firstVertex.y) * intersectionRatio,
                });
            }
        }

        if (secondInside) {
            clippedVertices.push({x: secondVertex.x, y: secondVertex.y});
        }
    }

    return cleanPolygon(clippedVertices);
}

/**
 * Return the first normalized position at which a segment enters a convex
 * polygon. Half-plane clipping makes this a swept hit test, avoiding the
 * tunnelling a fast bullet would cause if only its final position were used.
 */
function segmentPolygonIntersectionParameter(start, end, vertices) {
    if (vertices.length < 3) {
        return undefined;
    }

    const direction = {
        x: end.x - start.x,
        y: end.y - start.y,
    };
    let polygonTwiceArea = 0;

    for (let vertexIndex = 0; vertexIndex < vertices.length; vertexIndex += 1) {
        const firstVertex = vertices[vertexIndex];
        const secondVertex = vertices[(vertexIndex + 1) % vertices.length];
        polygonTwiceArea += cross2D(
            firstVertex.x,
            firstVertex.y,
            secondVertex.x,
            secondVertex.y,
        );
    }

    if (Math.abs(polygonTwiceArea) <= COLLISION_EPSILON) {
        return undefined;
    }

    const orientation = polygonTwiceArea < 0 ? -1 : 1;
    let minimumParameter = 0;
    let maximumParameter = 1;

    for (let vertexIndex = 0; vertexIndex < vertices.length; vertexIndex += 1) {
        const firstVertex = vertices[vertexIndex];
        const secondVertex = vertices[(vertexIndex + 1) % vertices.length];
        const edgeX = secondVertex.x - firstVertex.x;
        const edgeY = secondVertex.y - firstVertex.y;
        const startSide =
            orientation *
            cross2D(
                edgeX,
                edgeY,
                start.x - firstVertex.x,
                start.y - firstVertex.y,
            );
        const sideRate =
            orientation * cross2D(edgeX, edgeY, direction.x, direction.y);

        if (Math.abs(sideRate) <= COLLISION_EPSILON) {
            if (startSide < -COLLISION_EPSILON) {
                return undefined;
            }

            continue;
        }

        const boundaryParameter = (-COLLISION_EPSILON - startSide) / sideRate;

        if (sideRate > 0) {
            minimumParameter = Math.max(minimumParameter, boundaryParameter);
        } else {
            maximumParameter = Math.min(maximumParameter, boundaryParameter);
        }

        if (minimumParameter > maximumParameter + COLLISION_EPSILON) {
            return undefined;
        }
    }

    return minimumParameter <= 1 + COLLISION_EPSILON
        ? Math.min(1, Math.max(0, minimumParameter))
        : undefined;
}

/**
 * Return the first normalized position at which a segment reaches a circle.
 * Bullets use this swept test for the ship as well as the polygon test above,
 * so a fast projectile cannot pass through the circular hull between frames.
 */
function segmentCircleIntersectionParameter(start, end, circle) {
    const directionX = end.x - start.x;
    const directionY = end.y - start.y;
    const offsetX = start.x - circle.x;
    const offsetY = start.y - circle.y;
    const directionLengthSquared = directionX ** 2 + directionY ** 2;
    const radiusSquared = circle.radius ** 2;

    if (offsetX ** 2 + offsetY ** 2 <= radiusSquared) {
        return 0;
    }

    if (directionLengthSquared <= COLLISION_EPSILON) {
        return undefined;
    }

    const projectedOffset = offsetX * directionX + offsetY * directionY;
    const discriminant =
        projectedOffset ** 2 -
        directionLengthSquared * (offsetX ** 2 + offsetY ** 2 - radiusSquared);

    if (discriminant < -COLLISION_EPSILON) {
        return undefined;
    }

    const squareRootDiscriminant = Math.sqrt(Math.max(0, discriminant));
    const firstParameter =
        (-projectedOffset - squareRootDiscriminant) / directionLengthSquared;
    const secondParameter =
        (-projectedOffset + squareRootDiscriminant) / directionLengthSquared;

    if (firstParameter >= -COLLISION_EPSILON && firstParameter <= 1) {
        return Math.max(0, firstParameter);
    }

    return secondParameter >= -COLLISION_EPSILON && secondParameter <= 1
        ? Math.max(0, secondParameter)
        : undefined;
}

/**
 * Split a rock after the contact solver has transferred the impact impulse.
 * Blasters cut along their incoming path; body impacts use the contact normal.
 * Every qualifying impact destroys terminal rocks and discards small fragments.
 * @param {Asteroid} asteroid Rock whose post-impact motion fragments inherit.
 * @param {Vector2} hitPoint Contact point through which the cut passes.
 * @param {Vector2} cutDirection Unit direction of the impact's cut line.
 * @returns {Asteroid[]} Fragments retained by the minimum-area rule.
 */
function splitAsteroid(asteroid, hitPoint, cutDirection) {
    if (asteroid.localVertices.length <= 3) {
        return [];
    }

    const asteroidVertices = asteroid.collisionPolygon();
    let firstPolygon = clipPolygonByLine(
        asteroidVertices,
        hitPoint,
        cutDirection,
        true,
    );
    let secondPolygon = clipPolygonByLine(
        asteroidVertices,
        hitPoint,
        cutDirection,
        false,
    );

    // A tangent or a cut exactly through a vertex can create a zero-area side
    // because of floating-point boundaries. A line through the polygon's
    // centroid is a deterministic fallback that still follows the impact's
    // direction and guarantees two real fragments for a valid convex asteroid.
    if (
        firstPolygon.length < 3 ||
        secondPolygon.length < 3 ||
        polygonArea(firstPolygon) <= COLLISION_EPSILON ||
        polygonArea(secondPolygon) <= COLLISION_EPSILON
    ) {
        const centroid = polygonCentroid(asteroidVertices);
        firstPolygon = clipPolygonByLine(
            asteroidVertices,
            centroid,
            cutDirection,
            true,
        );
        secondPolygon = clipPolygonByLine(
            asteroidVertices,
            centroid,
            cutDirection,
            false,
        );
    }

    if (
        firstPolygon.length < 3 ||
        secondPolygon.length < 3 ||
        polygonArea(firstPolygon) <= COLLISION_EPSILON ||
        polygonArea(secondPolygon) <= COLLISION_EPSILON
    ) {
        return [];
    }

    const firstArea = polygonArea(firstPolygon);
    const secondArea = polygonArea(secondPolygon);
    const totalArea = firstArea + secondArea;
    // The impacting body rebounds instead of being absorbed, so only the rock's
    // mass is distributed across its fragments. The contact solver has already
    // transferred the impulse before this split.
    const totalMass = asteroid.mass;
    const firstMass = (totalMass * firstArea) / totalArea;
    const secondMass = (totalMass * secondArea) / totalArea;
    // Each fragment inherits the parent's rigid velocity field at its own
    // centroid. Giving both fragments the parent's angular velocity preserves
    // the parent's spin and the orbital angular momentum around its center.
    const firstCenter = polygonCentroid(firstPolygon);
    const secondCenter = polygonCentroid(secondPolygon);
    const firstVelocity = velocityAtPoint(asteroid, firstCenter);
    const secondVelocity = velocityAtPoint(asteroid, secondCenter);

    // Keep the physics calculation based on the complete cut, then remove any
    // undersized result so a grazing hit cannot leave a permanent sliver.
    return [
        {
            area: firstArea,
            asteroid: createAsteroidFromPolygon(
                firstPolygon,
                firstVelocity.x,
                firstVelocity.y,
                firstMass,
                asteroid.density,
                asteroid.rotation,
                asteroid.angularVelocity,
            ),
        },
        {
            area: secondArea,
            asteroid: createAsteroidFromPolygon(
                secondPolygon,
                secondVelocity.x,
                secondVelocity.y,
                secondMass,
                asteroid.density,
                asteroid.rotation,
                asteroid.angularVelocity,
            ),
        },
    ]
        .filter(({area}) => area >= ASTEROID_MIN_FRAGMENT_AREA)
        .map(({asteroid: fragment}) => fragment);
}

/**
 * Apply fragmentation to a phaser hit or a sufficiently strong body impact.
 * Phaser contact is already established by the swept geometric hit test, so
 * it always cuts. Body contacts retain the impulse threshold that prevents
 * gentle overlaps and resting contacts from shattering the field.
 * @param {Asteroid} asteroid Rock receiving the solved contact impulse.
 * @param {Vector2} hitPoint Impact contact point in world coordinates.
 * @param {Vector2} cutDirection Unit direction of the impact's cut line.
 * @param {ContactResponse} response Impulse transferred by the contact solver.
 * @param {"phaser" | "body"} impactSource Interaction that caused the impact.
 * @returns {Asteroid[]} Original rock or retained fragments in the field.
 */
function fragmentAsteroidAtImpact(
    asteroid,
    hitPoint,
    cutDirection,
    response,
    impactSource,
) {
    const impactImpulse = contactImpulseMagnitude(response);
    if (
        impactSource !== "phaser" &&
        (!Number.isFinite(impactImpulse) ||
            impactImpulse <= ASTEROID_SPLIT_IMPULSE_THRESHOLD)
    ) {
        return [asteroid];
    }

    const asteroidIndex = asteroids.indexOf(asteroid);
    if (asteroidIndex < 0) {
        return [];
    }
    const fragments = splitAsteroid(asteroid, hitPoint, cutDirection);

    asteroids.splice(asteroidIndex, 1, ...fragments);
    for (const ship of starships)
        ship.aimAssist.followFragments(asteroid, fragments);
    return fragments;
}

function boundaryHit(start, end, width, height) {
    const directionX = end.x - start.x;
    const directionY = end.y - start.y;
    let nearestParameter = Infinity;
    let normal;

    const considerBoundary = (parameter, candidateNormal) => {
        if (
            parameter >= -COLLISION_EPSILON &&
            parameter <= 1 + COLLISION_EPSILON &&
            parameter < nearestParameter
        ) {
            nearestParameter = Math.max(0, parameter);
            normal = candidateNormal;
        }
    };

    if (directionX < -COLLISION_EPSILON) {
        considerBoundary(-start.x / directionX, {x: -1, y: 0});
    } else if (directionX > COLLISION_EPSILON) {
        considerBoundary((width - start.x) / directionX, {x: 1, y: 0});
    }

    if (directionY < -COLLISION_EPSILON) {
        considerBoundary(-start.y / directionY, {x: 0, y: -1});
    } else if (directionY > COLLISION_EPSILON) {
        considerBoundary((height - start.y) / directionY, {x: 0, y: 1});
    }

    return normal === undefined
        ? undefined
        : {parameter: nearestParameter, normal};
}

function polygonNormalAtPoint(
    vertices,
    point,
    incomingVelocityX,
    incomingVelocityY,
) {
    let polygonTwiceArea = 0;
    let nearestDistanceSquared = Infinity;
    let nearestNormal = {x: 1, y: 0};

    for (let vertexIndex = 0; vertexIndex < vertices.length; vertexIndex += 1) {
        const firstVertex = vertices[vertexIndex];
        const secondVertex = vertices[(vertexIndex + 1) % vertices.length];
        polygonTwiceArea += cross2D(
            firstVertex.x,
            firstVertex.y,
            secondVertex.x,
            secondVertex.y,
        );
    }

    for (let vertexIndex = 0; vertexIndex < vertices.length; vertexIndex += 1) {
        const firstVertex = vertices[vertexIndex];
        const secondVertex = vertices[(vertexIndex + 1) % vertices.length];
        const edgeX = secondVertex.x - firstVertex.x;
        const edgeY = secondVertex.y - firstVertex.y;
        const edgeLength = Math.hypot(edgeX, edgeY);

        if (edgeLength <= COLLISION_EPSILON) {
            continue;
        }

        const pointAlongEdge = Math.min(
            1,
            Math.max(
                0,
                ((point.x - firstVertex.x) * edgeX +
                    (point.y - firstVertex.y) * edgeY) /
                edgeLength ** 2,
            ),
        );
        const closestX = firstVertex.x + edgeX * pointAlongEdge;
        const closestY = firstVertex.y + edgeY * pointAlongEdge;
        const distanceSquared =
            (point.x - closestX) ** 2 + (point.y - closestY) ** 2;

        if (distanceSquared < nearestDistanceSquared) {
            nearestDistanceSquared = distanceSquared;
            nearestNormal =
                polygonTwiceArea >= 0
                    ? {x: edgeY / edgeLength, y: -edgeX / edgeLength}
                    : {x: -edgeY / edgeLength, y: edgeX / edgeLength};
        }
    }

    if (
        incomingVelocityX * nearestNormal.x + incomingVelocityY * nearestNormal.y >
        0
    ) {
        nearestNormal.x *= -1;
        nearestNormal.y *= -1;
    }

    return nearestNormal;
}

function circleNormalAtPoint(
    circle,
    point,
    incomingVelocityX,
    incomingVelocityY,
) {
    const fallbackNormal = normalizedVector(
        -incomingVelocityX,
        -incomingVelocityY,
    );
    const normal = normalizedVector(
        point.x - circle.x,
        point.y - circle.y,
        fallbackNormal.x,
        fallbackNormal.y,
    );

    if (incomingVelocityX * normal.x + incomingVelocityY * normal.y > 0) {
        normal.x *= -1;
        normal.y *= -1;
    }

    return normal;
}

/**
 * Apply a rigid-body contact impulse. The normal points from the first body
 * toward the second body, and the returned vector is the impulse received by
 * the second body. The same contact point drives linear motion, spin, and
 * friction, so an off-center shoulder naturally exchanges angular momentum.
 */
/**
 * @param {PhysicsBody} firstBody
 * @param {PhysicsBody} secondBody
 * @param {Vector2} normal
 * @param {Vector2} contactPoint
 * @param {number} [frictionCoefficient]
 * @returns {ContactResponse}
 */
function applyContactImpulse(
    firstBody,
    secondBody,
    normal,
    contactPoint,
    frictionCoefficient = FRICTION_COEFFICIENT,
) {
    const firstOffsetX = contactPoint.x - firstBody.x;
    const firstOffsetY = contactPoint.y - firstBody.y;
    const secondOffsetX = contactPoint.x - secondBody.x;
    const secondOffsetY = contactPoint.y - secondBody.y;
    const inverseFirstMass = bodyInverseMass(firstBody);
    const inverseSecondMass = bodyInverseMass(secondBody);
    const inverseFirstMoment = bodyInverseMomentOfInertia(firstBody);
    const inverseSecondMoment = bodyInverseMomentOfInertia(secondBody);
    const firstNormalLever = cross2D(
        firstOffsetX,
        firstOffsetY,
        normal.x,
        normal.y,
    );
    const secondNormalLever = cross2D(
        secondOffsetX,
        secondOffsetY,
        normal.x,
        normal.y,
    );
    const normalEffectiveMass =
        inverseFirstMass +
        inverseSecondMass +
        firstNormalLever ** 2 * inverseFirstMoment +
        secondNormalLever ** 2 * inverseSecondMoment;
    const firstContactVelocity = velocityAtPoint(firstBody, contactPoint);
    const secondContactVelocity = velocityAtPoint(secondBody, contactPoint);
    const relativeVelocityX = secondContactVelocity.x - firstContactVelocity.x;
    const relativeVelocityY = secondContactVelocity.y - firstContactVelocity.y;
    const relativeNormalVelocity =
        relativeVelocityX * normal.x + relativeVelocityY * normal.y;

    // A separating contact needs no impulse. Applying a response to only one
    // body would change both linear and angular momentum without a counterpart.
    if (relativeNormalVelocity >= 0 || normalEffectiveMass <= COLLISION_EPSILON) {
        return {
            x: 0,
            y: 0,
            normalImpulse: 0,
            tangentImpulse: 0,
            firstAngularImpulse: 0,
            secondAngularImpulse: 0,
        };
    }

    const normalImpulseMagnitude =
        (-(1 + BOUNCINESS) * relativeNormalVelocity) / normalEffectiveMass;
    const normalImpulseX = normalImpulseMagnitude * normal.x;
    const normalImpulseY = normalImpulseMagnitude * normal.y;

    applyBodyImpulse(firstBody, -normalImpulseX, -normalImpulseY, contactPoint);
    applyBodyImpulse(secondBody, normalImpulseX, normalImpulseY, contactPoint);

    // Friction is solved after the normal impulse so the tangent sees the
    // shoulder's updated angular velocity. Clamping it by Coulomb friction
    // keeps the contact from manufacturing energy while allowing spin transfer.
    const tangent = {x: -normal.y, y: normal.x};
    const firstNormalTangentLever = cross2D(
        firstOffsetX,
        firstOffsetY,
        tangent.x,
        tangent.y,
    );
    const secondNormalTangentLever = cross2D(
        secondOffsetX,
        secondOffsetY,
        tangent.x,
        tangent.y,
    );
    const tangentEffectiveMass =
        inverseFirstMass +
        inverseSecondMass +
        firstNormalTangentLever ** 2 * inverseFirstMoment +
        secondNormalTangentLever ** 2 * inverseSecondMoment;
    const firstPostNormalVelocity = velocityAtPoint(firstBody, contactPoint);
    const secondPostNormalVelocity = velocityAtPoint(secondBody, contactPoint);
    const relativeTangentVelocity =
        (secondPostNormalVelocity.x - firstPostNormalVelocity.x) * tangent.x +
        (secondPostNormalVelocity.y - firstPostNormalVelocity.y) * tangent.y;
    const unconstrainedTangentImpulse =
        tangentEffectiveMass > COLLISION_EPSILON
            ? -relativeTangentVelocity / tangentEffectiveMass
            : 0;
    const maximumTangentImpulse = frictionCoefficient * normalImpulseMagnitude;
    const tangentImpulseMagnitude = Math.min(
        maximumTangentImpulse,
        Math.max(-maximumTangentImpulse, unconstrainedTangentImpulse),
    );
    const tangentImpulseX = tangentImpulseMagnitude * tangent.x;
    const tangentImpulseY = tangentImpulseMagnitude * tangent.y;

    applyBodyImpulse(
        firstBody,
        -tangentImpulseX,
        -tangentImpulseY,
        contactPoint,
    );
    applyBodyImpulse(
        secondBody,
        tangentImpulseX,
        tangentImpulseY,
        contactPoint,
    );

    const impulseX = normalImpulseX + tangentImpulseX;
    const impulseY = normalImpulseY + tangentImpulseY;

    return {
        x: impulseX,
        y: impulseY,
        normalImpulse: normalImpulseMagnitude,
        tangentImpulse: tangentImpulseMagnitude,
        firstAngularImpulse: cross2D(
            firstOffsetX,
            firstOffsetY,
            -impulseX,
            -impulseY,
        ),
        secondAngularImpulse: cross2D(
            secondOffsetX,
            secondOffsetY,
            impulseX,
            impulseY,
        ),
    };
}

/**
 * Use the total impulse exchanged at a contact as the collision's momentum
 * measure. Friction is included because it is part of the same interaction.
 * @param {ContactResponse} response Contact impulse response from the solver.
 * @returns {number} Momentum transferred during the contact.
 */
function contactImpulseMagnitude(response) {
    return Math.hypot(response.x, response.y);
}

/**
 * Convert an interaction's energy bookkeeping into a non-negative spark
 * budget. Energy from bodies that are removed is added after the physical
 * response, so a disappearing body contributes its full remaining energy.
 * @param {number} beforeEnergy Total kinetic energy before the interaction.
 * @param {number} afterEnergy Total kinetic energy after the response.
 * @param {number} [removedEnergy] Kinetic energy of bodies removed afterward.
 * @returns {number} Kinetic energy converted into the visual effect.
 */
function interactionKineticEnergyLoss(
    beforeEnergy,
    afterEnergy,
    removedEnergy = 0,
) {
    const safeBeforeEnergy = Number.isFinite(beforeEnergy)
        ? Math.max(0, beforeEnergy)
        : 0;
    const safeAfterEnergy = Number.isFinite(afterEnergy)
        ? Math.max(0, afterEnergy)
        : 0;
    const safeRemovedEnergy = Number.isFinite(removedEnergy)
        ? Math.max(0, removedEnergy)
        : 0;

    return Math.max(0, safeBeforeEnergy - safeAfterEnergy + safeRemovedEnergy);
}

/**
 * Keep spark density proportional to dissipated energy while ensuring even a
 * small real loss produces a visible hit. The cap protects the frame budget
 * when the full energy of a large asteroid is converted at once.
 * @param {number} kineticEnergyLoss Energy converted into sparks.
 * @returns {number} Number of particles to emit.
 */
function sparkCountForEnergyLoss(kineticEnergyLoss) {
    if (!Number.isFinite(kineticEnergyLoss) || kineticEnergyLoss <= 0) {
        return 0;
    }

    return Math.min(
        MAX_SPARKS_PER_INTERACTION,
        Math.max(1, Math.round(kineticEnergyLoss / SPARK_ENERGY_PER_PARTICLE)),
    );
}

/**
 * Emit a random-direction burst at a contact point. The particles are
 * presentation-only, so this function intentionally does not touch bodies,
 * damage or any other gameplay state.
 * @param {Vector2} contactPoint Position of the interaction.
 * @param {number} kineticEnergyLoss Energy available for the burst.
 * @returns {void}
 */
function emitSparksAt(contactPoint, kineticEnergyLoss) {
    const safeKineticEnergyLoss = Number.isFinite(kineticEnergyLoss)
        ? Math.max(0, kineticEnergyLoss)
        : 0;
    const sparkCount = sparkCountForEnergyLoss(safeKineticEnergyLoss);
    const availableSparkSlots = Math.max(0, MAX_ACTIVE_SPARKS - sparks.length);
    const emittedSparkCount = Math.min(sparkCount, availableSparkSlots);

    for (let sparkIndex = 0; sparkIndex < emittedSparkCount; sparkIndex += 1) {
        sparks.push(new Spark(contactPoint));
    }
}

function resolveBulletCollisions(width, height) {
    for (
        let bulletIndex = bullets.length - 1;
        bulletIndex >= 0;
        bulletIndex -= 1
    ) {
        const bullet = bullets[bulletIndex];
        let segmentStart = {x: bullet.previousX, y: bullet.previousY};
        let segmentEnd = {x: bullet.x, y: bullet.y};
        const ignoredAsteroids = new Set();
        const ignoredShips = new Set();

        // A single animation step can contain more than one collision after a
        // bounce. Rebuild the remaining swept segment after every interaction so
        // the bullet can cut, ricochet, and reach another body immediately.
        for (
            let interactionIndex = 0;
            interactionIndex < 16;
            interactionIndex += 1
        ) {
            const bulletMinimumX = Math.min(segmentStart.x, segmentEnd.x);
            const bulletMaximumX = Math.max(segmentStart.x, segmentEnd.x);
            const bulletMinimumY = Math.min(segmentStart.y, segmentEnd.y);
            const bulletMaximumY = Math.max(segmentStart.y, segmentEnd.y);
            let hitTarget = undefined;
            let nearestHitParameter = Infinity;

            for (const asteroid of physicalTargets()) {
                if (
                    ignoredAsteroids.has(asteroid) ||
                    bulletMaximumX < asteroid.x - asteroid.radius ||
                    bulletMinimumX > asteroid.x + asteroid.radius ||
                    bulletMaximumY < asteroid.y - asteroid.radius ||
                    bulletMinimumY > asteroid.y + asteroid.radius
                ) {
                    continue;
                }

                const hitParameter = segmentPolygonIntersectionParameter(
                    segmentStart,
                    segmentEnd,
                    asteroid.collisionPolygon(),
                );

                if (hitParameter !== undefined && hitParameter < nearestHitParameter) {
                    nearestHitParameter = hitParameter;
                    hitTarget = asteroid;
                }
            }

            const wallHit = boundaryHit(
                segmentStart,
                segmentEnd,
                width,
                height,
            );
            let ship = undefined;
            let shipHitParameter = undefined;
            for (const candidate of starships) {
                if (!candidate.alive || ignoredShips.has(candidate)) continue;
                const parameter = segmentCircleIntersectionParameter(
                    segmentStart,
                    segmentEnd,
                    candidate,
                );
                if (
                    parameter !== undefined &&
                    parameter < (shipHitParameter ?? Infinity)
                ) {
                    ship = candidate;
                    shipHitParameter = parameter;
                }
            }
            const shipIsFirst =
                shipHitParameter !== undefined &&
                shipHitParameter < nearestHitParameter &&
                shipHitParameter <= (wallHit?.parameter ?? Infinity);
            const asteroidIsFirst =
                hitTarget !== undefined &&
                !shipIsFirst &&
                nearestHitParameter <= (wallHit?.parameter ?? Infinity);
            const bodyIsFirst = asteroidIsFirst || shipIsFirst;

            if (!bodyIsFirst && wallHit === undefined) {
                break;
            }

            const hitParameter = asteroidIsFirst
                ? nearestHitParameter
                : shipIsFirst
                    ? shipHitParameter
                    : wallHit.parameter;
            const hitPoint = {
                x: segmentStart.x + (segmentEnd.x - segmentStart.x) * hitParameter,
                y: segmentStart.y + (segmentEnd.y - segmentStart.y) * hitParameter,
            };
            const remainingDistance =
                Math.hypot(
                    segmentEnd.x - segmentStart.x,
                    segmentEnd.y - segmentStart.y,
                ) *
                (1 - hitParameter);
            // Every pulse applies the same impact response. Borg pulses are
            // consumed immediately afterward; starship pulses may ricochet.
            const canReflect =
                bullet.source !== "borg" &&
                bullet.reflectionCount < MAX_BULLET_REFLECTIONS;

            let normal = bodyIsFirst ? undefined : wallHit.normal;
            let interactionBeforeEnergy = bodyKineticEnergy(bullet);
            let interactionAfterEnergy = interactionBeforeEnergy;
            let removedEnergy = 0;

            if (
                asteroidIsFirst &&
                hitTarget instanceof BorgCube &&
                hitTarget.alive
            ) {
                // Absorption transfers the disappearing pulse's linear and angular
                // impulse into the hull through the same rigid-body impulse helper.
                applyBodyImpulse(
                    hitTarget,
                    bullet.mass * bullet.velocityX,
                    bullet.mass * bullet.velocityY,
                    hitPoint,
                );
                hitTarget.hitPhaser(hitPoint);
                // Borg shields absorb the pulse. Existing rock, ship and wall
                // ricochets retain their normal finite reflection behavior.
                bullets.splice(bulletIndex, 1);
                break;
            } else if (asteroidIsFirst) {
                const asteroid = hitTarget;
                bullet.x = hitPoint.x;
                bullet.y = hitPoint.y;
                const beforeEnergy =
                    bodyKineticEnergy(asteroid) + bodyKineticEnergy(bullet);
                interactionBeforeEnergy = beforeEnergy;

                normal = polygonNormalAtPoint(
                    asteroid.collisionPolygon(),
                    hitPoint,
                    bullet.velocityX,
                    bullet.velocityY,
                );
                const incomingDirection = normalizedVector(
                    bullet.velocityX,
                    bullet.velocityY,
                );
                const response = applyContactImpulse(
                    asteroid,
                    bullet,
                    normal,
                    hitPoint,
                );
                if (!(asteroid instanceof BorgCube) && bullet.source === "starship")
                    recordAsteroidDamage(response, "blasters");
                bullet.syncAngle();
                if (canReflect) {
                    bullet.recordReflection();
                }
                // A wreck is a solid reflector, never a cuttable asteroid. Enemy
                // and player pulses otherwise share the complete ricochet path.
                const fragments =
                    asteroid instanceof BorgCube
                        ? [asteroid]
                        : fragmentAsteroidAtImpact(
                            asteroid,
                            hitPoint,
                            incomingDirection,
                            response,
                            "phaser",
                        );
                const afterEnergy = fragments.reduce(
                    (energy, fragment) => energy + bodyKineticEnergy(fragment),
                    bodyKineticEnergy(bullet),
                );
                interactionAfterEnergy = afterEnergy;
                for (const fragment of fragments) {
                    ignoredAsteroids.add(fragment);
                }
            } else if (shipIsFirst) {
                bullet.x = hitPoint.x;
                bullet.y = hitPoint.y;
                const beforeEnergy =
                    bodyKineticEnergy(ship) + bodyKineticEnergy(bullet);
                interactionBeforeEnergy = beforeEnergy;

                normal = circleNormalAtPoint(
                    ship,
                    hitPoint,
                    bullet.velocityX,
                    bullet.velocityY,
                );
                const bulletImpulse = applyContactImpulse(
                    ship,
                    bullet,
                    normal,
                    hitPoint,
                );
                applyShipCollisionAngleAdjustment(bulletImpulse, ship);
                ship.applyWeaponDamage(contactImpulseMagnitude(bulletImpulse));
                // Only the lethal weapon hit earns a combat badge. Helpers
                // lost to other causes and damage to the player do not qualify.
                if (ship !== playerShip && !ship.alive) {
                    roundAchievements.add(
                        bullet.source === "borg" ? "wolf-359" : "friendly-fire",
                    );
                }
                if (bulletImpulse.normalImpulse > COLLISION_EPSILON) {
                    empSound.playRandom();
                }
                bullet.syncAngle();

                if (canReflect) {
                    bullet.recordReflection();
                }

                const afterEnergy = bodyKineticEnergy(ship) + bodyKineticEnergy(bullet);
                interactionAfterEnergy = afterEnergy;
                ignoredShips.add(ship);
            }

            if (!canReflect) {
                removedEnergy += bodyKineticEnergy(bullet);
                emitSparksAt(
                    hitPoint,
                    interactionKineticEnergyLoss(
                        interactionBeforeEnergy,
                        interactionAfterEnergy,
                        removedEnergy,
                    ),
                );
                bullets.splice(bulletIndex, 1);
                break;
            }

            if (!bodyIsFirst) {
                bullet.reflect(normal);
                interactionAfterEnergy = bodyKineticEnergy(bullet);
            }
            emitSparksAt(
                hitPoint,
                interactionKineticEnergyLoss(
                    interactionBeforeEnergy,
                    interactionAfterEnergy,
                    removedEnergy,
                ),
            );
            const direction = normalizedVector(
                bullet.velocityX,
                bullet.velocityY,
            );
            const travelDistance = Math.max(
                0,
                remainingDistance - BULLET_COLLISION_OFFSET,
            );
            segmentStart = {
                x: hitPoint.x + direction.x * BULLET_COLLISION_OFFSET,
                y: hitPoint.y + direction.y * BULLET_COLLISION_OFFSET,
            };
            segmentEnd = {
                x: segmentStart.x + direction.x * travelDistance,
                y: segmentStart.y + direction.y * travelDistance,
            };
        }

        if (bullets[bulletIndex] === bullet) {
            bullet.previousX = bullet.x;
            bullet.previousY = bullet.y;
            bullet.x = segmentEnd.x;
            bullet.y = segmentEnd.y;
        }
    }
}

function polygonAxes(vertices) {
    const axes = [];

    for (let vertexIndex = 0; vertexIndex < vertices.length; vertexIndex += 1) {
        const firstVertex = vertices[vertexIndex];
        const secondVertex = vertices[(vertexIndex + 1) % vertices.length];
        const edgeX = secondVertex.x - firstVertex.x;
        const edgeY = secondVertex.y - firstVertex.y;
        const edgeLength = Math.hypot(edgeX, edgeY);

        if (edgeLength <= COLLISION_EPSILON) {
            continue;
        }

        axes.push({x: -edgeY / edgeLength, y: edgeX / edgeLength});
    }

    return axes;
}

function projectPolygon(vertices, axis) {
    let minimum = vertices[0].x * axis.x + vertices[0].y * axis.y;
    let maximum = minimum;

    for (let vertexIndex = 1; vertexIndex < vertices.length; vertexIndex += 1) {
        const vertex = vertices[vertexIndex];
        const projection = vertex.x * axis.x + vertex.y * axis.y;
        minimum = Math.min(minimum, projection);
        maximum = Math.max(maximum, projection);
    }

    return {minimum, maximum};
}

function projectCircle(body, axis) {
    const centerProjection = body.x * axis.x + body.y * axis.y;

    return {
        minimum: centerProjection - body.radius,
        maximum: centerProjection + body.radius,
    };
}

/** @param {Vector2[]} vertices @param {Vector2} direction @returns {Vector2} */
function supportPoint(vertices, direction) {
    const supportTolerance = COLLISION_EPSILON * 100;
    let greatestProjection = -Infinity;
    let supportX = 0;
    let supportY = 0;
    let supportCount = 0;

    for (const vertex of vertices) {
        const projection = vertex.x * direction.x + vertex.y * direction.y;

        if (projection > greatestProjection + supportTolerance) {
            greatestProjection = projection;
            supportX = vertex.x;
            supportY = vertex.y;
            supportCount = 1;
        } else if (Math.abs(projection - greatestProjection) <= supportTolerance) {
            supportX += vertex.x;
            supportY += vertex.y;
            supportCount += 1;
        }
    }

    return {
        x: supportX / supportCount,
        y: supportY / supportCount,
    };
}

/**
 * @param {PhysicsBody} firstBody
 * @param {PhysicsBody} secondBody
 * @param {Vector2} normal
 * @param {Vector2[]} [firstVertices]
 * @param {Vector2[]} [secondVertices]
 * @returns {Vector2}
 */
function contactPointForBodies(
    firstBody,
    secondBody,
    normal,
    firstVertices,
    secondVertices,
) {
    const firstPoint =
        firstVertices === undefined
            ? {
                x: firstBody.x + normal.x * firstBody.radius,
                y: firstBody.y + normal.y * firstBody.radius,
            }
            : supportPoint(firstVertices, normal);
    const secondPoint =
        secondVertices === undefined
            ? {
                x: secondBody.x - normal.x * secondBody.radius,
                y: secondBody.y - normal.y * secondBody.radius,
            }
            : supportPoint(secondVertices, {x: -normal.x, y: -normal.y});

    return {
        x: (firstPoint.x + secondPoint.x) / 2,
        y: (firstPoint.y + secondPoint.y) / 2,
    };
}

/**
 * Return the translation needed to separate two one-dimensional projections.
 * The two directional distances matter when one convex shape contains the
 * other; the ordinary intersection width would under-correct that contact.
 */
function projectionOverlap(firstProjection, secondProjection) {
    const moveFirstNegative = firstProjection.maximum - secondProjection.minimum;
    const moveFirstPositive = secondProjection.maximum - firstProjection.minimum;

    return Math.min(moveFirstNegative, moveFirstPositive);
}

function collisionAxis(firstBody, secondBody, axis, firstShape, secondShape) {
    const firstProjection =
        firstShape.type === "polygon"
            ? projectPolygon(firstShape.vertices, axis)
            : projectCircle(firstBody, axis);
    const secondProjection =
        secondShape.type === "polygon"
            ? projectPolygon(secondShape.vertices, axis)
            : projectCircle(secondBody, axis);
    const overlap = projectionOverlap(firstProjection, secondProjection);

    return overlap < -COLLISION_EPSILON ? undefined : overlap;
}

function orientCollisionAxis(firstBody, secondBody, axis) {
    const centerOffsetX = secondBody.x - firstBody.x;
    const centerOffsetY = secondBody.y - firstBody.y;
    const centerDirection = centerOffsetX * axis.x + centerOffsetY * axis.y;

    if (centerDirection < -COLLISION_EPSILON) {
        return {x: -axis.x, y: -axis.y};
    }

    if (Math.abs(centerDirection) <= COLLISION_EPSILON) {
        // When the selected edge normal is perpendicular to the center offset,
        // relative motion provides a stable sign. Coincident centers use the same
        // deterministic first-minus-second fallback as the original solver.
        const relativeDirection = normalizedVector(
            firstBody.velocityX - secondBody.velocityX,
            firstBody.velocityY - secondBody.velocityY,
        );

        if (relativeDirection.x * axis.x + relativeDirection.y * axis.y < 0) {
            return {x: -axis.x, y: -axis.y};
        }
    }

    return axis;
}

/**
 * @param {PhysicsBody} firstBody
 * @param {PhysicsBody} secondBody
 * @param {Vector2[]} firstVertices
 * @param {Vector2[]} secondVertices
 * @returns {CollisionManifold | undefined}
 */
function polygonPolygonManifold(
    firstBody,
    secondBody,
    firstVertices,
    secondVertices,
) {
    // For convex polygons, separating axes are perpendicular to every edge of
    // either polygon. A gap on any one of them proves that the shapes do not
    // touch; the smallest overlap is the contact penetration used by physics.
    // Walk the cached lists directly without copying them for every SAT test.
    const firstAxes = firstBody.collisionAxes ?? polygonAxes(firstVertices);
    const secondAxes = secondBody.collisionAxes ?? polygonAxes(secondVertices);
    let minimumPenetration = Infinity;
    let minimumAxis = firstAxes[0];
    const firstShape = {type: "polygon", vertices: firstVertices};
    const secondShape = {type: "polygon", vertices: secondVertices};

    for (
        let axisIndex = 0;
        axisIndex < firstAxes.length + secondAxes.length;
        axisIndex += 1
    ) {
        const axis =
            axisIndex < firstAxes.length
                ? firstAxes[axisIndex]
                : secondAxes[axisIndex - firstAxes.length];
        const overlap = collisionAxis(
            firstBody,
            secondBody,
            axis,
            firstShape,
            secondShape,
        );

        if (overlap === undefined) {
            return undefined;
        }

        if (overlap < minimumPenetration) {
            minimumPenetration = overlap;
            minimumAxis = axis;
        }
    }

    const normal = orientCollisionAxis(firstBody, secondBody, minimumAxis);

    return {
        normal,
        penetration: Math.max(0, minimumPenetration),
        contactPoint: contactPointForBodies(
            firstBody,
            secondBody,
            normal,
            firstVertices,
            secondVertices,
        ),
    };
}

function closestPointOnSegment(point, firstPoint, secondPoint) {
    const segmentX = secondPoint.x - firstPoint.x;
    const segmentY = secondPoint.y - firstPoint.y;
    const segmentLengthSquared = segmentX ** 2 + segmentY ** 2;

    if (segmentLengthSquared <= COLLISION_EPSILON ** 2) {
        return firstPoint;
    }

    const pointAlongSegment = Math.min(
        1,
        Math.max(
            0,
            ((point.x - firstPoint.x) * segmentX +
                (point.y - firstPoint.y) * segmentY) /
            segmentLengthSquared,
        ),
    );

    return {
        x: firstPoint.x + segmentX * pointAlongSegment,
        y: firstPoint.y + segmentY * pointAlongSegment,
    };
}

function closestPointOnPolygon(point, vertices) {
    let closestPoint = vertices[0];
    let closestDistanceSquared = Infinity;

    for (let vertexIndex = 0; vertexIndex < vertices.length; vertexIndex += 1) {
        const firstVertex = vertices[vertexIndex];
        const secondVertex = vertices[(vertexIndex + 1) % vertices.length];
        const candidate = closestPointOnSegment(
            point,
            firstVertex,
            secondVertex,
        );
        const distanceX = candidate.x - point.x;
        const distanceY = candidate.y - point.y;
        const distanceSquared = distanceX ** 2 + distanceY ** 2;

        if (distanceSquared < closestDistanceSquared) {
            closestDistanceSquared = distanceSquared;
            closestPoint = candidate;
        }
    }

    return closestPoint;
}

/**
 * @param {PhysicsBody} circleBody
 * @param {PhysicsBody} polygonBody
 * @param {Vector2[]} polygonVertices
 * @returns {CollisionManifold | undefined}
 */
function circlePolygonManifold(circleBody, polygonBody, polygonVertices) {
    const axes = polygonBody.collisionAxes ?? polygonAxes(polygonVertices);
    const closestPoint = closestPointOnPolygon(
        {x: circleBody.x, y: circleBody.y},
        polygonVertices,
    );
    const closestPointAxis = normalizedVector(
        closestPoint.x - circleBody.x,
        closestPoint.y - circleBody.y,
        1,
        0,
    );

    const axisCount =
        axes.length +
        Number(
            Math.hypot(
                closestPoint.x - circleBody.x,
                closestPoint.y - circleBody.y,
            ) > COLLISION_EPSILON,
        );

    let minimumPenetration = Infinity;
    let minimumAxis = axes[0];
    const circleShape = {type: "circle"};
    const polygonShape = {type: "polygon", vertices: polygonVertices};

    for (let axisIndex = 0; axisIndex < axisCount; axisIndex += 1) {
        // The closest-point axis completes circle/polygon SAT without appending
        // temporary data to the asteroid's immutable cached edge-axis list.
        const axis = axisIndex < axes.length ? axes[axisIndex] : closestPointAxis;
        const overlap = collisionAxis(
            circleBody,
            polygonBody,
            axis,
            circleShape,
            polygonShape,
        );

        if (overlap === undefined) {
            return undefined;
        }

        if (overlap < minimumPenetration) {
            minimumPenetration = overlap;
            minimumAxis = axis;
        }
    }

    const normal = orientCollisionAxis(circleBody, polygonBody, minimumAxis);

    return {
        normal,
        penetration: Math.max(0, minimumPenetration),
        contactPoint: contactPointForBodies(
            circleBody,
            polygonBody,
            normal,
            undefined,
            polygonVertices,
        ),
    };
}

function invertedManifold(manifold) {
    return {
        normal: {x: -manifold.normal.x, y: -manifold.normal.y},
        penetration: manifold.penetration,
        contactPoint: manifold.contactPoint,
    };
}

function collisionManifold(firstBody, secondBody) {
    const firstVertices = firstBody.collisionPolygon?.();
    const secondVertices = secondBody.collisionPolygon?.();
    const firstIsPolygon = firstVertices !== undefined;
    const secondIsPolygon = secondVertices !== undefined;

    if (firstIsPolygon && secondIsPolygon) {
        return polygonPolygonManifold(
            firstBody,
            secondBody,
            firstVertices,
            secondVertices,
        );
    }

    if (!firstIsPolygon && secondIsPolygon) {
        return circlePolygonManifold(firstBody, secondBody, secondVertices);
    }

    if (firstIsPolygon && !secondIsPolygon) {
        const manifold = circlePolygonManifold(
            secondBody,
            firstBody,
            firstVertices,
        );

        return manifold === undefined ? undefined : invertedManifold(manifold);
    }

    // Two shield circles use their center axis. Coincident centers fall back
    // to relative motion, then +x, avoiding division by zero deterministically.
    const x = secondBody.x - firstBody.x;
    const y = secondBody.y - firstBody.y;
    const distance = Math.hypot(x, y);
    const penetration = firstBody.radius + secondBody.radius - distance;
    if (penetration < -COLLISION_EPSILON) return undefined;
    const fallback = normalizedVector(
        firstBody.velocityX - secondBody.velocityX,
        firstBody.velocityY - secondBody.velocityY,
    );
    const normal = normalizedVector(x, y, fallback.x, fallback.y);
    const firstRim = firstBody.radius - Math.max(0, penetration) / 2;
    return {
        normal,
        penetration: Math.max(0, penetration),
        contactPoint: {
            x: firstBody.x + normal.x * firstRim,
            y: firstBody.y + normal.y * firstRim,
        },
    };
}

/**
 * Resolve a convex-shape contact with a single shared contact point. Equal
 * and opposite impulses at that point preserve total angular momentum for an
 * isolated asteroid pair, while the restitution and friction coefficients
 * account for the energy dissipated by a non-ideal collision.
 */
/**
 * @param {PhysicsBody} firstBody
 * @param {PhysicsBody} secondBody
 * @param {CollisionManifold} [existingManifold] Precomputed contact geometry.
 * @returns {ContactResponse | undefined} Contact response, or undefined when
 *   the bodies do not overlap.
 */
function resolveCollision(firstBody, secondBody, existingManifold) {
    const manifold = existingManifold ?? collisionManifold(firstBody, secondBody);

    if (manifold === undefined) {
        return undefined;
    }

    const {normal, penetration, contactPoint} = manifold;
    const offsetX = normal.x;
    const offsetY = normal.y;

    const inverseFirstMass = bodyInverseMass(firstBody);
    const inverseSecondMass = bodyInverseMass(secondBody);
    const inverseMassSum = inverseFirstMass + inverseSecondMass;
    const angularMomentumBeforeSeparation =
        bodyAngularMomentum(firstBody) + bodyAngularMomentum(secondBody);

    // Separate overlap proportionally to inverse mass. This keeps a large
    // asteroid from teleporting the ship while preventing repeated impulses
    // from a body that remains embedded after a large animation frame.
    if (penetration > 0) {
        const separation = penetration / inverseMassSum;
        firstBody.x -= offsetX * separation * inverseFirstMass;
        firstBody.y -= offsetY * separation * inverseFirstMass;
        secondBody.x += offsetX * separation * inverseSecondMass;
        secondBody.y += offsetY * separation * inverseSecondMass;
        restoreAngularMomentumAfterPositionCorrection(
            firstBody,
            secondBody,
            angularMomentumBeforeSeparation,
        );
    }

    const response = applyContactImpulse(
        firstBody,
        secondBody,
        {
            x: offsetX,
            y: offsetY,
        },
        contactPoint,
    );

    return response;
}

/**
 * Resolve both rocks before cutting either one. Equal and opposite impulses
 * have the same magnitude, so one sufficiently strong contact splits both
 * rocks, regardless of their masses. Each inherits its own post-impact motion.
 * @param {Asteroid} firstAsteroid First rock in the contact pair.
 * @param {Asteroid} secondAsteroid Second rock in the contact pair.
 * @param {Set<Asteroid>} fragmentedAsteroids Parents excluded from later contacts.
 * @returns {void}
 */
function resolveAsteroidPairCollision(
    firstAsteroid,
    secondAsteroid,
    fragmentedAsteroids,
) {
    const manifold = collisionManifold(firstAsteroid, secondAsteroid);

    if (manifold === undefined) {
        return;
    }

    const beforeEnergy =
        bodyKineticEnergy(firstAsteroid) + bodyKineticEnergy(secondAsteroid);
    const response = resolveCollision(firstAsteroid, secondAsteroid, manifold);

    if (response !== undefined) {
        const firstFragments = fragmentAsteroidAtImpact(
            firstAsteroid,
            manifold.contactPoint,
            manifold.normal,
            response,
            "body",
        );
        const secondFragments = fragmentAsteroidAtImpact(
            secondAsteroid,
            manifold.contactPoint,
            manifold.normal,
            response,
            "body",
        );
        if (!firstFragments.includes(firstAsteroid)) {
            fragmentedAsteroids.add(firstAsteroid);
        }
        if (!secondFragments.includes(secondAsteroid)) {
            fragmentedAsteroids.add(secondAsteroid);
        }
        const afterEnergy =
            firstFragments.reduce(
                (energy, fragment) => energy + bodyKineticEnergy(fragment),
                0,
            ) +
            secondFragments.reduce(
                (energy, fragment) => energy + bodyKineticEnergy(fragment),
                0,
            );
        emitSparksAt(
            manifold.contactPoint,
            interactionKineticEnergyLoss(beforeEnergy, afterEnergy),
        );
    }
}

/**
 * Resolve a stable list of parents so replacing either member of a pair never
 * skips unrelated rocks or recursively shatters fresh fragments. Pieces made
 * in this pass join body contacts next frame with the already-solved motion.
 * @returns {void}
 */
function resolveAsteroidCollisions() {
    const contactAsteroids = asteroids.slice();
    const fragmentedAsteroids = new Set();

    for (
        let firstIndex = 0;
        firstIndex < contactAsteroids.length;
        firstIndex += 1
    ) {
        const firstAsteroid = contactAsteroids[firstIndex];

        for (
            let secondIndex = firstIndex + 1;
            secondIndex < contactAsteroids.length;
            secondIndex += 1
        ) {
            if (fragmentedAsteroids.has(firstAsteroid)) {
                break;
            }
            const secondAsteroid = contactAsteroids[secondIndex];

            if (
                fragmentedAsteroids.has(secondAsteroid) ||
                !bodiesMayOverlap(firstAsteroid, secondAsteroid)
            ) {
                continue;
            }

            resolveAsteroidPairCollision(
                firstAsteroid,
                secondAsteroid,
                fragmentedAsteroids,
            );
        }
    }

    for (const ship of starships) {
        if (!ship.alive) continue;
        for (
            let asteroidIndex = contactAsteroids.length - 1;
            asteroidIndex >= 0;
            asteroidIndex -= 1
        ) {
            const asteroid = contactAsteroids[asteroidIndex];
            if (
                !asteroids.includes(asteroid) ||
                fragmentedAsteroids.has(asteroid) ||
                !bodiesMayOverlap(ship, asteroid)
            ) {
                continue;
            }

            const manifold = collisionManifold(ship, asteroid);

            if (manifold === undefined) {
                continue;
            }

            const beforeEnergy =
                bodyKineticEnergy(ship) + bodyKineticEnergy(asteroid);
            const response = resolveCollision(ship, asteroid, manifold);

            if (response !== undefined) {
                ship.applyCollisionDamage(contactImpulseMagnitude(response));
                if (response.normalImpulse > COLLISION_EPSILON) {
                    recordAsteroidDamage(response, "ramming");
                    empSound.playRandom();
                }
                const fragments = fragmentAsteroidAtImpact(
                    asteroid,
                    manifold.contactPoint,
                    manifold.normal,
                    response,
                    "body",
                );
                const afterEnergy = fragments.reduce(
                    (energy, fragment) => energy + bodyKineticEnergy(fragment),
                    bodyKineticEnergy(ship),
                );
                // Removed material joins the sparks for every impact source.
                emitSparksAt(
                    manifold.contactPoint,
                    interactionKineticEnergyLoss(beforeEnergy, afterEnergy),
                );
                applyShipCollisionAngleAdjustment(response, ship);
            }
        }
    }

    // Both rock and cube contacts consume one parent snapshot. Children created
    // by either kind of physical contact join the next frame's body pass.
    resolveBorgCollisions(
        contactAsteroids.filter((rock) => asteroids.includes(rock)),
    );
}

/**
 * Keep cube contacts on the same impulse and fragmentation paths as rocks.
 * Hull damage uses actual normal contact response; fresh fragments wait until
 * the next body pass. Both the live cube and its intact wreck stay physical.
 * @param {Asteroid[]} [contactAsteroids] Surviving parents from the shared pass.
 * @returns {void}
 */
function resolveBorgCollisions(contactAsteroids = asteroids.slice()) {
    for (let first = 0; first < borgCubes.length; first += 1) {
        const cube = borgCubes[first];
        for (let second = first + 1; second < borgCubes.length; second += 1) {
            const other = borgCubes[second];
            if (!bodiesMayOverlap(cube, other)) continue;
            const manifold = collisionManifold(cube, other);
            if (manifold === undefined) continue;
            // Collective contacts still separate solid hulls and transfer momentum,
            // but never consume shields, hull health, or contact damage budgets.
            resolveCollision(cube, other, manifold);
        }
    }
    for (const cube of borgCubes) {
        for (const ship of starships) {
            if (!ship.alive) continue;
            const shipManifold = bodiesMayOverlap(ship, cube)
                ? collisionManifold(ship, cube)
                : undefined;
            if (shipManifold !== undefined) {
                const response = resolveCollision(ship, cube, shipManifold);
                if (response !== undefined) {
                    const impulse = contactImpulseMagnitude(response);
                    ship.applyCollisionDamage(impulse);
                    // Cube hulls remain dangerous after defeat, so lethal
                    // helper collisions with live cubes or wrecks qualify.
                    if (ship !== playerShip && !ship.alive) {
                        roundAchievements.add("wolf-359");
                    }
                    applyShipCollisionAngleAdjustment(response, ship);
                    cube.hitBody(impulse, shipManifold.contactPoint);
                }
            }
        }
        for (const rock of contactAsteroids) {
            if (!asteroids.includes(rock) || !bodiesMayOverlap(cube, rock)) continue;
            const manifold = collisionManifold(cube, rock);
            if (manifold === undefined) continue;
            const beforeEnergy = bodyKineticEnergy(cube) + bodyKineticEnergy(rock);
            const response = resolveCollision(cube, rock, manifold);
            if (response === undefined) continue;
            cube.hitBody(
                contactImpulseMagnitude(response),
                manifold.contactPoint,
            );
            const fragments = fragmentAsteroidAtImpact(
                rock,
                manifold.contactPoint,
                manifold.normal,
                response,
                "body",
            );
            const afterEnergy = fragments.reduce(
                (energy, fragment) => energy + bodyKineticEnergy(fragment),
                bodyKineticEnergy(cube),
            );
            emitSparksAt(
                manifold.contactPoint,
                interactionKineticEnergyLoss(beforeEnergy, afterEnergy),
            );
        }
    }
}

/**
 * Friendly hulls remain physical. Apply the same impulse and damage model to
 * both ships without treating their contact as asteroid fragmentation.
 * @returns {void}
 */
function resolveStarshipCollisions() {
    for (let first = 0; first < starships.length; first += 1) {
        const ship = starships[first];
        if (!ship.alive) continue;
        for (let second = first + 1; second < starships.length; second += 1) {
            const other = starships[second];
            if (!other.alive || !bodiesMayOverlap(ship, other)) continue;
            const manifold = collisionManifold(ship, other);
            if (manifold === undefined) continue;
            const response = resolveCollision(ship, other, manifold);
            if (response === undefined) continue;
            const impulse = contactImpulseMagnitude(response);
            ship.applyCollisionDamage(impulse);
            other.applyCollisionDamage(impulse);
            applyShipCollisionAngleAdjustment(response, ship);
            applyShipCollisionAngleAdjustment(
                {
                    ...response,
                    firstAngularImpulse: response.secondAngularImpulse,
                },
                other,
            );
        }
    }
}

function bodiesMayOverlap(firstBody, secondBody) {
    const distanceX = secondBody.x - firstBody.x;
    const distanceY = secondBody.y - firstBody.y;
    const radiusSum = firstBody.radius + secondBody.radius;

    return distanceX ** 2 + distanceY ** 2 <= radiusSum ** 2;
}

/**
 * Read opposite steering keys as a single direction, with aliases sharing
 * one ramp and simultaneous CW/CCW inputs cancelling each other.
 * @param {Set<string>} keys Held controls from one input source.
 * @returns {number} -1 for CCW, 0 for no turn, or 1 for CW.
 */
function turnDirectionForKeys(keys) {
    const turnsCounterClockwise = keys.has("ArrowLeft") || keys.has("KeyA");
    const turnsClockwise = keys.has("ArrowRight") || keys.has("KeyD");
    return Number(turnsClockwise) - Number(turnsCounterClockwise);
}

/**
 * Reuse autopilot wall navigation: brake outward drift, face an escape lane,
 * then thrust away. Preserve a nose already aimed inward instead of turning it.
 * @param {Starship} ship Hull receiving ordinary flight inputs.
 * @param {Set<string>} input Keys produced by this navigation controller.
 * @param {{desiredAngle: number, brake: boolean}} wall Shared wall response.
 * @returns {number} Heading used to steer and align escape thrust.
 */
function applyWallAvoidanceInput(ship, input, wall) {
    const facingInward = Math.cos(ship.angle - wall.desiredAngle) > 0.5;
    const desiredAngle = facingInward ? ship.angle : wall.desiredAngle;
    if (wall.brake) {
        input.add("KeyS");
    } else if (
        Math.abs(shortestAngleDifference(desiredAngle, ship.angle)) <=
        AUTOPILOT_THRUST_ALIGNMENT_TOLERANCE
    ) {
        input.add("KeyW");
    }
    return desiredAngle;
}

/**
 * Borrow wall avoidance without enabling combat navigation. Trigger only on
 * outward travel, then commit through the low-speed turn and escape thrust.
 * Release after inward velocity reaches the autopilot's safe coast speed.
 * Ordinary manual helm inputs resume unchanged afterward; firing stays live.
 * @param {Starship} ship Player hull receiving temporary navigation assistance.
 * @param {number} deltaTime Bounded simulation step in seconds.
 * @param {number} width Arena width in CSS pixels.
 * @param {number} height Arena height in CSS pixels.
 * @returns {void}
 */
function updateWallAvoidance(ship, deltaTime, width, height) {
    const controls = ship.controls;
    controls.wallAvoidancePressedKeys.clear();
    const wall = autopilotWallThreat(ship, width, height, deltaTime);
    if (controls.autopilotEnabled) {
        controls.wallAvoidanceActive = false;
        syncPressedKeys(ship);
        return;
    }
    if (!controls.wallAvoidanceActive && wall !== undefined) {
        const inwardSpeed =
            ship.velocityX * Math.cos(wall.desiredAngle) +
            ship.velocityY * Math.sin(wall.desiredAngle);
        if (inwardSpeed < -COLLISION_EPSILON) {
            controls.wallAvoidanceActive = true;
            controls.wallAvoidanceEscapeAngle = wall.desiredAngle;
        }
    }
    if (controls.wallAvoidanceActive) {
        // A new corner threat may add a second inward normal during escape.
        if (wall !== undefined && wall.brake)
            controls.wallAvoidanceEscapeAngle = wall.desiredAngle;
        const inwardSpeed =
            ship.velocityX * Math.cos(controls.wallAvoidanceEscapeAngle) +
            ship.velocityY * Math.sin(controls.wallAvoidanceEscapeAngle);
        if (inwardSpeed >= AUTOPILOT_MIN_COAST_SPEED) {
            controls.wallAvoidanceActive = false;
        } else {
            controls.wallAvoidanceDesiredAngle = applyWallAvoidanceInput(
                ship,
                controls.wallAvoidancePressedKeys,
                {
                    desiredAngle: controls.wallAvoidanceEscapeAngle,
                    brake: inwardSpeed < -COLLISION_EPSILON,
                },
            );
            const error = shortestAngleDifference(
                controls.wallAvoidanceDesiredAngle,
                ship.angle,
            );
            if (Math.abs(error) > COLLISION_EPSILON) {
                controls.wallAvoidancePressedKeys.add(
                    error > 0 ? "KeyD" : "KeyA",
                );
            }
        }
    }
    syncPressedKeys(ship);
}

/**
 * Apply the shared turn control's displacement, releasing an assisted press
 * exactly at its target rather than taking an extra frame past parallel.
 * Manual input has no target limit and uses the same speed and ramp.
 * @param {Starship} ship Hull receiving ordinary rotation input.
 * @param {number} displacement Signed turn integrated from held A/D input.
 * @returns {void}
 */
function applyTurnInput(ship, displacement) {
    const target = ship.controls.turnTargetAngle;
    const error =
        target === undefined
            ? displacement
            : shortestAngleDifference(target, ship.angle);
    ship.angle = wrapAngle(
        ship.angle +
            Math.sign(displacement) *
                Math.min(Math.abs(displacement), Math.abs(error)),
    );
}

/**
 * Consume merged flight inputs. Manual and wall avoidance A/D presses use the same
 * ramped turn control; autopilot keeps its existing navigation turn behavior.
 * @param {Starship} ship Hull receiving ordinary brake, thrust, and turn inputs.
 * @param {number} deltaTime Bounded simulation step in seconds.
 * @returns {void}
 */
function applyFlightInput(ship, deltaTime) {
    const controls = ship.controls;
    const manuallySteering = ["KeyA", "KeyD", "ArrowLeft", "ArrowRight"].some(
        (key) => controls.manualPressedKeys.has(key),
    );
    applyTurnInput(ship, controls.manualTurnControl.advance(performance.now()));
    if (!manuallySteering && !controls.wallAvoidanceActive) {
        ship.angle = wrapAngle(
            ship.angle +
                turnDirectionForKeys(controls.pressedKeys) *
                    Math.min(
                        ROTATION_SPEED * deltaTime,
                        Math.abs(
                            shortestAngleDifference(
                                controls.automatedDesiredAngle,
                                ship.angle,
                            ),
                        ),
                    ),
        );
    }
    ship.applyThrottle(controls.pressedKeys, deltaTime);
}

/**
 * A/D and the left/right arrows gently ramp the ship's facing speed. Collision
 * friction applies separate one-time heading adjustments. The velocity vector
 * remains free, so a ship can drift sideways or backwards while its nose
 * controls firing and thrust. Down decelerates along the current travel vector
 * rather than steering the ship toward its nose.
 * @param {number} deltaTime Bounded simulation step in seconds.
 * @param {number} width Arena width in CSS pixels.
 * @param {number} height Arena height above the command strip in CSS pixels.
 * @returns {void}
 */
function updateGame(deltaTime, width, height) {
    updateStarfleetTactics(width, height);
    for (const ship of starships) {
        if (!ship.alive) continue;
        ship.refillCollisionDamageBudget(deltaTime);
        ship.regenerateShield(deltaTime);
        updateAutopilotInput(ship, deltaTime, width, height);

        if (ship === playerShip)
            updateWallAvoidance(ship, deltaTime, width, height);
        applyFlightInput(ship, deltaTime);
    }

    for (const asteroid of asteroids) {
        asteroid.update(width, height, deltaTime);
    }

    updateBorgHealthTransfers(deltaTime);
    updateBorgFleetTactics(width, height);
    for (const cube of borgCubes) cube.update(width, height, deltaTime);

    for (const ship of starships) {
        if (!ship.alive) continue;
        // The ship is a dynamic rigid body just like an asteroid. The wall callback
        // sends each shield contact through the shared normal/friction solver so a
        // tangential impact changes the ship's heading instead of only
        // reflecting its center-of-mass velocity.
        advanceAndReflect(
            ship,
            "x",
            "velocityX",
            ship.velocityX * deltaTime,
            STARSHIP_RADIUS,
            width - STARSHIP_RADIUS,
            BOUNCINESS,
            (normal) => resolveShipWallContact(ship, normal),
        );
        advanceAndReflect(
            ship,
            "y",
            "velocityY",
            ship.velocityY * deltaTime,
            STARSHIP_RADIUS,
            height - STARSHIP_RADIUS,
            BOUNCINESS,
            (normal) => resolveShipWallContact(ship, normal),
        );

        updateAutoGunnerFiring(ship);
        updateBulletFiring(ship, deltaTime);
    }
    updateBullets(deltaTime);
    resolveBulletCollisions(width, height);
    resolveAsteroidCollisions();
    resolveStarshipCollisions();
    for (const ship of starships)
        if (ship.alive) ship.aimAssist.update(deltaTime);
    if (
        starships.some((ship) => ship.alive) &&
        asteroids.length === 0 &&
        !borgCubes.some((cube) => cube.alive)
    ) {
        beginWin();
    }
}

/**
 * Publish alarms and the human hull's destruction screen through the bridge.
 * Fleet simulation does not choose which hull a human observes or controls.
 * @param {number} deltaTime Active simulation seconds since the last step.
 * @returns {void}
 */
function updateBridgeStatus(deltaTime) {
    updateAlert(playerShip, deltaTime);
    if (!playerShip.alive) beginShipFailure();
}

/**
 * Advance one coherent world snapshot, then render that same snapshot.
 *
 * `async` functions do not execute JavaScript concurrently: awaiting here
 * would only split this main-thread transaction and could make a renderer see
 * a half-resolved collision or an autopilot decision based on stale bodies.
 * A Web Worker would provide real parallelism, but it cannot share these
 * mutable objects with this direct-file page without copying the complete
 * world each frame (SharedArrayBuffer is unavailable without cross-origin
 * isolation). Copying adds work and asynchronous messages require a new
 * snapshot protocol to preserve ordered collision/health rules. Workers
 * remain an option if browser profiling justifies that architectural change;
 * first remove repeated geometry and paint setup from this frame transaction.
 * @param {number} frameTime Animation-frame timestamp in milliseconds.
 * @returns {void}
 */
function animate(frameTime) {
    if (
        previousFrameTime !== undefined &&
        frameTime - previousFrameTime > SOUND_WAKE_GAP_MILLISECONDS
    ) {
        recoverSound();
    }
    const deltaTime =
        previousFrameTime === undefined
            ? 0
            : Math.min(
                  (frameTime - previousFrameTime) / 1000,
                  MAX_SIMULATION_STEP,
              );
    previousFrameTime = frameTime;

    const width = viewportWidth;
    const height = viewportHeight;
    const gameplayHeight = gameplayHeightForViewport(height);
    generateAsteroids(width, gameplayHeight);
    if (shipFailureActive) {
        updateShipFailure(deltaTime, width, gameplayHeight);
    } else if (!gamePaused) {
        updateGame(deltaTime, width, gameplayHeight);
        // Advance protection only after active simulation, including contacts.
        for (const ship of starships) {
            ship.spawnImmunityRemaining = Math.max(
                0,
                ship.spawnImmunityRemaining - deltaTime,
            );
        }
        updateBridgeStatus(deltaTime);
    }
    updateSparks(deltaTime);
    for (const ship of starships) updateDisplayedStatusBars(deltaTime, ship);
    drawGame(width, height);
    window.requestAnimationFrame(animate);
}

function controlKeyForEvent(event) {
    if (event.code === FIRE_KEY) {
        return FIRE_KEY;
    }

    if (event.key.startsWith("Arrow")) {
        return ["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(
            event.key,
        )
            ? event.key
            : undefined;
    }

    return ["KeyA", "KeyD", "KeyW", "KeyS"].includes(event.code)
        ? event.code
        : undefined;
}

document.addEventListener("keydown", (event) => {
    if (event.code === AIM_ASSIST_TOGGLE_KEY) {
        if (!event.repeat) playerShip.aimAssist.toggle();
        event.preventDefault();
        return;
    }

    if (event.code === AUTOPILOT_TOGGLE_KEY && !event.repeat) {
        unlockSound();
        toggleAutopilot(playerShip);
        event.preventDefault();
        return;
    }

    if (event.code === AUTO_GUNNER_TOGGLE_KEY) {
        if (!event.repeat) {
            unlockSound();
            toggleAutoGunner(playerShip);
        }
        event.preventDefault();
        return;
    }

    if (event.code === PAUSE_KEY && !event.repeat) {
        unlockSound();
        if (gameWon) {
            restartGame(
                viewportWidth,
                gameplayHeightForViewport(viewportHeight),
            );
            gamePaused = false;
        } else if (!shipFailureActive) {
            gamePaused = !gamePaused;
            if (gamePaused) {
                // A pause freezes gameplay input as well as simulation time. Requiring
                // a fresh Space press after resuming avoids a held key firing
                // unexpectedly.
                for (const ship of starships) clearPressedKeys(ship);
            }
        }

        event.preventDefault();
        return;
    }

    if (shipFailureActive) {
        event.preventDefault();
        return;
    }

    const controlKey = controlKeyForEvent(event);

    if (controlKey !== undefined) {
        unlockSound();
        event.preventDefault();

        disableAutomationForManualInput(playerShip, controlKey);

        if (gamePaused) {
            return;
        }

        if (controlKey === FIRE_KEY && !event.repeat) {
            tryFireBullet(playerShip);
        }
        playerShip.controls.manualPressedKeys.add(controlKey);
        syncPressedKeys(playerShip);
    }
});

document.addEventListener("keyup", (event) => {
    const controlKey = controlKeyForEvent(event);

    if (controlKey !== undefined) {
        playerShip.controls.manualPressedKeys.delete(controlKey);
        syncPressedKeys(playerShip);
    }
});

window.addEventListener("blur", () => {
    for (const ship of starships) clearPressedKeys(ship);
});

/**
 * Start with the styled canvas dimensions, then follow element layout changes.
 * A cold load can expose the canvas's default 300-by-150 size before the page
 * settles. Caching that size stretches the whole HUD and seeds a tiny arena.
 * Waiting for load avoids generating that world; observing the canvas catches
 * later layout changes even when no window resize event accompanies them.
 * @returns {void}
 */
function startGame() {
    const canvasResizeObserver = new ResizeObserver(resizeCanvas);
    canvasResizeObserver.observe(canvas);
    // Retain the window event for display-density changes, which can require a
    // new drawing buffer without changing the canvas's CSS dimensions.
    window.addEventListener("resize", resizeCanvas);
    resizeCanvas();
    window.requestAnimationFrame(animate);
}

if (document.readyState === "complete") {
    startGame();
} else {
    window.addEventListener("load", startGame, {once: true});
}
